window.__MLS101_MANIFEST__ = {"courseCode":"MLS101","courseTitle":"Medical Laboratory Science 101","programme":"Medical Laboratory Science","visibility":"programme-restricted","sourceFile":"MLS101_All_Lectures_Single_File.html","integrationNotes":"Source-derived lecture notes, flashcards and questions are mapped into Bablo Hub's existing course modules. Original lecture order and wording are retained.","lectures":[{"id":"mls101-lecture-01","order":1,"title":"Week 1: Laboratory Biorisk Management","notesHtml":"<div class=\"card\">\n    <h2>Learning objectives</h2>\n    <ul>\n      <li>Define laboratory biorisk management in your own words</li>\n      <li>Explain the basic concepts of laboratory hazards and how they arise</li>\n      <li>Identify the sources and types of biorisks in medical laboratories</li>\n      <li>Describe biorisks linked to handling clinical samples</li>\n      <li>Justify why every clinical sample is treated as high-risk</li>\n      <li>Apply first-principle safety thinking to a real laboratory scenario</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>1. First principles: the risk equation</h2>\n    <p><b>Risk = Hazard × Exposure × Consequence.</b> Remove any one factor and the risk collapses.</p>\n    <ul>\n      <li><b>Hazard:</b> the biological agent or material with potential to cause harm.</li>\n      <li><b>Exposure:</b> the pathway that lets a person come into contact with it.</li>\n      <li><b>Consequence:</b> the harm that results, such as infection, illness or spread.</li>\n    </ul>\n    <p class=\"key\">Laboratory biorisk management is the disciplined practice of identifying each factor and reducing it before an incident, not after.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>2. The concept of laboratory biorisk management</h2>\n    <p>Biorisk management is the combination of principles, practices and procedures used to control biological risk: reducing the likelihood of exposure, infection, loss or misuse of biological agents and toxins. It rests on two pillars:</p>\n    <table>\n      <tr><th>Pillar</th><th>What it protects</th><th>Covers</th></tr>\n      <tr><td><b>Biosafety</b></td><td>People from agents</td><td>Containment principles, practices, equipment and facility design that prevent unintentional exposure or accidental release.</td></tr>\n      <tr><td><b>Biosecurity</b></td><td>Agents from people</td><td>Protection, control and accountability of agents, preventing unauthorised access, loss, theft, misuse, diversion or intentional release.</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>3. Basic concepts of laboratory hazards</h2>\n    <p>A hazard is anything with the potential to cause harm. There are five classes:</p>\n    <table>\n      <tr><th>Class</th><th>Examples</th></tr>\n      <tr><td>Biological</td><td>Pathogens, cultures, blood, body fluids, other infectious materials</td></tr>\n      <tr><td>Chemical</td><td>Reagents, stains, solvents, disinfectants that are toxic or corrosive</td></tr>\n      <tr><td>Physical</td><td>Sharps, broken glass, heat, electrical and fire hazards</td></tr>\n      <tr><td>Ergonomic</td><td>Poor posture, repetitive strain, awkward workstation design</td></tr>\n      <tr><td>Radiological</td><td>Ionising sources used in some diagnostic and research procedures</td></tr>\n    </table>\n    <p class=\"key\">In a medical laboratory biological hazards dominate, but they rarely act alone. Chemical and physical hazards often compound them.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>4. Sources and types of biorisk</h2>\n    <h3>Sources (where biorisk comes from)</h3>\n    <ul>\n      <li>Patient specimens (blood, sputum, urine, tissue)</li>\n      <li>Microbial cultures and stock isolates</li>\n      <li>Contaminated equipment and work surfaces</li>\n      <li>Sharps: needles, lancets, broken glassware</li>\n      <li>Aerosols generated during sample processing</li>\n      <li>Improperly stored or labelled biological waste</li>\n    </ul>\n    <h3>Types (how biorisk manifests)</h3>\n    <ul>\n      <li><b>Percutaneous injury:</b> needlestick or cut through the skin</li>\n      <li><b>Mucocutaneous exposure:</b> splash to eyes, mouth or skin</li>\n      <li><b>Inhalation:</b> infectious aerosols or droplets</li>\n      <li><b>Ingestion:</b> via contaminated hands or surfaces</li>\n      <li><b>Spills and breakages</b> during handling or transport</li>\n      <li><b>Cross-contamination</b> between samples or work areas</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>5. Biorisks across the sample journey</h2>\n    <p>Risk travels with the sample through every stage:</p>\n    <table>\n      <tr><th>Stage</th><th>Main biorisk</th></tr>\n      <tr><td>1. Collection</td><td>Needlestick injuries; splash during venepuncture</td></tr>\n      <tr><td>2. Transport</td><td>Leakage or breakage from poor packaging and labelling</td></tr>\n      <tr><td>3. Processing</td><td>Aerosol release during centrifugation, pipetting or mixing</td></tr>\n      <tr><td>4. Analysis</td><td>Direct contact or splash while examining or culturing</td></tr>\n      <tr><td>5. Disposal</td><td>Exposure from improper segregation or disposal of waste</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>6. Why every clinical sample is high-risk</h2>\n    <ul>\n      <li>A clinical sample rarely arrives with its infectious status confirmed.</li>\n      <li>No visible sign reveals which pathogens a sample contains.</li>\n      <li>Confirmatory test results often take hours or days.</li>\n      <li>One sample may carry more than one infectious agent.</li>\n      <li>Patient history may be incomplete, unknown or withheld.</li>\n    </ul>\n    <p class=\"key\"><b>Standard Precautions:</b> every specimen, regardless of history, diagnosis or how routine it looks, is handled as potentially infectious.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>7. Case study: the morning in sample reception</h2>\n    <p>A student receives a rack of blood specimens for HIV and Hepatitis screening. One tube has a loose cap and blood on its outside. The form is soaked and the label smudged. The student is tempted to wipe the tube with tissue, tighten the cap and process it without gloves.</p>\n    <ul>\n      <li><b>Hazard classes present:</b> biological dominates; the wet outer surface and the chance of cuts or splashes add to it.</li>\n      <li><b>Exposure pathways:</b> hand-to-mouth or eye contact, skin contact with the contaminated exterior, splash during opening, and contamination of the bench.</li>\n      <li><b>Correct action:</b> wear gloves, handle the tube as potentially infectious, decontaminate the outside, do not process until the sample is documented and labelled correctly, and report the problem.</li>\n      <li><b>Biosecurity angle:</b> an unreadable label and form break traceability and accountability for the sample.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>Summary: key takeaways</h2>\n    <ul>\n      <li><b>Risk has three levers:</b> hazard, exposure and consequence. Reduce any one and risk falls.</li>\n      <li><b>Two pillars work together:</b> biosafety protects people from agents; biosecurity protects agents from people.</li>\n      <li><b>Hazards are multi-class:</b> biological, chemical, physical, ergonomic and radiological often overlap.</li>\n      <li><b>Risk travels with the sample:</b> each stage has its own exposure points.</li>\n      <li><b>Assume the unknown:</b> this is the basis of Standard Precautions.</li>\n    </ul>\n    <p class=\"meta\">Next: Week 2, Biosafety and Biosecurity in Medical Laboratories.</p>\n  </div>","flashcards":[{"front":"What is laboratory biorisk management?","back":"The combination of principles, practices and procedures used to control biological risk: reducing the likelihood of exposure, infection, loss or misuse of biological agents and toxins.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"Write the risk equation.","back":"Risk = Hazard × Exposure × Consequence. Remove any one factor and the risk collapses.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"Define 'Hazard'.","back":"The biological agent or material with potential to cause harm.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"Define 'Exposure'.","back":"The pathway that lets a person come into contact with the hazard.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"Define 'Consequence'.","back":"The harm that results: infection, illness or spread.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"What does biosafety protect?","back":"People from agents (containment, equipment and facility design).","topic":"Week 1: Laboratory Biorisk Management"},{"front":"What does biosecurity protect?","back":"Agents from people (control, accountability, prevention of theft, misuse, diversion).","topic":"Week 1: Laboratory Biorisk Management"},{"front":"Name the five hazard classes.","back":"Biological, chemical, physical, ergonomic, radiological.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"Give examples of chemical hazards.","back":"Reagents, stains, solvents and disinfectants that are toxic or corrosive.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"Give examples of physical hazards.","back":"Sharps, broken glass, heat, electrical and fire hazards.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"Which hazard class dominates in a medical lab?","back":"Biological. Often compounded by chemical and physical hazards.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"What is an ergonomic hazard?","back":"Poor posture, repetitive strain and awkward workstation design.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"What is a radiological hazard in the lab?","back":"Ionising sources used in some diagnostic and research procedures.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"Name the sources of biorisk.","back":"Patient specimens, microbial cultures and stock isolates, contaminated equipment and surfaces, sharps, aerosols, improperly labelled waste.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"What is percutaneous injury?","back":"A needlestick or cut through the skin.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"What is mucocutaneous exposure?","back":"A splash to the eyes, mouth or skin.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"How does inhalation exposure occur?","back":"Through infectious aerosols or droplets.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"What is cross-contamination?","back":"Transfer of material between samples or work areas.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"List the five stages of the sample journey.","back":"Collection, transport, processing, analysis, disposal.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"Which step has the highest aerosol risk and why?","back":"Processing: centrifugation, pipetting and mixing generate aerosols.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"Why is every clinical sample high-risk?","back":"Its infectious status is usually unknown until tested, and no visible sign reveals what it carries.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"What is Standard Precautions?","back":"Every specimen is handled as potentially infectious, regardless of history or diagnosis.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"Can one sample carry more than one agent?","back":"Yes. A single sample may harbour more than one infectious agent.","topic":"Week 1: Laboratory Biorisk Management"},{"front":"What are the two pillars working together?","back":"Biosafety (people from agents) and biosecurity (agents from people).","topic":"Week 1: Laboratory Biorisk Management"},{"front":"What is the core principle of Week 1?","back":"Identify each risk factor and reduce it before an incident, not after.","topic":"Week 1: Laboratory Biorisk Management"}],"questions":[{"question":"Laboratory biorisk management is best described as:","options":["Only handling infectious waste","A combination of principles and practices to control biological risk","A hospital insurance policy","Sterilising equipment only"],"answerIndex":1,"explanation":"It is the full set of principles, practices and procedures that control biological risk.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Biosafety protects:","options":["Agents from people","People from agents","The environment from chemicals only","Patients from staff"],"answerIndex":1,"explanation":"Biosafety protects people from biological agents.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Biosecurity protects:","options":["People from agents","Agents from people","Samples from temperature","Equipment from wear"],"answerIndex":1,"explanation":"Biosecurity protects agents from unauthorised access, loss, theft or misuse.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"The risk equation is:","options":["Hazard + Exposure + Consequence","Hazard × Exposure × Consequence","Hazard ÷ Exposure","Exposure − Hazard"],"answerIndex":1,"explanation":"Risk is the product of the three factors.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"According to the lecture, if you remove exposure from the equation, the risk:","options":["Doubles","Collapses","Stays the same","Becomes a hazard"],"answerIndex":1,"explanation":"Remove any one factor and the risk collapses.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"A hazard is best defined as:","options":["The pathway of contact","The harm that results","The agent with potential to cause harm","The protective equipment"],"answerIndex":2,"explanation":"A hazard is the agent or material with potential to cause harm.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Exposure is:","options":["The pathway that lets a person contact the hazard","An infection","The biological agent","A type of PPE"],"answerIndex":0,"explanation":"Exposure is the route of contact.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Infection, illness or spread is the:","options":["Hazard","Exposure","Consequence","Biosecurity measure"],"answerIndex":2,"explanation":"Consequence is the harm that results.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Which is NOT one of the five hazard classes?","options":["Biological","Chemical","Thermal","Ergonomic"],"answerIndex":2,"explanation":"The five classes are biological, chemical, physical, ergonomic and radiological.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"In a medical laboratory, which hazard class dominates?","options":["Radiological","Biological","Ergonomic","Physical"],"answerIndex":1,"explanation":"Biological hazards dominate, though they often combine with others.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Hazards in the lab often:","options":["Act alone","Compound each other","Disappear over time","Are only chemical"],"answerIndex":1,"explanation":"Chemical and physical hazards frequently compound biological ones.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Ionising sources used in diagnostics fall under:","options":["Physical","Radiological","Chemical","Ergonomic"],"answerIndex":1,"explanation":"Ionising sources are radiological hazards.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Poor posture and repetitive strain are:","options":["Ergonomic hazards","Chemical hazards","Biological hazards","Radiological hazards"],"answerIndex":0,"explanation":"They come from workstation and body mechanics.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Broken glass is classed as a:","options":["Physical hazard","Biological hazard","Ergonomic hazard","Chemical hazard"],"answerIndex":0,"explanation":"Sharps and broken glass are physical hazards.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Disinfectants and solvents are:","options":["Biological hazards","Chemical hazards","Physical hazards","Radiological hazards"],"answerIndex":1,"explanation":"They are toxic or corrosive chemicals.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Which is listed as a SOURCE of biorisk?","options":["Patient specimens","Lab coats","Water supply","Gloves"],"answerIndex":0,"explanation":"Patient specimens are a key source of biological risk.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Aerosols during sample processing are mainly produced by:","options":["Centrifugation, pipetting and mixing","Labelling","Storage in a fridge","Transport in a box"],"answerIndex":0,"explanation":"These actions generate infectious aerosols.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Percutaneous injury means:","options":["Inhalation of aerosols","A splash to the eyes","A needlestick or cut through the skin","Ingestion"],"answerIndex":2,"explanation":"Percutaneous means through the skin.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"A splash to the eyes is an example of:","options":["Percutaneous injury","Mucocutaneous exposure","Inhalation","Ingestion"],"answerIndex":1,"explanation":"Mucocutaneous exposure is contact with mucous membranes or skin.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Ingestion of agents can happen through:","options":["Contaminated hands or surfaces","Gloves","Autoclave steam","Centrifuge rotation"],"answerIndex":0,"explanation":"Touching the mouth or food after contact with contaminated surfaces.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Cross-contamination means:","options":["Transfer of material between samples or work areas","Routine cleaning","Sterilising instruments","Labelling samples"],"answerIndex":0,"explanation":"It is unintended transfer between samples or areas.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"The correct order of the sample journey is:","options":["Collection, transport, processing, analysis, disposal","Analysis, collection, disposal, transport, processing","Disposal, collection, processing, analysis, transport","Processing, collection, analysis, disposal, transport"],"answerIndex":0,"explanation":"Risk follows the sample in this order.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Leakage from poor packaging is linked to which stage?","options":["Collection","Transport","Analysis","Disposal"],"answerIndex":1,"explanation":"Poor packaging and labelling cause leaks during transport.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Needlestick during venepuncture belongs to which stage?","options":["Collection","Transport","Processing","Disposal"],"answerIndex":0,"explanation":"Venepuncture is part of collection.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Improper segregation of waste is a risk at which stage?","options":["Disposal","Collection","Transport","Analysis"],"answerIndex":0,"explanation":"Disposal is where waste segregation matters.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Standard Precautions require that:","options":["Only known-positive samples are treated as infectious","Every specimen is treated as potentially infectious","Gloves are needed only for blood","PPE is skipped for routine tests"],"answerIndex":1,"explanation":"Every specimen is handled as potentially infectious.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"A clinical sample is high-risk mainly because:","options":["Its infectious status is usually unknown until tested","It always contains HIV","It is sterile","It contains no organisms"],"answerIndex":0,"explanation":"The uncertainty is itself the hazard.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"A single clinical sample may:","options":["Hold only one agent","Harbour more than one infectious agent","Contain no agents","Carry only chemical hazards"],"answerIndex":1,"explanation":"Multiple agents can be present at once.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Confirmatory test results that confirm safety often take:","options":["Seconds","Hours or days","Never","Minutes, always"],"answerIndex":1,"explanation":"Results often take hours or days, so samples are treated as unknown in the meantime.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Can a visible sign reveal which pathogens a sample contains?","options":["Yes, always","No; no visible sign reveals the pathogens","Only colour reveals them","Only smell reveals them"],"answerIndex":1,"explanation":"Pathogens cannot be identified by appearance.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Patient history for a sample may be:","options":["Always provided","Incomplete, unknown or withheld","Irrelevant to risk","Stored on the sample"],"answerIndex":1,"explanation":"That is why every sample is treated as high-risk.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"In the case study, the outside of the loose-cap tube is contaminated with:","options":["Sterile saline","An unknown-titre sample","Disinfectant","Plain water"],"answerIndex":1,"explanation":"Blood on the outside is an unknown-titre contamination.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Wiping the tube with tissue and processing it without gloves breaks:","options":["Standard Precautions","Labelling rules only","Laboratory opening hours","No rule at all"],"answerIndex":0,"explanation":"It treats an unknown sample as safe.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"The biggest hazard class in the case study is:","options":["Radiological","Biological","Ergonomic","Physical"],"answerIndex":1,"explanation":"The blood sample is the dominant biological hazard.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"The smudged label and form in the case study raise which concern?","options":["Traceability and accountability (biosecurity)","A chemical spill","Radiation exposure","Posture"],"answerIndex":0,"explanation":"Unreadable records break sample traceability.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"The student's reason 'it's probably fine' is dangerous because:","options":["It saves time","It assumes unknown status is safe","It is standard practice","It is written in the rules"],"answerIndex":1,"explanation":"Assuming safety without knowing status is the core error.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"The correct response to the loose-cap tube is to:","options":["Process it immediately without gloves","Wear gloves, decontaminate, document and label correctly before processing","Discard it without a record","Ask the patient to repeat the test first"],"answerIndex":1,"explanation":"Handle as infectious, decontaminate, and keep records intact.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"'Assume the unknown' is the basis of:","options":["Standard Precautions","Biosecurity","Ergonomics","Radiation safety"],"answerIndex":0,"explanation":"Standard Precautions assume every sample could be infectious.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Biosafety cabinets and facility design mainly fall under:","options":["Biosecurity","Biosafety","Ergonomics","Chemical safety"],"answerIndex":1,"explanation":"They are containment measures that protect people.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Unauthorised access to a biological agent is a:","options":["Biosafety concern","Biosecurity concern","Ergonomic concern","Radiological concern"],"answerIndex":1,"explanation":"Biosecurity protects agents from unauthorised access.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Accidental release of an agent is a:","options":["Biosecurity concern","Biosafety concern","Theft issue","Diversion issue"],"answerIndex":1,"explanation":"Accidental release is a biosafety failure.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Which is a biosecurity concern?","options":["Accidental release","Unauthorised access or theft","Eye splash","Repetitive strain"],"answerIndex":1,"explanation":"Theft and diversion are biosecurity issues.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Which learning objective asks you to apply first-principle thinking to a scenario?","options":["Define","Explain","Apply","Identify"],"answerIndex":2,"explanation":"'Apply' is the objective that uses a real scenario.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Which is NOT a biological hazard?","options":["Culture","Blood","Solvent","Body fluids"],"answerIndex":2,"explanation":"Solvents are chemical hazards.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Stains and reagents are examples of:","options":["Chemical hazards","Physical hazards","Radiological hazards","Ergonomic hazards"],"answerIndex":0,"explanation":"Reagents and stains are chemical hazards.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Microbial cultures and stock isolates are listed under:","options":["Sources of biorisk","Ergonomic hazards","Radiological hazards","Chemical hazards"],"answerIndex":0,"explanation":"They are sources of biological risk.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Which is a TYPE of biorisk rather than a source?","options":["Spills and breakages","Patient specimens","Microbial cultures","Contaminated surfaces"],"answerIndex":0,"explanation":"Spills are how biorisk manifests.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Infection, illness or spread is called:","options":["A hazard","An exposure","A consequence","A biosecurity measure"],"answerIndex":2,"explanation":"That is the consequence in the risk equation.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Lab biorisk management aims to act:","options":["After an incident","Before an incident","Never","Only in emergencies"],"answerIndex":1,"explanation":"Prevention comes before incidents.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Two pillars of biorisk management are best described as:","options":["Competing","Complementary","Unnecessary","Identical"],"answerIndex":1,"explanation":"Biosafety and biosecurity work together.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Reducing exposure while the hazard stays the same:","options":["Increases the consequence","Reduces the risk","Increases the hazard","Has no effect"],"answerIndex":1,"explanation":"Reducing any factor lowers the overall risk.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Which is an ergonomic hazard?","options":["Poor workstation design","Broken glass","A pathogen","An ionising source"],"answerIndex":0,"explanation":"Workstation design is ergonomic.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Week 2 of MLS 101 covers:","options":["Biosafety and biosecurity in medical laboratories","Radiation physics","Chemical storage","Ergonomics only"],"answerIndex":0,"explanation":"Week 2 builds on Week 1's biosafety and biosecurity foundations.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Which is a key takeaway from Week 1?","options":["Hazards are single-class","Risk travels with the sample","Biosecurity is only about theft","Gloves are optional"],"answerIndex":1,"explanation":"Each sample stage carries its own exposure points.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Which pillar would a locked, logged store of select agents mainly serve?","options":["Biosafety","Biosecurity","Ergonomics","Radiological safety"],"answerIndex":1,"explanation":"Accountability and control of agents is biosecurity.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Which pair correctly matches the two pillars of biorisk management?","options":["Biosafety protects agents from people; biosecurity protects people from agents","Biosafety protects people from agents; biosecurity protects agents from people","Both protect only the environment","Biosafety is about theft; biosecurity is about splashes"],"answerIndex":1,"explanation":"Biosafety protects people from agents; biosecurity protects agents from people.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"During which stage of the sample journey is aerosol release most associated with centrifugation and pipetting?","options":["Collection","Transport","Processing","Disposal"],"answerIndex":2,"explanation":"Processing includes centrifugation, pipetting and mixing, which can release aerosols.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"A drop of blood splashes into a worker's eye. This is best classed as:","options":["Percutaneous injury","Mucocutaneous exposure","Ingestion","Inhalation"],"answerIndex":1,"explanation":"A splash to the eyes is mucocutaneous exposure.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"A lab reduces the number of staff allowed to handle a pathogen. Which factor of the risk equation is being reduced?","options":["Hazard","Exposure","Consequence","None of them"],"answerIndex":1,"explanation":"Limiting who can contact the agent reduces exposure.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"A broken centrifuge tube is classed as which hazard?","options":["Biological","Chemical","Physical","Ergonomic"],"answerIndex":2,"explanation":"Broken glass and equipment failures are physical hazards.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"A technician develops back pain from long periods at the microscope. This is a:","options":["Chemical hazard","Ergonomic hazard","Radiological hazard","Biological hazard"],"answerIndex":1,"explanation":"Posture and prolonged work are ergonomic hazards.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"A specimen tube arrives with blood on the outside and a smudged label. The safest default is to treat it as:","options":["Safe because it looks routine","Potentially infectious","Chemically contaminated only","Sterile"],"answerIndex":1,"explanation":"Standard Precautions: treat every specimen as potentially infectious.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Using the same pipette tip for two different patients' specimens is an example of:","options":["Cross-contamination","Standard Precautions","Hazard identification","Consequence"],"answerIndex":0,"explanation":"Transfer between samples is cross-contamination.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Which is NOT listed as a source of biorisk?","options":["Patient specimens","Microbial cultures","Sharps","Standard Precautions"],"answerIndex":3,"explanation":"Standard Precautions is a rule, not a source of biorisk.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Why is the uncertainty of a clinical sample itself considered a hazard?","options":["It makes the sample heavier","Its infectious content is unknown until testing is complete","It always contains HIV","It cannot be stored"],"answerIndex":1,"explanation":"The unknown infectious status is the hazard.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"An unlabelled specimen arrives in a teaching lab. What is the best first step?","options":["Process it quickly to save time","Handle it as potentially infectious and use appropriate PPE","Throw it away without a record","Taste it to check"],"answerIndex":1,"explanation":"Handle it as potentially infectious with appropriate PPE.","topic":"Week 1: Laboratory Biorisk Management"},{"question":"Which hazard class is most dominant in a medical laboratory?","options":["Biological","Radiological","Ergonomic","Physical"],"answerIndex":0,"explanation":"Biological hazards dominate in medical labs, often combined with chemical and physical hazards.","topic":"Week 1: Laboratory Biorisk Management"}]},{"id":"mls101-lecture-02","order":2,"title":"Week 2: Biosafety and Biosecurity","notesHtml":"<div class=\"card\">\n    <h2>Learning outcomes</h2>\n    <ul>\n      <li>Define biosafety and biosecurity</li>\n      <li>Distinguish between them</li>\n      <li>Describe the practical measures that keep lab personnel, samples and the community safe</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>1. Why biorisk management matters</h2>\n    <p>Medical lab scientists handle blood, sputum, stool and other specimens that may contain bacteria, viruses, fungi and parasites. This creates two related but distinct kinds of risk:</p>\n    <p class=\"key\"><b>Biorisk = Biosafety risk + Biosecurity risk.</b> Biorisk management is the umbrella discipline that protects personnel, patients, the public and the environment from biological agents and toxins.</p>\n    <p>Reviews of laboratory-acquired infections (LAIs) show that many followed breaches of routine biosafety, such as pipetting by mouth, working outside a biosafety cabinet, or needlestick injuries. They were not mainly exotic or unpreventable events.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>2. Biosafety</h2>\n    <p>WHO defines biosafety as the containment principles, technologies and practices implemented to prevent unintentional exposure to pathogens and toxins, or their accidental release.</p>\n    <p><b>Key idea:</b> protecting <i>people</i> from pathogens.</p>\n    <p><b>Example:</b> a scientist processing sputum for AFB microscopy wears gloves and an N95 respirator and works inside a certified biosafety cabinet. This reduces the chance of inhaling or being splashed with <i>M. tuberculosis</i>.</p>\n    <h3>Core elements of biosafety practice</h3>\n    <table>\n      <tr><th>Element</th><th>What it means</th></tr>\n      <tr><td><b>Risk assessment</b></td><td>Identify the hazard of each agent or procedure and match it to the right containment level before work begins</td></tr>\n      <tr><td><b>Standard microbiological practices</b></td><td>Hand hygiene, no mouth pipetting, no eating or drinking, minimising aerosols and splashes</td></tr>\n      <tr><td><b>Safety equipment (primary barriers)</b></td><td>Biosafety cabinets, PPE (gloves, gowns, respirators), safety centrifuge cups that shield the worker</td></tr>\n      <tr><td><b>Facility design (secondary barriers)</b></td><td>Handwashing sinks, negative-pressure airflow, autoclaves, restricted access that protect the wider environment</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>3. Biosecurity</h2>\n    <p>Biosecurity refers to the institutional and personal security measures that prevent the loss, theft, misuse, diversion or intentional release of pathogens, toxins and valuable biological materials.</p>\n    <p><b>Key idea:</b> protecting <i>pathogens</i> from people with harmful intent. It controls who can access dangerous agents and holds them accountable.</p>\n    <p><b>Example:</b> a lab keeps stored isolates in a locked freezer, logs every scientist who removes a sample, and restricts key-card access to the molecular biology room.</p>\n    <h3>Core elements of biosecurity</h3>\n    <table>\n      <tr><th>Element</th><th>What it means</th></tr>\n      <tr><td><b>Physical security</b></td><td>Locked storage, restricted-access rooms, alarms, key-card or biometric entry</td></tr>\n      <tr><td><b>Personnel reliability</b></td><td>Background checks, supervision and ongoing assessment of staff working with dangerous pathogens</td></tr>\n      <tr><td><b>Material control and accountability</b></td><td>Inventories and logs of agents held, by whom, and any transfer in or out</td></tr>\n      <tr><td><b>Transport security</b></td><td>Secure, triple-packaged shipment in line with IATA and WHO rules</td></tr>\n      <tr><td><b>Information security</b></td><td>Protecting data on pathogen stocks, protocols and security procedures from unauthorised access</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>4. The relationship between biosafety and biosecurity</h2>\n    <p>They are <b>complementary, not competing</b>. Both sit within biorisk management, both begin with risk assessment, and both protect personnel, the public and the environment. They guard against different threats:</p>\n    <ul>\n      <li><b>Biosafety</b> guards against <i>accidental</i> exposure.</li>\n      <li><b>Biosecurity</b> guards against <i>intentional</i> misuse.</li>\n      <li><b>Shared foundation:</b> risk assessment, SOPs and training.</li>\n    </ul>\n    <p class=\"key\">Memory aid: \"Biosafety keeps dangerous pathogens away from people; biosecurity keeps dangerous people away from pathogens.\"</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>5. Biosafety vs biosecurity at a glance</h2>\n    <table>\n      <tr><th></th><th>Biosafety</th><th>Biosecurity</th></tr>\n      <tr><td><b>Nature of threat</b></td><td>Accidental or unintentional exposure</td><td>Deliberate or intentional misuse</td></tr>\n      <tr><td><b>Source of risk</b></td><td>Natural hazards, human error, equipment failure</td><td>Human intent: theft, sabotage, diversion</td></tr>\n      <tr><td><b>Primary goal</b></td><td>Contain agents, prevent accidental release</td><td>Prevent unauthorised access or removal</td></tr>\n      <tr><td><b>Typical measures</b></td><td>PPE, biosafety cabinets, SOPs, immunisation</td><td>Locks, ID badges, inventories, background checks</td></tr>\n      <tr><td><b>Basis of planning</b></td><td>Risk assessment</td><td>Threat assessment</td></tr>\n      <tr><td><b>Guiding question</b></td><td>How do we stop an accident?</td><td>How do we stop a bad actor?</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>6. Biosafety levels (BSL 1 to 4)</h2>\n    <p>Labs are classified into four Biosafety Levels based on the risk group of the agents handled. Higher levels need stricter containment, engineering controls and PPE.</p>\n    <table>\n      <tr><th>Level</th><th>Typical agents</th><th>Containment</th></tr>\n      <tr><td><b>BSL-1</b></td><td>Non-pathogenic organisms, e.g. non-pathogenic E. coli</td><td>Open bench work; standard hand hygiene; no special barriers</td></tr>\n      <tr><td><b>BSL-2</b></td><td>Moderate-risk agents, e.g. HBV, HIV, Salmonella</td><td>Biosafety cabinet for aerosol-generating work, PPE, limited access, sharps precautions</td></tr>\n      <tr><td><b>BSL-3</b></td><td>Agents causing serious or lethal disease via inhalation, e.g. <i>M. tuberculosis</i></td><td>Controlled access, negative-pressure ventilation, respiratory protection, sealed windows</td></tr>\n      <tr><td><b>BSL-4</b></td><td>Exotic, high-consequence agents with no vaccine or treatment, e.g. Ebola, Lassa</td><td>Maximum containment; positive-pressure suits; dedicated air and waste systems</td></tr>\n    </table>\n    <p class=\"key\">Note: the BSL table is a key exam point. Routine culture of <i>M. tuberculosis</i> is BSL-3 work.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>7. Workplace safety assurance</h2>\n    <ol>\n      <li><b>Biosafety policy and manual:</b> a written institutional manual with rules, roles and responsibilities for each area</li>\n      <li><b>Training and competency:</b> induction, refresher training, and documented competency before independent bench work</li>\n      <li><b>PPE and engineering controls:</b> correctly fitted PPE and working biosafety cabinets or fume hoods</li>\n      <li><b>SOPs for every procedure:</b> current SOPs for routine work and emergencies such as spills and exposure</li>\n      <li><b>Waste management:</b> segregation, decontamination (autoclaving or chemical) and safe disposal of infectious and sharps waste</li>\n      <li><b>Health surveillance:</b> pre-placement screening, immunisation (e.g. Hepatitis B) and post-exposure follow-up</li>\n    </ol>\n  </div>\n\n  <div class=\"card\">\n    <h2>8. Biosecurity measures in the workplace</h2>\n    <ul>\n      <li><b>Access control:</b> key-card, biometric or locked-door entry to agent storage and sensitive areas</li>\n      <li><b>Inventory and accountability:</b> up-to-date logs with regular reconciliation to detect loss or unexplained transfer</li>\n      <li><b>Personnel vetting:</b> screening and supervision of staff and visitors with access to dangerous materials</li>\n      <li><b>Secure transport:</b> triple packaging and documented chain of custody (IATA and WHO rules)</li>\n      <li><b>Information security:</b> protecting records of stocks and security protocols</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>9. Case study: a laboratory-acquired infection</h2>\n    <p>A scientist processed sputum for suspected TB on an open bench, without a certified biosafety cabinet, and sometimes without a fitted respirator (\"it was only a quick smear\"). Six weeks later, active pulmonary TB was diagnosed. The investigation traced the exposure to repeated aerosol-generating work done outside primary containment.</p>\n    <ul>\n      <li><b>Principles breached:</b> biosafety, through the lack of primary containment and PPE.</li>\n      <li><b>Type of failure:</b> a biosafety failure. No deliberate misuse is described.</li>\n      <li><b>Single most effective change:</b> doing aerosol-generating work inside a certified biosafety cabinet.</li>\n      <li><b>Barriers:</b> the primary barriers are the biosafety cabinet and respirator. The secondary barrier is room ventilation.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>Summary: key takeaways</h2>\n    <ul>\n      <li>Biosafety prevents accidental exposure or release. Biosecurity prevents deliberate misuse.</li>\n      <li>Both rely on risk assessment and share the goal of protecting people and the environment.</li>\n      <li>Labs are graded BSL-1 to BSL-4 by the risk of the agents they handle.</li>\n      <li>Workplace safety assurance combines policy, training, PPE, SOPs and health surveillance.</li>\n    </ul>\n  </div>","flashcards":[{"front":"What does WHO define biosafety as?","back":"Containment principles, technologies and practices to prevent unintentional exposure to pathogens and toxins, or their accidental release.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is the key idea of biosafety?","back":"Protecting people from pathogens.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is biosecurity?","back":"Institutional and personal security measures to prevent loss, theft, misuse, diversion or intentional release of pathogens, toxins and valuable biological materials.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is the key idea of biosecurity?","back":"Protecting pathogens from people with harmful intent, controlling access and holding people accountable.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"Is biosafety about accidental or intentional threats?","back":"Accidental or unintentional exposure.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"Is biosecurity about accidental or intentional threats?","back":"Intentional or deliberate misuse.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is the memory aid for the two?","back":"Biosafety keeps dangerous pathogens away from people; biosecurity keeps dangerous people away from pathogens.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"Are biosafety and biosecurity competing or complementary?","back":"Complementary.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is the shared foundation of biosafety and biosecurity?","back":"Risk assessment, SOPs and training.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is biorisk?","back":"Biosafety risk plus biosecurity risk.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"Name the four core elements of biosafety practice.","back":"Risk assessment, standard microbiological practices, safety equipment (primary barriers), facility design (secondary barriers).","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What are primary barriers in biosafety?","back":"Equipment that shields the worker: biosafety cabinets, PPE, safety centrifuge cups.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What are secondary barriers in biosafety?","back":"Facility design: handwashing sinks, negative-pressure airflow, autoclaves, restricted access.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"Name the five core elements of biosecurity.","back":"Physical security, personnel reliability, material control and accountability, transport security, information security.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is material control and accountability?","back":"Inventories and logs of agents held, by whom, and any transfer in or out.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is personnel reliability?","back":"Background checks, supervision and ongoing assessment of staff handling dangerous pathogens.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"How should infectious substances be transported?","back":"Triple-packaged, in line with IATA and WHO rules.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"How many biosafety levels are there?","back":"Four: BSL-1 to BSL-4.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What determines the biosafety level?","back":"The risk group of the agents handled.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is BSL-1 for?","back":"Non-pathogenic organisms; open bench work with standard hand hygiene.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is BSL-2 for?","back":"Moderate-risk agents such as HBV, HIV and Salmonella; biosafety cabinet for aerosol work.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is BSL-3 for?","back":"Agents causing serious or lethal disease through inhalation, e.g. M. tuberculosis; negative-pressure ventilation.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is BSL-4 for?","back":"Exotic, high-consequence agents with no vaccine or treatment, e.g. Ebola or Lassa; maximum containment.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"Which BSL is appropriate for routine culture of M. tuberculosis?","back":"BSL-3.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is the key BSL-4 feature?","back":"Maximum containment, positive-pressure suits, dedicated air and waste systems.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"Name the six workplace safety assurance elements.","back":"Biosafety policy and manual, training and competency, PPE and engineering controls, SOPs, waste management, health surveillance.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is health surveillance?","back":"Pre-placement screening, immunisation (e.g. Hepatitis B) and post-exposure follow-up.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What do most laboratory-acquired infections follow?","back":"Breaches of routine biosafety practice.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"Give an example of biosafety in action.","back":"Working with TB sputum in a biosafety cabinet with gloves and an N95 respirator.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"Give an example of biosecurity in action.","back":"A locked freezer, a sample removal log, and key-card access to restricted rooms.","topic":"Week 2: Biosafety and Biosecurity"},{"front":"What is the single most effective change in the LAI case?","back":"Doing aerosol-generating work inside a certified biosafety cabinet.","topic":"Week 2: Biosafety and Biosecurity"}],"questions":[{"question":"Biosafety is best defined as:","options":["Protecting agents from people","Containment principles and practices to prevent unintentional exposure to pathogens","Controlling access to freezers only","Measuring equipment"],"answerIndex":1,"explanation":"Biosafety prevents unintentional exposure or release.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Biosecurity is best defined as:","options":["Preventing accidental spills","Security measures to prevent loss, theft, misuse or diversion of biological materials","Ergonomic posture","Fire drills"],"answerIndex":1,"explanation":"Biosecurity covers deliberate or unauthorised actions.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Biosafety protects:","options":["Agents from people","People from agents","Equipment from heat","Samples from light"],"answerIndex":1,"explanation":"Biosafety protects people.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Biosecurity protects:","options":["People from agents","Agents from people","Staff from fatigue","Buildings from fire"],"answerIndex":1,"explanation":"Biosecurity protects agents.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Biosafety guards against:","options":["Intentional misuse","Accidental exposure","Theft","Diversion"],"answerIndex":1,"explanation":"Biosafety handles accidents.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Biosecurity guards against:","options":["Accidental exposure","Intentional misuse","Needle sticks","Splashes"],"answerIndex":1,"explanation":"Biosecurity handles intentional misuse.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"The memory aid 'biosafety keeps dangerous pathogens away from people' is paired with:","options":["Biosecurity keeps dangerous people away from pathogens","Biosecurity keeps pathogens cold","Biosecurity keeps staff happy","Biosecurity keeps records clean"],"answerIndex":0,"explanation":"The pair is biosecurity keeping people away from pathogens.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Biosafety and biosecurity are best described as:","options":["Competing","Complementary","Identical","Unrelated"],"answerIndex":1,"explanation":"They work together.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is a shared foundation of both?","options":["Risk assessment","Lab colour","Coffee","Music"],"answerIndex":0,"explanation":"Risk assessment is shared.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Biorisk is:","options":["Biosafety risk only","Biosecurity risk only","Biosafety risk plus biosecurity risk","Chemical risk plus physical risk"],"answerIndex":2,"explanation":"Biorisk combines both.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Biorisk management protects:","options":["Only staff","Personnel, patients, public and environment","Only equipment","Only patients"],"answerIndex":1,"explanation":"It protects everyone involved.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Laboratory-acquired infections often follow:","options":["Exotic events that cannot be prevented","Breaches of routine biosafety practice","Only power cuts","Only fires"],"answerIndex":1,"explanation":"Most follow routine breaches.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is a biosafety breach listed in the lecture?","options":["Pipetting by mouth","Using a key card","Logging inventory","Locking a freezer"],"answerIndex":0,"explanation":"Mouth pipetting is a biosafety breach.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is a core element of biosafety practice?","options":["Risk assessment","Background check","Locked freezer","Key-card entry"],"answerIndex":0,"explanation":"Risk assessment is a biosafety element.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Standard microbiological practice includes:","options":["Hand hygiene","Background checks","Triple packaging","Access logs"],"answerIndex":0,"explanation":"Hand hygiene is a standard practice.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is a primary barrier?","options":["Facility design","Biosafety cabinet","Autoclave","Restricted access"],"answerIndex":1,"explanation":"Biosafety cabinets shield the worker.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is a secondary barrier?","options":["Biosafety cabinet","PPE","Negative-pressure airflow","Gloves"],"answerIndex":2,"explanation":"Airflow is facility design.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Safety centrifuge cups are classed as:","options":["Primary barriers","Secondary barriers","Biosecurity measures","Waste"],"answerIndex":0,"explanation":"They protect the worker directly.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Negative-pressure airflow is an example of:","options":["Primary barrier","Secondary barrier","Biosecurity measure","PPE"],"answerIndex":1,"explanation":"Facility design.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Handwashing sinks are classed as:","options":["Secondary barriers","Primary barriers","Biosecurity","PPE"],"answerIndex":0,"explanation":"Facility design.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Biosecurity physical security includes:","options":["Locked storage","Hand hygiene","Autoclaves","Pipettes"],"answerIndex":0,"explanation":"Locked storage is physical security.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Personnel reliability includes:","options":["Background checks","Biosafety cabinets","Sharps bins","Centrifuges"],"answerIndex":0,"explanation":"Background checks.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Material control means:","options":["Keeping inventories and logs of agents","Changing gloves","Cleaning benches","Heating samples"],"answerIndex":0,"explanation":"Inventories and logs.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Secure transport of infectious substances uses:","options":["Triple packaging","Plastic bags only","No packaging","Open boxes"],"answerIndex":0,"explanation":"Triple packaging.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Information security protects:","options":["Records of stocks and security protocols","Lab lighting","Chairs","Floor tiles"],"answerIndex":0,"explanation":"Records and protocols.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is a biosecurity measure?","options":["Autoclaving","Key-card access to agent storage","Hand hygiene","Eye protection"],"answerIndex":1,"explanation":"Key-card access restricts entry.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is a biosafety measure?","options":["Key-card access","Locked freezer","Eye protection","Logging removal of samples"],"answerIndex":2,"explanation":"Eye protection is a safety measure.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Logging every scientist who removes a sample is:","options":["Biosafety","Biosecurity","Ergonomics","Radiation safety"],"answerIndex":1,"explanation":"It holds people accountable.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which measure is for accountability?","options":["Logs and inventories","Gloves","Lab coats","Autoclaves"],"answerIndex":0,"explanation":"Logs provide accountability.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"What is the key difference between the two?","options":["Biosafety is about accidents; biosecurity is about intent","Biosafety is about money; biosecurity is about time","No difference","Biosafety is only for animals"],"answerIndex":0,"explanation":"Accident versus intent.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"What is the basis of biosafety planning?","options":["Threat assessment","Risk assessment","Budget planning","Staff rota"],"answerIndex":1,"explanation":"Risk assessment.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"What is the basis of biosecurity planning?","options":["Threat assessment","Risk assessment only","Lunch plan","Parking"],"answerIndex":0,"explanation":"Threat assessment.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"A biosafety question is:","options":["How do we stop a bad actor?","How do we stop an accident?","How do we stop theft?","How do we stop diversion?"],"answerIndex":1,"explanation":"Accident focus.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"A biosecurity question is:","options":["How do we stop an accident?","How do we stop a bad actor?","How do we clean benches?","How do we label?"],"answerIndex":1,"explanation":"Intent focus.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"How many biosafety levels are there?","options":["2","3","4","5"],"answerIndex":2,"explanation":"Four levels.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"BSL-2 is typically used for:","options":["Non-pathogenic E. coli","Moderate-risk agents such as HIV and Salmonella","Ebola","Lassa"],"answerIndex":1,"explanation":"Moderate-risk agents.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"BSL-1 is used for:","options":["Non-pathogenic organisms","TB","Ebola","Lassa"],"answerIndex":0,"explanation":"Non-pathogenic organisms.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"BSL-3 is used for:","options":["Agents causing serious or lethal disease via inhalation","Non-pathogenic bacteria","Plain water","Glass"],"answerIndex":0,"explanation":"Serious inhalation risk.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"BSL-4 is used for:","options":["Exotic, high-consequence agents with no vaccine or treatment","Routine blood tests","Urine dipsticks","Stool microscopy"],"answerIndex":0,"explanation":"Highest containment.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which BSL requires negative-pressure ventilation?","options":["BSL-1","BSL-2","BSL-3","None"],"answerIndex":2,"explanation":"BSL-3 uses negative-pressure ventilation.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which BSL requires positive-pressure suits?","options":["BSL-1","BSL-2","BSL-3","BSL-4"],"answerIndex":3,"explanation":"BSL-4 uses positive-pressure suits.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Routine culture of M. tuberculosis is at:","options":["BSL-1","BSL-2","BSL-3","BSL-4"],"answerIndex":2,"explanation":"BSL-3.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is the lowest containment?","options":["BSL-1","BSL-2","BSL-3","BSL-4"],"answerIndex":0,"explanation":"BSL-1.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which best describes BSL-4?","options":["Open bench work","Maximum containment","Standard handwashing only","No PPE needed"],"answerIndex":1,"explanation":"Maximum containment.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Biosafety levels are assigned based on:","options":["The risk group of the agent","The colour of the lab","The cost of reagents","The number of staff"],"answerIndex":0,"explanation":"Risk group drives BSL.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Workplace safety assurance includes:","options":["A written biosafety manual","Free lunches","Music","Car parks"],"answerIndex":0,"explanation":"A manual is part of assurance.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Health surveillance includes:","options":["Pre-placement screening","Gym membership","Driving tests","Cooking classes"],"answerIndex":0,"explanation":"Pre-placement screening.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which immunisation is mentioned for lab staff?","options":["Hepatitis B","Measles only","None","Flu only"],"answerIndex":0,"explanation":"Hepatitis B is listed.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Waste management in the lab includes:","options":["Segregation and decontamination","Burning in the open","Mixing all waste","Storing at the bench"],"answerIndex":0,"explanation":"Segregation and decontamination.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is a biosafety requirement for training?","options":["Documented competency before independent bench work","Driving tests","Talent shows","Quiz nights"],"answerIndex":0,"explanation":"Competency before independent work.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"In the LAI case study, which principle was breached?","options":["Biosafety","Biosecurity only","Ergonomics only","Radiation safety"],"answerIndex":0,"explanation":"Biosafety containment was lacking.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"In the LAI case study, what is the most helpful single change?","options":["Working in a certified biosafety cabinet","Changing the lab colour","Buying a new fridge","Working faster"],"answerIndex":0,"explanation":"Primary containment.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which barriers should have contained the aerosols in the LAI case?","options":["Biosafety cabinet, respirator and room ventilation","Lab coat and gloves only","Glasses only","Sandals"],"answerIndex":0,"explanation":"Primary and secondary barriers.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which was NOT stated as the failure type in the LAI case?","options":["Biosafety failure","Biosecurity failure","Both are possible to discuss","Ergonomic failure"],"answerIndex":3,"explanation":"Ergonomic is not the lecture's focus here.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is a biosecurity failure example?","options":["Splash to the eye","Theft of isolates from an unlocked freezer","Needle stick","Aerosol release"],"answerIndex":1,"explanation":"Theft is biosecurity.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is a biosafety failure example?","options":["Pipetting by mouth","Deliberate removal of samples","Sharing a locked key","Stealing a sample"],"answerIndex":0,"explanation":"Mouth pipetting is biosafety.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Why do labs limit access to agent storage?","options":["To make it look neat","To prevent loss, theft and misuse","To save money","To cool the room"],"answerIndex":1,"explanation":"Protect agents from misuse.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is correct about biosafety cabinets?","options":["They are biosecurity devices","They are primary barriers for aerosol work","They replace PPE","They are facility design"],"answerIndex":1,"explanation":"Primary barriers for aerosol work.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which is correct about PPE?","options":["It is a secondary barrier","It is a primary barrier worn by the worker","It is biosecurity","It is facility design"],"answerIndex":1,"explanation":"PPE is worn by the worker.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which statement is correct?","options":["Biosecurity measures never involve people","Background checks are a biosecurity measure","Biosafety involves theft prevention","Biosafety is only about glass"],"answerIndex":1,"explanation":"Background checks are biosecurity.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Why is risk assessment important before work?","options":["It is optional","It matches hazards to the right containment before work begins","It delays work","It replaces training"],"answerIndex":1,"explanation":"Match containment before starting.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Which of these shows the link between biosafety and biosecurity?","options":["Both begin with risk assessment","One ignores the other","Both ignore SOPs","Both ignore training"],"answerIndex":0,"explanation":"Shared start.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"What does BSL stand for?","options":["Biosafety Level","Blood Specimen Limit","Biological Sample Log","Bench Safety Line"],"answerIndex":0,"explanation":"Biosafety Level.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"Why are biosafety cabinets used for aerosol-generating work?","options":["To look professional","To contain infectious aerosols","To warm samples","To store reagents"],"answerIndex":1,"explanation":"Containment of aerosols.","topic":"Week 2: Biosafety and Biosecurity"},{"question":"The main message of Week 2 is:","options":["Biosafety and biosecurity are unrelated","Biosafety protects against accidents, biosecurity protects against misuse, and both are needed","Only PPE matters","Only security matters"],"answerIndex":1,"explanation":"Both are needed.","topic":"Week 2: Biosafety and Biosecurity"}]},{"id":"mls101-lecture-03","order":3,"title":"Week 3: The AMP Model of Biorisk Management","notesHtml":"<div class=\"card\">\n    <h2>Learning outcomes</h2>\n    <ul>\n      <li>Explain the AMP model</li>\n      <li>Describe its three components</li>\n      <li>Show how they work together in a continual cycle to manage biorisk in the medical laboratory</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>1. Bridge from Week 2</h2>\n    <p>Biosafety guards against accidental exposure and biosecurity guards against intentional misuse. Good intentions and isolated precautions are not enough. A lab needs a structured, repeatable system to identify risk, control it, and check that the controls keep working. The AMP model does this for biorisk, turning biosafety and biosecurity from a list of habits into a managed, continually improving system.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>2. What is the AMP model?</h2>\n    <p>AMP is a biorisk management framework built on three interconnected components: <b>Assessment, Mitigation and Performance</b>. It is used to identify, control and continually improve the management of biological risk in labs.</p>\n    <ul>\n      <li><b>Source:</b> it underpins CEN Workshop Agreement CWA 15793 (Laboratory Biorisk Management Standard) and is reflected in WHO guidance.</li>\n      <li><b>Not a checklist:</b> it is a continual cycle. You assess risk, mitigate it, check that mitigation performs, and feed what you learn back into a fresh assessment.</li>\n    </ul>\n    <p class=\"key\">The cycle never \"finishes\" because new agents, staff, procedures and incidents keep feeding back into assessment.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>3. Component 1: Assessment</h2>\n    <p><b>Core question: what could go wrong?</b></p>\n    <p>Assessment is the systematic process of identifying biological hazards and analysing the risk they pose: the likelihood of accidental exposure or a deliberate security breach, and the consequences if it happened.</p>\n    <ol>\n      <li>Identify the biological agents or toxins handled, and their risk group</li>\n      <li>Analyse routes of exposure and the likelihood of release (biosafety risk)</li>\n      <li>Analyse threats of loss, theft, diversion or misuse (biosecurity risk)</li>\n      <li>Characterise consequences for staff, patients, community and environment</li>\n      <li>Assign the appropriate biosafety level and prioritise risks for action</li>\n    </ol>\n  </div>\n\n  <div class=\"card\">\n    <h2>4. Component 2: Mitigation</h2>\n    <p><b>Core question: how do we control it?</b></p>\n    <p>Mitigation is the set of actions that reduce the risks found at assessment to an acceptable level. It combines biosafety and biosecurity controls.</p>\n    <ol>\n      <li><b>Engineering controls:</b> biosafety cabinets, negative-pressure rooms, locks</li>\n      <li><b>Administrative controls:</b> SOPs, codes of practice, staff training</li>\n      <li><b>PPE:</b> gloves, gowns, respirators</li>\n      <li><b>Security controls:</b> access restriction, inventories, transport security</li>\n      <li>Select the lowest-risk method or agent that still meets the testing need</li>\n    </ol>\n  </div>\n\n  <div class=\"card\">\n    <h2>5. Component 3: Performance</h2>\n    <p><b>Core question: is the control working?</b></p>\n    <p>Performance is the ongoing verification that mitigation measures actually work and are sustained over time. It is the quality-assurance arm of biorisk management.</p>\n    <ol>\n      <li>Monitoring and supervisory checks of day-to-day practice</li>\n      <li>Internal and external audits or inspections of the biorisk programme</li>\n      <li>Incident and near-miss reporting, investigation and corrective action</li>\n      <li>Refresher training and competency re-assessment of personnel</li>\n      <li>Management review, feeding lessons learned back into assessment</li>\n    </ol>\n  </div>\n\n  <div class=\"card\">\n    <h2>6. The three components at a glance</h2>\n    <table>\n      <tr><th></th><th>Assessment</th><th>Mitigation</th><th>Performance</th></tr>\n      <tr><td><b>Core question</b></td><td>What could go wrong?</td><td>How do we control it?</td><td>Is the control working?</td></tr>\n      <tr><td><b>Main activity</b></td><td>Hazard and risk or threat analysis</td><td>Engineering, admin, PPE and security controls</td><td>Monitoring, audit, review</td></tr>\n      <tr><td><b>Timing</b></td><td>Before work begins, and periodically</td><td>During implementation</td><td>Continuously, after implementation</td></tr>\n      <tr><td><b>Output</b></td><td>Prioritised risk register</td><td>Documented control measures</td><td>Audit findings and corrective actions</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>7. Worked example: introducing a TB testing service</h2>\n    <p>A hospital lab plans to introduce Xpert MTB/RIF (GeneXpert) testing for tuberculosis.</p>\n    <ul>\n      <li><b>Assessment:</b> identify <i>M. tuberculosis</i> as the hazard. Assess aerosol risk during sputum loading and the biosafety level needed for specimen preparation.</li>\n      <li><b>Mitigation:</b> process specimens in a biosafety cabinet, issue N95 respirators, write a cartridge-loading SOP, and restrict reagent access to trained staff.</li>\n      <li><b>Performance:</b> supervisors check compliance weekly, incidents and near misses are logged, and staff complete refresher training twice a year.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>8. Integration: why all three must run together</h2>\n    <ul>\n      <li><b>Mitigation without assessment:</b> controls are put in place blindly. Effort goes to low risks while real hazards go unmanaged.</li>\n      <li><b>Performance without mitigation:</b> monitoring has nothing concrete to check.</li>\n      <li><b>Assessment without performance:</b> risks are identified once and never re-checked, so controls can quietly fail and risk can creep back.</li>\n    </ul>\n    <p class=\"key\">Integration means running all three continuously and in parallel, so each strengthens the others. This is the same continual-improvement logic as a lab Quality Management System.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>9. PDCA and the AMP model</h2>\n    <p><b>PDCA</b> (Plan, Do, Check, Act) is also called the Deming or Shewhart Cycle. It is the generic improvement engine. AMP is that same logic applied to biorisk.</p>\n    <table>\n      <tr><th>PDCA step</th><th>AMP component</th><th>What happens</th></tr>\n      <tr><td><b>Plan</b></td><td>Assessment</td><td>Identify the hazard or threat, analyse the risk, decide controls and targets</td></tr>\n      <tr><td><b>Do</b></td><td>Mitigation</td><td>Implement engineering, administrative, PPE and security controls</td></tr>\n      <tr><td><b>Check</b></td><td>Performance</td><td>Monitor, audit and review whether controls work as intended</td></tr>\n      <tr><td><b>Act</b></td><td>Back to Assessment</td><td>Standardise controls that work, or revise the assessment and restart</td></tr>\n    </table>\n    <p><b>TB example:</b> Plan = assess aerosol risk and decide a biosafety cabinet is needed. Do = install it and train staff. Check = audit compliance and review incident logs. Act = standardise the SOP lab-wide if it works, or revise and retrain if gaps are found.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>10. Summary</h2>\n    <ul>\n      <li><b>AMP</b> = Assessment, Mitigation, Performance. It is a cycle, not a checklist.</li>\n      <li><b>Assessment</b> identifies and analyses biosafety and biosecurity risk.</li>\n      <li><b>Mitigation</b> puts engineering, administrative, PPE and security controls in place.</li>\n      <li><b>Performance</b> verifies controls work and feeds lessons back into assessment.</li>\n    </ul>\n  </div>","flashcards":[{"front":"What does AMP stand for?","back":"Assessment, Mitigation, Performance.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What is the AMP model?","back":"A biorisk management framework of three interconnected components used to identify, control and continually improve management of biological risk.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"Which standard does the AMP model underpin?","back":"CEN Workshop Agreement CWA 15793: Laboratory Biorisk Management Standard.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"Is the AMP model a one-off checklist?","back":"No. It is a continual cycle: assess, mitigate, perform, and feed results back into assessment.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What is the core question of Assessment?","back":"What could go wrong?","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What does Assessment involve?","back":"Identifying biological hazards and analysing the likelihood and consequences of accidental exposure or deliberate breach.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What does Assessment output?","back":"A prioritised risk register.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What is the core question of Mitigation?","back":"How do we control it?","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"Name the four main types of mitigation control.","back":"Engineering, administrative, PPE, and security controls.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"Give an example of an engineering control.","back":"Biosafety cabinets, negative-pressure rooms, or locks.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"Give an example of an administrative control.","back":"SOPs, codes of practice, or staff training.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"Give an example of a security control.","back":"Access restriction, inventories, or transport security.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What is the core question of Performance?","back":"Is the control working?","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What does Performance involve?","back":"Verifying that mitigation measures are working and sustained over time, the quality-assurance arm of biorisk management.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"Name two Performance activities.","back":"Monitoring and supervisory checks; internal and external audits; incident and near-miss reporting; refresher training; management review.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What does Mitigation output?","back":"Documented control measures.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What does Performance output?","back":"Audit findings and corrective actions.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"When does Assessment happen?","back":"Before work begins, and periodically.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"Why is AMP drawn as a cycle, not a line?","back":"Because biorisk management never finishes; new agents, staff, procedures and incidents feed back into assessment.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What is PDCA also called?","back":"The Deming Cycle or Shewhart Cycle.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"Which AMP component matches PDCA's Plan step?","back":"Assessment.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"Which AMP component matches PDCA's Do step?","back":"Mitigation.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"Which AMP component matches PDCA's Check step?","back":"Performance.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What does PDCA's Act step lead to in AMP?","back":"Back to Assessment: standardise what works, or revise the assessment and restart.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What goes wrong with Mitigation without Assessment?","back":"Controls are put in place blindly, and effort is wasted on low risks while real hazards go unmanaged.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What goes wrong with Assessment without Performance?","back":"Risks are identified once and never re-checked, so controls can quietly fail.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"What goes wrong with Performance without Mitigation?","back":"Monitoring has no concrete controls to check.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"In the TB example, what is the Assessment hazard?","back":"Mycobacterium tuberculosis, with aerosol risk during sputum loading.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"In the TB example, name two Mitigation measures.","back":"Process in a biosafety cabinet; issue N95 respirators; write an SOP; restrict reagent access.","topic":"Week 3: The AMP Model of Biorisk Management"},{"front":"In the TB example, name two Performance measures.","back":"Weekly supervisor compliance checks; incident and near-miss logging; refresher training twice a year.","topic":"Week 3: The AMP Model of Biorisk Management"}],"questions":[{"question":"AMP stands for:","options":["Assessment, Mitigation, Performance","Analysis, Monitoring, Protection","Audit, Management, Planning","Assessment, Measurement, Prevention"],"answerIndex":0,"explanation":"AMP = Assessment, Mitigation, Performance.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"The AMP model is best described as:","options":["A one-off checklist","A continual cycle","A type of PPE","A lab building plan"],"answerIndex":1,"explanation":"It is a continual cycle.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"AMP underpins which standard?","options":["ISO 9001","CEN Workshop Agreement CWA 15793","CLIA 88","HIPAA"],"answerIndex":1,"explanation":"CWA 15793 is the Laboratory Biorisk Management Standard.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"What is the core question of Assessment?","options":["How do we control it?","Is the control working?","What could go wrong?","Who pays?"],"answerIndex":2,"explanation":"Assessment asks what could go wrong.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"What is the core question of Mitigation?","options":["What could go wrong?","How do we control it?","Is it working?","When is the audit?"],"answerIndex":1,"explanation":"Mitigation asks how to control it.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"What is the core question of Performance?","options":["What could go wrong?","How do we control it?","Is the control working?","Who is the supervisor?"],"answerIndex":2,"explanation":"Performance checks that controls work.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Assessment identifies:","options":["Biological hazards and their risk","Only the price of reagents","Only staff salaries","Only room colour"],"answerIndex":0,"explanation":"Assessment identifies hazards and analyses risk.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Assessment analyses both:","options":["Biosafety and biosecurity risk","Only chemical risk","Only ergonomic risk","Only financial risk"],"answerIndex":0,"explanation":"Both kinds of risk are assessed.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which is a biosecurity risk analysed at assessment?","options":["Needlestick injury","Theft or diversion of agents","Splash to the eye","Repetitive strain"],"answerIndex":1,"explanation":"Theft and diversion are biosecurity risks.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which is a biosafety risk analysed at assessment?","options":["Theft","Diversion","Accidental exposure","Unauthorised access"],"answerIndex":2,"explanation":"Accidental exposure is biosafety.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"At assessment, the lab must assign:","options":["The appropriate biosafety level","A new uniform","The staff salary","The lab name"],"answerIndex":0,"explanation":"Assign the appropriate BSL.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Assessment output is best described as:","options":["A prioritised risk register","A purchase list","A menu","A staff rota"],"answerIndex":0,"explanation":"The output is a prioritised risk register.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"When should assessment happen?","options":["Only after an accident","Before work begins and periodically","Only once a year at the end","Never"],"answerIndex":1,"explanation":"Before work and periodically.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which is an engineering control in mitigation?","options":["SOPs","Biosafety cabinet","Staff training","Access rules"],"answerIndex":1,"explanation":"Biosafety cabinets are engineering controls.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which is an administrative control in mitigation?","options":["Negative-pressure room","SOPs and staff training","Gloves","Locks"],"answerIndex":1,"explanation":"SOPs and training are administrative.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which is a PPE control in mitigation?","options":["Gloves","Locks","SOPs","Inventories"],"answerIndex":0,"explanation":"Gloves are PPE.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which is a security control in mitigation?","options":["Respirator","Access restriction","Biosafety cabinet","Training"],"answerIndex":1,"explanation":"Access restriction is a security control.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Mitigation should select:","options":["The highest-risk method","The lowest-risk method that still meets the testing need","The most expensive method","A random method"],"answerIndex":1,"explanation":"Choose the lowest-risk option that works.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Mitigation output is best described as:","options":["Documented control measures","An audit finding","A risk register","A staff list"],"answerIndex":0,"explanation":"Mitigation documents its controls.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which is a Performance activity?","options":["Buying equipment","Internal audit","Designing a lab","Writing menus"],"answerIndex":1,"explanation":"Internal audits are Performance activities.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which is a Performance activity?","options":["Refresher training and competency reassessment","Choosing a building colour","Hiring a driver","Purchasing furniture"],"answerIndex":0,"explanation":"Refresher training checks competency.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Performance outputs are best described as:","options":["Audit findings and corrective actions","Risk registers","Lab designs","Purchase orders"],"answerIndex":0,"explanation":"Performance produces findings and corrective actions.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Performance should be:","options":["Done once only","Continuous, after implementation","Only before work starts","Only when there is a complaint"],"answerIndex":1,"explanation":"Performance is continuous.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which of these is a near-miss reporting activity?","options":["Performance","Mitigation","Assessment only","Procurement"],"answerIndex":0,"explanation":"Near-miss reporting is part of performance.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Management review feeds lessons learned back into:","options":["Procurement","Assessment","Staff parking","Lab decor"],"answerIndex":1,"explanation":"Lessons go back into assessment.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"In the AMP model, the cycle repeats because:","options":["It is required by law only","Biorisk management never finishes","Labs close yearly","PPE expires"],"answerIndex":1,"explanation":"New agents, staff and incidents feed back.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which PDCA step matches Assessment?","options":["Plan","Do","Check","Act"],"answerIndex":0,"explanation":"Plan matches assessment.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which PDCA step matches Mitigation?","options":["Plan","Do","Check","Act"],"answerIndex":1,"explanation":"Do matches mitigation.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which PDCA step matches Performance?","options":["Plan","Do","Check","Act"],"answerIndex":2,"explanation":"Check matches performance.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which PDCA step leads back to Assessment?","options":["Plan","Do","Check","Act"],"answerIndex":3,"explanation":"Act feeds back into assessment.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"PDCA stands for:","options":["Plan, Do, Check, Act","Prepare, Deliver, Clean, Assess","Protect, Direct, Control, Audit","Plan, Document, Confirm, Adjust"],"answerIndex":0,"explanation":"Plan, Do, Check, Act.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"PDCA is also called the:","options":["Deming Cycle or Shewhart Cycle","Pasteur Cycle","Koch Loop","Nightingale Method"],"answerIndex":0,"explanation":"Deming and Shewhart are its names.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"In the TB example, the hazard identified at assessment is:","options":["Mycobacterium tuberculosis","Plastic bottles","Paper","Water"],"answerIndex":0,"explanation":"M. tuberculosis is the hazard.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"In the TB example, what mitigation is used for sputum loading?","options":["Working in a biosafety cabinet","Working with the door open","Eating nearby","Using no gloves"],"answerIndex":0,"explanation":"A biosafety cabinet is used.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"In the TB example, which PPE is issued?","options":["N95 respirators","Sandals","Hats","Scarves"],"answerIndex":0,"explanation":"N95 respirators are issued.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"In the TB example, who is allowed reagent access?","options":["Anyone","Trained staff only","Visitors","Patients"],"answerIndex":1,"explanation":"Access is restricted to trained staff.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"In the TB example, how often is refresher training?","options":["Never","Twice a year","Once a decade","Only after an incident"],"answerIndex":1,"explanation":"Twice a year.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Mitigation without assessment leads to:","options":["Perfect control","Effort wasted on low risks, and real hazards unmanaged","No cost","No staff"],"answerIndex":1,"explanation":"Wrong priorities.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Assessment without performance leads to:","options":["Constant review","Controls that can quietly fail and risk creeping back","Perfect safety","Less training"],"answerIndex":1,"explanation":"Risk can creep back unnoticed.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Performance without mitigation leads to:","options":["Monitoring with nothing concrete to check","Better controls","Fewer audits","More PPE"],"answerIndex":0,"explanation":"There is nothing to verify.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Integration means:","options":["Running the three components once in sequence","Running all three continuously and in parallel so each strengthens the others","Doing only assessment","Doing only performance"],"answerIndex":1,"explanation":"Continuous and parallel.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which best describes the relationship between AMP and a lab QMS?","options":["They have no link","The same continual-improvement logic applies","QMS replaces AMP","AMP replaces QMS"],"answerIndex":1,"explanation":"Both use continual improvement.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"A near-miss report during Performance should prompt:","options":["Nothing","A new assessment","A purchase","A party"],"answerIndex":1,"explanation":"It can trigger a new assessment.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which is the best example of Performance monitoring?","options":["Weekly supervisor compliance checks","Designing a logo","Choosing a colour","Booking a hall"],"answerIndex":0,"explanation":"Supervisor checks monitor performance.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which best describes the Mitigation goal?","options":["Find hazards","Reduce risk to an acceptable level","Measure audits","Write reports only"],"answerIndex":1,"explanation":"Mitigation reduces risk.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which best describes the Assessment goal?","options":["Reduce risk","Identify and analyse risk","Audit staff","Buy PPE"],"answerIndex":1,"explanation":"Assessment identifies and analyses.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which best describes the Performance goal?","options":["Start new projects","Verify and sustain controls","Design buildings","Choose uniforms"],"answerIndex":1,"explanation":"Verify and sustain.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"The 'Do' step of PDCA is best described as:","options":["Implementing the plan, often on a small controlled scale first","Writing the report","Closing the lab","Ignoring the data"],"answerIndex":0,"explanation":"Implement, often on a small scale.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"The 'Check' step of PDCA is:","options":["Measuring results against expectations","Designing the building","Hiring new staff","Buying chairs"],"answerIndex":0,"explanation":"Check measures results.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"The 'Act' step of PDCA is:","options":["Standardise success, or adjust the plan and repeat","Stop forever","Forget the results","Only write a letter"],"answerIndex":0,"explanation":"Standardise or adjust and repeat.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which of these best reflects 'biosafety and biosecurity' from Week 2 in AMP?","options":["Both are part of the Assessment and Mitigation","Neither is used","Only PPE","Only audits"],"answerIndex":0,"explanation":"Both are assessed and mitigated.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which control is best for restricting who can reach agent storage?","options":["Security control","Engineering control only","PPE","Training"],"answerIndex":0,"explanation":"Security controls restrict access.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which best describes 'prioritise risks for action'?","options":["Ranking risks so the most serious are addressed first","Ignoring risks","Writing risks in colour","Listing staff"],"answerIndex":0,"explanation":"Priority first.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which best describes 'characterise consequences'?","options":["Assessing harm to staff, patients, community and environment","Counting chairs","Designing signs","Buying software"],"answerIndex":0,"explanation":"It covers all affected groups.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Why must Mitigation balance biosafety and biosecurity?","options":["Because they are unrelated","Because controls must address both accidental and deliberate threats","Because one is cheaper","Because the lab likes it"],"answerIndex":1,"explanation":"Both threats must be covered.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"The main message of Week 3 is:","options":["AMP is a one-time checklist","AMP is a cycle that turns biosafety and biosecurity into a managed, continually improving system","AMP is only for managers","AMP is only for chemicals"],"answerIndex":1,"explanation":"That is the central idea.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which review question asks about sustaining biorisk management?","options":["Explain the role of Performance in sustaining the system","Name the lab colour","List the staff names","Describe the car park"],"answerIndex":0,"explanation":"Performance sustains the system.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which best describes 'continual cycle'?","options":["A line that ends","A loop that repeats, feeding results into new assessment","A single event","A random pattern"],"answerIndex":1,"explanation":"It is a loop.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which AMP component asks 'Is the control working?'","options":["Assessment","Mitigation","Performance","Planning"],"answerIndex":2,"explanation":"Performance verifies that controls are working and sustained.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"The output of Assessment is best described as:","options":["Documented control measures","A prioritised risk register","Audit findings","Corrective actions"],"answerIndex":1,"explanation":"Assessment produces a prioritised risk register.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"In the GeneXpert TB example, which step belongs to Performance rather than Mitigation?","options":["Processing specimens in a biosafety cabinet","Issuing N95 respirators","Supervisors checking compliance weekly","Writing a cartridge-loading SOP"],"answerIndex":2,"explanation":"Weekly supervisor checks monitor the controls, which is Performance.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which PDCA step corresponds to Mitigation in the AMP model?","options":["Plan","Do","Check","Act"],"answerIndex":1,"explanation":"Do (implement controls) matches Mitigation.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"A near miss is reported during Performance monitoring. According to the cycle, the next step is:","options":["Close the file and stop","Feed the finding back into a new Assessment","Remove the controls","Wait for the next annual review"],"answerIndex":1,"explanation":"Results from Performance reshape the next Assessment.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Mitigation carried out without Assessment leads to:","options":["Perfect control of all hazards","Effort spent on low risks while real hazards go unmanaged","No cost","Faster testing"],"answerIndex":1,"explanation":"Controls without knowing which risks matter waste effort.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which standard underpins the AMP model?","options":["ISO 15189","CEN Workshop Agreement CWA 15793","ISO 17025","GP17"],"answerIndex":1,"explanation":"The AMP model underpins CWA 15793, the Laboratory Biorisk Management Standard.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Restricting reagent access to trained staff is which type of control?","options":["Security control","Engineering control","PPE","Elimination"],"answerIndex":0,"explanation":"Access restriction is a security control in the Mitigation component.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Which of these is a Performance activity?","options":["Engineering controls such as biosafety cabinets","Internal and external audits or inspections of the biorisk programme","Selecting the lowest-risk agent","Writing the risk register"],"answerIndex":1,"explanation":"Audits and inspections verify performance.","topic":"Week 3: The AMP Model of Biorisk Management"},{"question":"Why is the AMP model drawn as a cycle rather than a straight line?","options":["Because it has no end point; new agents, staff and incidents keep feeding back into assessment","Because cycles are cheaper to print","Because it repeats only once a year","Because it removes the need for PDCA"],"answerIndex":0,"explanation":"Biorisk management never finishes, so the cycle keeps repeating.","topic":"Week 3: The AMP Model of Biorisk Management"}]},{"id":"mls101-lecture-04","order":4,"title":"Week 4: Laboratory Risk Assessment","notesHtml":"<div class=\"card\">\n    <h2>Learning outcomes</h2>\n    <ul>\n      <li>Define laboratory risk assessment and explain its purpose</li>\n      <li>Describe common risk assessment methods and when to use them</li>\n      <li>Identify biological, chemical, physical and procedural hazards</li>\n      <li>Characterise and evaluate risk using likelihood and consequence</li>\n      <li>Explain how human factors influence biorisk and risk controls</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>1. What is laboratory risk assessment?</h2>\n    <p>A structured, evidence-informed process for identifying what could cause harm, estimating how likely it is to occur, judging the possible consequences, and deciding whether more controls are needed.</p>\n    <table>\n      <tr><th>Term</th><th>Meaning</th><th>Example</th></tr>\n      <tr><td><b>Hazard</b></td><td>Something with the potential to cause harm</td><td>Infectious blood, a corrosive reagent, a broken centrifuge rotor</td></tr>\n      <tr><td><b>Exposure pathway</b></td><td>How a person or environment could contact the hazard</td><td>Splash to eyes, aerosol inhalation, needlestick</td></tr>\n      <tr><td><b>Risk</b></td><td>The likelihood of harm and the severity of its consequences, in a given context</td><td>Depends on task, exposure route, people, equipment and controls</td></tr>\n    </table>\n    <p class=\"key\">Do not confuse hazard with risk. A hazard may be present, but the risk depends on the task, the exposure route, the people, the equipment and the controls.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>2. Why assess laboratory risk?</h2>\n    <ul>\n      <li><b>Protect people:</b> reduce occupational exposure, injury and laboratory-associated infection.</li>\n      <li><b>Protect specimens and results:</b> prevent contamination, sample mix-ups and invalid results.</li>\n      <li><b>Select proportionate controls:</b> match practice, PPE, equipment and facilities to the actual risk.</li>\n      <li><b>Support preparedness:</b> plan for spills, sharps injuries, equipment failure and other incidents.</li>\n      <li><b>Improve accountability:</b> document decisions, assign responsibilities and review changing conditions.</li>\n      <li><b>Use resources wisely:</b> prioritise the controls that reduce risk most effectively.</li>\n    </ul>\n    <p>Assessment should be done <b>before work begins</b> and revisited when procedures, personnel, equipment, agents or facilities change.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>3. A practical risk assessment workflow</h2>\n    <ol>\n      <li><b>Gather information:</b> agent, specimen, procedure, equipment, location and personnel.</li>\n      <li><b>Evaluate the risk:</b> consider exposure routes, likelihood and consequence.</li>\n      <li><b>Choose a control strategy:</b> decide what risk level is acceptable for the activity.</li>\n      <li><b>Implement controls:</b> apply practices, equipment, PPE and facility safeguards.</li>\n      <li><b>Review and improve:</b> check whether controls work; revise after a change or incident.</li>\n    </ol>\n    <p class=\"key\">Remember PDCA: plan the work, do it with controls, check performance, act on findings. Risk assessment is iterative, not a one-time form.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>4. Risk assessment methods</h2>\n    <table>\n      <tr><th>Method</th><th>How it works</th><th>Useful for</th></tr>\n      <tr><td><b>Qualitative</b></td><td>Descriptive categories (low, moderate, high) from professional judgement</td><td>Routine procedures, rapid screening, early planning</td></tr>\n      <tr><td><b>Semi-quantitative</b></td><td>Scores for likelihood and consequence, combined in a risk matrix</td><td>Prioritising several hazards consistently</td></tr>\n      <tr><td><b>Quantitative</b></td><td>Numerical data or models to estimate probability or impact</td><td>Situations with reliable data and suitable models</td></tr>\n      <tr><td><b>Task-based or protocol-driven</b></td><td>Breaks a procedure into steps and examines hazards, routes and controls at each step</td><td>Specimen processing, centrifugation, aliquoting, waste handling</td></tr>\n      <tr><td><b>What-if, checklist or team review</b></td><td>Structured questions and staff experience to find failure points</td><td>Audits, new methods, changes, incident follow-up</td></tr>\n    </table>\n    <p class=\"key\">No single method fits every activity. Choose one that matches the complexity, uncertainty and potential consequences.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>5. Identifying laboratory hazards</h2>\n    <table>\n      <tr><th>Hazard group</th><th>Examples in an MLS lab</th><th>Possible harm or pathway</th></tr>\n      <tr><td><b>Biological</b></td><td>Blood, body fluids, cultures, contaminated surfaces, aerosols</td><td>Infection via mucosa, inhalation, broken skin or sharps</td></tr>\n      <tr><td><b>Chemical</b></td><td>Fixatives, disinfectants, acids, solvents, stains</td><td>Burns, irritation, poisoning or inhalation injury</td></tr>\n      <tr><td><b>Physical and equipment</b></td><td>Centrifuge failure, glass breakage, heat, electricity, noise</td><td>Cuts, impact injury, burns or electric shock</td></tr>\n      <tr><td><b>Ergonomic</b></td><td>Repetitive pipetting, prolonged microscope use, awkward posture</td><td>Musculoskeletal strain and fatigue</td></tr>\n      <tr><td><b>Process and environment</b></td><td>Poor workflow, overcrowding, spills, poor ventilation or waste segregation</td><td>Exposure, cross-contamination and unsafe disposal</td></tr>\n    </table>\n    <p><b>Hazard prompts:</b> What is being handled? What step is performed? How could exposure occur? Who might be exposed? What controls are already in place?</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>6. Characterising risk: likelihood × consequence</h2>\n    <p>A risk matrix helps a team compare hazards consistently. It supports judgement; it does not replace it.</p>\n    <table>\n      <tr><th>Likelihood ↓ / Consequence →</th><th>1 Minor</th><th>2 Moderate</th><th>3 Major</th><th>4 Severe</th></tr>\n      <tr><td><b>4 Likely</b></td><td>Moderate</td><td>High</td><td>High</td><td>Very high</td></tr>\n      <tr><td><b>3 Possible</b></td><td>Low</td><td>Moderate</td><td>High</td><td>Very high</td></tr>\n      <tr><td><b>2 Unlikely</b></td><td>Low</td><td>Low</td><td>Moderate</td><td>High</td></tr>\n      <tr><td><b>1 Rare</b></td><td>Low</td><td>Low</td><td>Low</td><td>Moderate</td></tr>\n    </table>\n    <ul>\n      <li><b>Likelihood:</b> how probable is exposure or an incident, considering frequency, route and existing controls?</li>\n      <li><b>Consequence:</b> how serious could the outcome be for staff, patients, the public or the environment?</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>7. Evaluating risk and selecting controls</h2>\n    <p>After estimating the initial risk, decide whether existing controls are adequate. Add controls, then reassess the <b>residual risk</b>.</p>\n    <ol>\n      <li><b>Eliminate or substitute:</b> avoid the hazardous step where feasible; use a safer method or reagent.</li>\n      <li><b>Engineering controls:</b> biological safety cabinet where indicated, sealed centrifuge cups or rotors, splash shields.</li>\n      <li><b>Administrative controls:</b> validated SOPs, training, restricted access, maintenance, clear workflow and incident reporting.</li>\n      <li><b>PPE:</b> lab coat or gown, gloves, eye or face protection, and respiratory protection when the assessment requires it.</li>\n    </ol>\n    <p class=\"key\">PPE is important, but it should not be the only control when stronger, feasible controls are available.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>8. Human factors in biorisk assessment</h2>\n    <p>Risk depends not only on the agent and equipment, but also on how people work in real conditions.</p>\n    <ul>\n      <li><b>Competence and training:</b> unfamiliarity with a procedure can increase errors.</li>\n      <li><b>Fatigue and workload:</b> long shifts, interruptions and rushing weaken attention.</li>\n      <li><b>Communication:</b> unclear labels, handovers or SOPs can cause wrong steps.</li>\n      <li><b>Safety culture:</b> fear of blame discourages reporting of near misses.</li>\n      <li><b>Ergonomics and layout:</b> poor reach, clutter and cramped benches increase slips and spills.</li>\n      <li><b>Supervision and compliance:</b> controls fail if expectations, resources or monitoring are inadequate.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>9. Case study: serum aliquoting in a busy lab</h2>\n    <p>A trainee aliquots patient serum near the end of a busy shift. The bench is crowded, eye protection is not being worn, and a tube is opened by force. A splash lands close to the trainee's face.</p>\n    <h3>Risk factors identified</h3>\n    <ul>\n      <li>The biological material may contain infectious agents.</li>\n      <li>A splash to the eyes, nose or mouth is a plausible exposure route.</li>\n      <li>Fatigue, clutter and poor technique increase the chance of an incident.</li>\n      <li>Existing controls appear incomplete.</li>\n    </ul>\n    <h3>Working through the assessment</h3>\n    <ul>\n      <li><b>Hazards:</b> potentially infectious serum, and forceful opening of the tube.</li>\n      <li><b>Most plausible exposure route:</b> splash to the mucous membranes of the eyes, nose or mouth. Contaminated gloves and surfaces are secondary concerns.</li>\n      <li><b>Immediate controls:</b> wear splash protection; open tubes with a suitable technique or device; declutter the bench.</li>\n      <li><b>Longer-term controls:</b> follow the SOP; train and supervise; plan work to reduce rushing.</li>\n      <li><b>After the event:</b> if exposure occurred, follow the institution's exposure-response procedure promptly. Document the event, review root causes and reassess the risk.</li>\n    </ul>\n    <p class=\"key\">Initial risk: possible exposure with potentially serious consequences. Use the local risk matrix. Do not rely on a universal score.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>Summary: key takeaways</h2>\n    <ul>\n      <li><b>Hazard</b> is what can cause harm. <b>Risk</b> is how likely harm is, and how bad it could be, in context.</li>\n      <li>Assess before work starts, and again when anything changes.</li>\n      <li>Choose a method that fits the activity. Methods range from qualitative to quantitative.</li>\n      <li>Judge risk as likelihood times consequence, using the local matrix.</li>\n      <li>Controls go from eliminate, through engineering and administrative, to PPE. PPE is never enough alone.</li>\n      <li>Human factors such as fatigue, layout and safety culture can undermine even good controls.</li>\n    </ul>\n  </div>","flashcards":[{"front":"What is laboratory risk assessment?","back":"A structured, evidence-informed process for identifying what could cause harm, estimating likelihood, judging consequences, and deciding whether more controls are needed.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What is a hazard?","back":"Something with the potential to cause harm, e.g. infectious blood, a corrosive reagent, a broken rotor.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What is an exposure pathway?","back":"How a person or environment could contact the hazard, e.g. splash to eyes, aerosol inhalation, needlestick.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What is risk?","back":"The likelihood of harm and the severity of its consequences in a given context.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Why is hazard different from risk?","back":"A hazard may be present, but risk depends on the task, exposure route, people, equipment and controls.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Name six reasons to assess laboratory risk.","back":"Protect people; protect specimens and results; select proportionate controls; support preparedness; improve accountability; use resources wisely.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"When should risk assessment be done?","back":"Before work begins, and revisited when procedures, personnel, equipment, agents or facilities change.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Name the five steps of the practical workflow.","back":"Gather information; evaluate the risk; choose a control strategy; implement controls; review and improve.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"How does the risk assessment workflow relate to PDCA?","back":"Plan the work, do it with controls, check performance, act on findings.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Is risk assessment a one-time form?","back":"No. It is iterative.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What is a qualitative method?","back":"Uses descriptive categories (low, moderate, high) from professional judgement.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What is a semi-quantitative method?","back":"Assigns scores to likelihood and consequence and combines them in a risk matrix.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What is a quantitative method?","back":"Uses numerical data or models to estimate probability or impact.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What is a task-based method?","back":"Breaks a procedure into steps and examines hazards, routes and controls at each step.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Which method suits specimen processing and centrifugation?","back":"Task-based or protocol-driven.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"When is a what-if or checklist review useful?","back":"Audits, new methods, changes and incident follow-up.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Is there a single method that fits every activity?","back":"No. Choose one proportionate to complexity, uncertainty and consequences.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Name the five hazard groups in an MLS lab.","back":"Biological, chemical, physical or equipment, ergonomic, process or environment.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Give examples of biological hazards in a lab.","back":"Blood, body fluids, cultures, contaminated surfaces, aerosols.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Give examples of chemical hazards in a lab.","back":"Fixatives, disinfectants, acids, solvents, stains.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Give examples of physical or equipment hazards.","back":"Centrifuge failure, glass breakage, heat, electricity, noise.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Give an example of an ergonomic hazard.","back":"Repetitive pipetting, prolonged microscope use, awkward posture.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What are the five hazard prompts?","back":"What is being handled? What step is performed? How could exposure occur? Who might be exposed? What controls exist?","topic":"Week 4: Laboratory Risk Assessment"},{"front":"In the risk matrix, what is a 'Likely' and 'Severe' rating?","back":"Very high.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"In the risk matrix, what is 'Rare' and 'Minor'?","back":"Low.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What does likelihood consider?","back":"Frequency, route and existing controls.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What does consequence consider?","back":"How serious the outcome could be for staff, patients, the public or the environment.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What is residual risk?","back":"The risk that remains after additional controls are applied and reassessed.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What is the first control option in the hierarchy?","back":"Eliminate or substitute the hazardous step where feasible.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Give an example of an engineering control.","back":"Biological safety cabinet, sealed centrifuge cups, splash shields.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Give an example of an administrative control.","back":"Validated SOPs, training, restricted access, maintenance, incident reporting.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Why should PPE not be the only control?","back":"Stronger, feasible controls may be available; PPE alone is not enough.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"Name six human factors in biorisk.","back":"Competence and training; fatigue and workload; communication; safety culture; ergonomics and layout; supervision and compliance.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"How does fear of blame affect safety?","back":"It discourages reporting of near misses.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"What is the most plausible exposure route in the serum aliquoting case?","back":"Splash to the mucous membranes of the eyes, nose or mouth.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"In the serum case, what is the immediate control?","back":"Splash protection, a suitable opening technique or device, and decluttering the bench.","topic":"Week 4: Laboratory Risk Assessment"},{"front":"After an exposure, what should happen?","back":"Follow the institution's exposure-response procedure promptly, document the event, and review root causes.","topic":"Week 4: Laboratory Risk Assessment"}],"questions":[{"question":"Laboratory risk assessment is best described as:","options":["A one-off form","A structured, evidence-informed process to identify hazards, estimate likelihood and consequence, and decide on controls","A type of PPE","A cleaning schedule"],"answerIndex":1,"explanation":"It is a structured, iterative process.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"The purpose of risk assessment includes:","options":["Protecting people and specimens","Only saving money","Only writing reports","Only passing inspection"],"answerIndex":0,"explanation":"It protects people, specimens and results, among other aims.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"When should risk assessment be done?","options":["After an accident only","Before work begins and when things change","Once a decade","Only on Mondays"],"answerIndex":1,"explanation":"Before work and when conditions change.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"A hazard is:","options":["Something with the potential to cause harm","A reagent label","A type of glove","A laboratory timetable"],"answerIndex":0,"explanation":"A hazard can cause harm.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Infectious blood in a lab is an example of:","options":["A hazard","An exposure pathway","A control","A consequence"],"answerIndex":0,"explanation":"It is something that can cause harm.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"A splash to the eyes is an example of:","options":["A hazard","An exposure pathway","A risk matrix","A control"],"answerIndex":1,"explanation":"It is a route by which harm can occur.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Risk is best defined as:","options":["The hazard itself","The likelihood of harm and its severity in context","The number of staff","The cost of PPE"],"answerIndex":1,"explanation":"Risk combines likelihood and severity.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which statement is correct?","options":["Hazard and risk are identical","A hazard may be present, but the risk depends on task, route, people and controls","Risk is always high when a hazard exists","Hazards cannot change"],"answerIndex":1,"explanation":"Risk depends on context.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Protecting specimens and results is achieved by:","options":["Preventing contamination and sample mix-ups","Using more coffee","Ignoring the SOP","Reducing staff"],"answerIndex":0,"explanation":"Contamination and mix-ups affect results.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"The workflow's first step is:","options":["Choose a control strategy","Gather information","Implement controls","Review and improve"],"answerIndex":1,"explanation":"Gather information first.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"In the workflow, the step after evaluating risk is:","options":["Gather information","Choose a control strategy","Review and improve","Plan a holiday"],"answerIndex":1,"explanation":"Choose a control strategy.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"The final step of the workflow is:","options":["Gather information","Evaluate the risk","Implement controls","Review and improve"],"answerIndex":3,"explanation":"Review and improve closes the loop.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"The workflow is linked to which cycle?","options":["PDCA","SWOT","PEST","SMART"],"answerIndex":0,"explanation":"Plan, Do, Check, Act.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Risk assessment is best described as:","options":["Iterative, not a one-time form","A single signature","A permanent document","A fixed score for all labs"],"answerIndex":0,"explanation":"It is iterative.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which is a qualitative method?","options":["Matrix scoring only","Using low, moderate and high categories from judgement","Using statistical models","Using numerical data only"],"answerIndex":1,"explanation":"Qualitative uses categories.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which method combines likelihood and consequence scores in a matrix?","options":["Qualitative","Semi-quantitative","Quantitative","Ergonomic"],"answerIndex":1,"explanation":"Semi-quantitative uses scores.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which method uses numerical data or models?","options":["Qualitative","Semi-quantitative","Quantitative","Checklist"],"answerIndex":2,"explanation":"Quantitative uses numbers.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"A method that breaks a procedure into steps is:","options":["Task-based","Qualitative only","Quantitative only","Team review"],"answerIndex":0,"explanation":"Task-based breaks procedures down.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which method is best for aliquoting and centrifugation?","options":["Task-based or protocol-driven","Random guessing","Only quantitative","No method"],"answerIndex":0,"explanation":"Task-based suits these procedures.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which method suits audits and incident follow-up?","options":["What-if, checklist or team review","Quantitative modelling only","Qualitative only","None"],"answerIndex":0,"explanation":"Structured team review fits.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"No single method fits every activity. The best choice is:","options":["Always quantitative","Proportionate to complexity, uncertainty and consequences","Always qualitative","Always what-if"],"answerIndex":1,"explanation":"Match the method to the activity.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which is a biological hazard?","options":["Glass breakage","Blood","Solvent","Noise"],"answerIndex":1,"explanation":"Blood is biological.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which is a chemical hazard?","options":["Stains","Electric cords","Noise","Heat"],"answerIndex":0,"explanation":"Stains are chemical.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which is a physical or equipment hazard?","options":["Centrifuge failure","Stain","Blood","Culture"],"answerIndex":0,"explanation":"Centrifuge failure is physical.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Repetitive pipetting is an example of:","options":["Ergonomic hazard","Biological hazard","Chemical hazard","Radiological hazard"],"answerIndex":0,"explanation":"It is ergonomic.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Overcrowding and poor workflow are:","options":["Process or environment hazards","Biological hazards only","Chemical hazards","Physical hazards"],"answerIndex":0,"explanation":"They are process hazards.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which harm is linked to a biological hazard?","options":["Burns","Infection via inhalation or sharps","Eye strain only","Hearing loss only"],"answerIndex":1,"explanation":"Infection pathways.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which harm is linked to a chemical hazard?","options":["Infection","Burns or poisoning","Musculoskeletal strain only","Electric shock only"],"answerIndex":1,"explanation":"Chemical harms.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which harm is linked to a physical hazard?","options":["Cuts or electric shock","Infection only","Poisoning only","Fatigue only"],"answerIndex":0,"explanation":"Physical harms.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which harm is linked to an ergonomic hazard?","options":["Musculoskeletal strain","Infection","Chemical burns","Electric shock"],"answerIndex":0,"explanation":"Ergonomic strain.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"A hazard prompt asks:","options":["What is being handled?","What is the weather?","What is the menu?","What is the salary?"],"answerIndex":0,"explanation":"Hazard prompts are about the work.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Likelihood considers:","options":["Frequency, route and existing controls","Only staff salaries","Only the colour of the lab","Only the price of reagents"],"answerIndex":0,"explanation":"Frequency, route, controls.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Consequence considers:","options":["How serious the outcome could be for people or the environment","How many tubes are used","The number of windows","The name of the lecturer"],"answerIndex":0,"explanation":"Seriousness of outcome.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"In the matrix, a 'Likely' and 'Severe' rating is:","options":["Low","Moderate","High","Very high"],"answerIndex":3,"explanation":"Very high.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"In the matrix, a 'Rare' and 'Minor' rating is:","options":["Low","Moderate","High","Very high"],"answerIndex":0,"explanation":"Low.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"In the matrix, 'Possible' and 'Major' is:","options":["Low","Moderate","High","Very high"],"answerIndex":2,"explanation":"High.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"In the matrix, 'Unlikely' and 'Moderate' is:","options":["Low","Moderate","High","Very high"],"answerIndex":0,"explanation":"Low.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"A risk matrix is used to:","options":["Replace judgement","Compare hazards consistently and support judgement","Remove the need for SOPs","Measure staff height"],"answerIndex":1,"explanation":"It supports judgement.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Residual risk means:","options":["The risk before any controls","The risk remaining after controls are added and reassessed","The risk from waste","The risk from PPE only"],"answerIndex":1,"explanation":"After controls.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"What is the first control option?","options":["PPE","Administrative","Eliminate or substitute the hazardous step","Engineering"],"answerIndex":2,"explanation":"Eliminate or substitute comes first.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"A biological safety cabinet is an example of:","options":["Engineering control","Administrative control","PPE","Elimination"],"answerIndex":0,"explanation":"Engineering control.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Validated SOPs and training are examples of:","options":["Engineering controls","Administrative controls","Eliminate controls","Substitution only"],"answerIndex":1,"explanation":"Administrative controls.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Gloves and lab coats are examples of:","options":["PPE","Engineering controls","Elimination","Administrative controls"],"answerIndex":0,"explanation":"PPE.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Why should PPE not be the only control?","options":["It is too cheap","Stronger, feasible controls may be available","It is not allowed","It is only for visitors"],"answerIndex":1,"explanation":"PPE is not enough alone.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which control is the most preferred where feasible?","options":["PPE","Elimination of the hazardous step","Signs only","Training only"],"answerIndex":1,"explanation":"Eliminate first.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which human factor involves unclear labels or handovers?","options":["Communication","Ergonomics","Fatigue","Competence"],"answerIndex":0,"explanation":"Communication.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which human factor involves long shifts and interruptions?","options":["Fatigue and workload","Competence","Communication","Supervision"],"answerIndex":0,"explanation":"Fatigue.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which human factor involves fear of blame?","options":["Safety culture","Ergonomics","Competence","Fatigue"],"answerIndex":0,"explanation":"Safety culture.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Poor reach, clutter and cramped benches relate to:","options":["Ergonomics and layout","Communication","Competence","Supervision"],"answerIndex":0,"explanation":"Layout.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Controls fail when expectations and monitoring are inadequate. This is:","options":["Supervision and compliance","Communication","Ergonomics","Competence"],"answerIndex":0,"explanation":"Supervision and compliance.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Unfamiliarity with a procedure can increase:","options":["Errors","Sunlight","Staff numbers","Cost"],"answerIndex":0,"explanation":"Competence affects errors.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"In the serum aliquoting case, which is a plausible exposure route?","options":["Splash to eyes, nose or mouth","Heat from the sun","Water from taps","Printer ink"],"answerIndex":0,"explanation":"Splash is the most plausible.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"In the serum case, which factor increases the chance of an incident?","options":["Fatigue, clutter and poor technique","Good lighting","A clean bench","Full PPE"],"answerIndex":0,"explanation":"Fatigue, clutter and poor technique.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"In the serum case, the controls appear to be:","options":["Complete","Incomplete","Unnecessary","Excessive"],"answerIndex":1,"explanation":"Existing controls appear incomplete.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"What is an immediate control for the serum case?","options":["Splash protection and a suitable tube-opening technique","Shouting","Ignoring the bench","Working faster"],"answerIndex":0,"explanation":"Immediate controls.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"What is a longer-term control for the serum case?","options":["Training, supervision and planning work to reduce rushing","Removing eye protection","Working at night","Skipping SOPs"],"answerIndex":0,"explanation":"Longer-term controls.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"After an exposure in the serum case, what should happen?","options":["Ignore it","Follow the exposure-response procedure, document and review root causes","Blame the trainee only","Continue working"],"answerIndex":1,"explanation":"Follow the procedure and review.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Why should risk be assessed again after a new instrument?","options":["Because instruments change hazards and workflow","Because it is a holiday","Because staff like forms","Because it is cheaper"],"answerIndex":0,"explanation":"New hazards may appear.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which is a risk difference the lecturer uses for centrifuges?","options":["The hazard is the broken rotor; the risk depends on how likely and how severe harm is in context","The hazard is the cost","The risk is the colour","No difference"],"answerIndex":0,"explanation":"Hazard versus risk.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which best describes the lecture's view of PPE?","options":["Sufficient alone","Important but not the only control","Unnecessary","Only for visitors"],"answerIndex":1,"explanation":"Important, not sufficient alone.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which of these is a process or environment hazard?","options":["Poor ventilation","Stain","Blood","Heat from a centrifuge"],"answerIndex":0,"explanation":"Poor ventilation is environmental.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which is a sign that controls may have failed?","options":["Repeated near misses","Clean records","Trained staff","Good ventilation"],"answerIndex":0,"explanation":"Near misses show gaps.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"The most important reason to choose a method proportionately is:","options":["To use more paper","To match effort to the real risk","To avoid all controls","To impress"],"answerIndex":1,"explanation":"Proportionate effort.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which statement about risk assessment methods is correct?","options":["One method fits all","No single method fits every activity","Quantitative always wins","Qualitative is never used"],"answerIndex":1,"explanation":"No single method.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which best describes 'characterise risk'?","options":["Describe the likelihood and consequence of harm","Count the chairs","Name the lab","Choose the uniform"],"answerIndex":0,"explanation":"Likelihood and consequence.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which is the best definition of an exposure pathway?","options":["The route by which a hazard could contact a person or environment","The price of a glove","The shape of a bench","The lab timetable"],"answerIndex":0,"explanation":"A route of contact.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"What does 'proportionate controls' mean?","options":["Controls that match the actual risk","Controls that cost the most","Controls that nobody uses","Controls that are secret"],"answerIndex":0,"explanation":"Match to the actual risk.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which statement describes the iterative nature of risk assessment?","options":["It is completed once and filed","It is revisited as conditions change","It is never reviewed","It is only for managers"],"answerIndex":1,"explanation":"Revisited as conditions change.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which best describes 'hazard identification'?","options":["Finding what could cause harm","Measuring the lab","Choosing staff","Buying chairs"],"answerIndex":0,"explanation":"Finding hazards.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"Which statement about human factors is correct?","options":["They do not affect risk","They can undermine even good written controls","They only matter for managers","They are unrelated to SOPs"],"answerIndex":1,"explanation":"They undermine controls.","topic":"Week 4: Laboratory Risk Assessment"},{"question":"The main message of Week 4 is:","options":["Risk assessment is a one-off paper exercise","Assess risk structurally, choose proportionate controls, and review them as conditions change, with people in mind","PPE is the only control","Hazards and risks are identical"],"answerIndex":1,"explanation":"That is the central message.","topic":"Week 4: Laboratory Risk Assessment"}]},{"id":"mls101-lecture-05","order":5,"title":"Week 5: Risk Mitigation and Control Strategies","notesHtml":"<div class=\"card\">\n    <h2>Learning outcomes</h2>\n    <ul>\n      <li>Explain the principles of risk mitigation</li>\n      <li>Apply the hierarchy of controls to laboratory hazards</li>\n      <li>Select controls for biological, chemical, physical and ergonomic risks</li>\n      <li>Differentiate biosafety from biosecurity measures</li>\n      <li>Evaluate whether workplace controls are effective</li>\n    </ul>\n    <p class=\"key\">Core message: risk mitigation is not simply wearing PPE. It is selecting, implementing and checking controls that reduce risk to an acceptable level.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>1. Principles of risk mitigation</h2>\n    <p>Risk mitigation means actions that reduce the likelihood and/or consequences of harm. Its principles:</p>\n    <ul>\n      <li><b>Risk-based:</b> match controls to the agent, procedure, people and facility.</li>\n      <li><b>Prevention first:</b> prevent exposure rather than relying on response after an incident.</li>\n      <li><b>Layered protection:</b> combine practices, equipment, facility safeguards and PPE.</li>\n      <li><b>Practical and sustainable:</b> choose controls staff can use correctly and consistently.</li>\n      <li><b>Review and improve:</b> monitor performance and reassess after changes or incidents.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>2. The hierarchy of controls (start at the top)</h2>\n    <table>\n      <tr><th>Level</th><th>Meaning</th><th>Lab example</th></tr>\n      <tr><td>1. Elimination</td><td>Remove the hazard or hazardous step</td><td>Stop an unnecessary open-tube step; avoid recapping needles</td></tr>\n      <tr><td>2. Substitution</td><td>Replace with a safer material or method</td><td>Less hazardous reagent or safer processing method, once validated</td></tr>\n      <tr><td>3. Engineering</td><td>Isolate people from the hazard</td><td>Certified biological safety cabinet (BSC), sealed centrifuge cups, splash guards, ventilation</td></tr>\n      <tr><td>4. Administrative</td><td>Procedures, training, scheduling, signs, supervision</td><td>SOPs, competency checks, access rules, workload planning, hand-hygiene protocol</td></tr>\n      <tr><td>5. PPE</td><td>Personal barrier; last line of defence</td><td>Lab coat or gown, suitable gloves, eye and face protection, respiratory protection when indicated</td></tr>\n    </table>\n    <p class=\"key\">Prefer higher-level controls where feasible. PPE stays essential when residual risk persists.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>3. Controlling biological hazards</h2>\n    <ul>\n      <li><b>Specimen handling:</b> treat unknown specimens as potentially infectious; use leak-proof containers and safe transport.</li>\n      <li><b>Aerosol-generating work:</b> use a risk-assessed procedure, a certified BSC when indicated, and sealed centrifuge cups or rotors.</li>\n      <li><b>Sharps and spills:</b> avoid recapping, discard sharps immediately, and follow the approved spill procedure.</li>\n    </ul>\n    <h3>Match the control to the exposure route</h3>\n    <table>\n      <tr><th>Route</th><th>Example</th><th>Key controls</th></tr>\n      <tr><td>Inhalation</td><td>Aerosols from vortexing or centrifugation</td><td>Containment, sealed rotors, safe technique</td></tr>\n      <tr><td>Splash or contact</td><td>Droplets reaching eyes, mouth or broken skin</td><td>BSC where indicated, eye/face protection, gloves</td></tr>\n      <tr><td>Percutaneous</td><td>Needlestick or contaminated sharp</td><td>Safety devices, no recapping, sharps container</td></tr>\n    </table>\n    <p class=\"key\">Choose precautions from a task-specific risk assessment, not from the organism name alone.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>4. Hazards are not only biological</h2>\n    <table>\n      <tr><th>Class</th><th>Examples</th><th>Mitigation</th></tr>\n      <tr><td>Chemical</td><td>Corrosives, solvents, disinfectants</td><td>Substitute where possible; segregate and store correctly; local exhaust; consult the SDS</td></tr>\n      <tr><td>Physical</td><td>Centrifuge failure, broken glass, electricity, heat</td><td>Inspect equipment; use guards; balance rotors; isolate faulty equipment</td></tr>\n      <tr><td>Ergonomic</td><td>Micropipetting, repetitive work, prolonged standing</td><td>Adjust workstation; suitable pipettes; rotate tasks; brief breaks</td></tr>\n      <tr><td>Fire / environment</td><td>Flammables, gas, spills, poor waste handling</td><td>Control ignition sources; keep exits and extinguishers clear; segregate waste</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>5. Biosafety and biosecurity: related but different</h2>\n    <table>\n      <tr><th></th><th>Biosafety</th><th>Biosecurity</th></tr>\n      <tr><td><b>Purpose</b></td><td>Prevent accidental exposure or accidental release</td><td>Prevent loss, theft, misuse, diversion or intentional release</td></tr>\n      <tr><td><b>Examples</b></td><td>Containment and work practices; decontamination and waste management; PPE and competency; incident reporting</td><td>Controlled access to work areas; secure storage and inventory; authorised handling and transfer; reporting missing materials</td></tr>\n    </table>\n    <p class=\"key\">Memory aid: biosafety protects against accidents; biosecurity protects against unauthorised access and misuse.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>6. Safe work practices and PPE (HGCER)</h2>\n    <ul>\n      <li><b>H, Hand hygiene:</b> before and after tasks, and after glove removal.</li>\n      <li><b>G, Gloves:</b> choose for the task; change when contaminated or damaged.</li>\n      <li><b>C, Lab coat:</b> fasten properly; keep it in designated work areas.</li>\n      <li><b>E, Eye/face:</b> use when there is a splash or impact risk.</li>\n      <li><b>R, Respiratory:</b> use only as indicated by assessment and programme; fit and competency matter.</li>\n    </ul>\n    <p>PPE has limits. It depends on correct selection, fit, donning and doffing, replacement and disposal. Never eat, drink, mouth-pipette or handle phones with contaminated gloves. PPE does not make an unsafe procedure safe.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>7. Workplace safety assurance (PDCA)</h2>\n    <table>\n      <tr><th>Step</th><th>What happens</th></tr>\n      <tr><td>PLAN</td><td>Assess hazards, choose controls, assign owners</td></tr>\n      <tr><td>DO</td><td>Implement SOPs, training, equipment and supplies</td></tr>\n      <tr><td>CHECK</td><td>Inspect, audit, observe technique, review incidents and near misses</td></tr>\n      <tr><td>ACT</td><td>Correct gaps, document actions, reassess</td></tr>\n    </table>\n    <h3>Evidence of assurance</h3>\n    <ul>\n      <li>Equipment certification and maintenance records (e.g. BSC certification, centrifuge checks)</li>\n      <li>Training and competency records; documented SOP review</li>\n      <li>Stock of PPE, disinfectants and spill supplies; correct waste segregation</li>\n      <li>Incident and near-miss trends, with corrective actions closed on time</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>8. Pre-task checklist</h2>\n    <ul>\n      <li>Have I identified the biological, chemical, physical and ergonomic hazards?</li>\n      <li>Do I understand the procedure and the likely exposure routes?</li>\n      <li>Are the containment devices and safety equipment available and fit for use?</li>\n      <li>Are the SOP, disinfectant, waste container and spill supplies ready?</li>\n      <li>Am I trained and competent for this task?</li>\n      <li>Are PPE and hand hygiene appropriate to the assessed risk?</li>\n      <li>Do I know how to report an incident and where to get help?</li>\n      <li>Will I stop and reassess if conditions change?</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>Knowledge check (for discussion)</h2>\n    <ol>\n      <li>Define risk mitigation and explain how it differs from risk assessment.</li>\n      <li>Rank the five levels of the hierarchy of controls, most to least preferred.</li>\n      <li>Give two engineering controls for reducing aerosol exposure during specimen processing.</li>\n      <li>State one key difference between biosafety and biosecurity.</li>\n      <li>A centrifuge tube breaks during operation. Name three controls that could reduce risk before, during or after this event.</li>\n      <li>Why is PPE last in the hierarchy, even though it is essential?</li>\n    </ol>\n  </div>","flashcards":[{"front":"What is risk mitigation?","back":"Actions that reduce the likelihood and/or consequences of harm. It is more than wearing PPE.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What does 'risk-based' mean in mitigation?","back":"Controls are matched to the agent, procedure, people and facility.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What does 'prevention first' mean?","back":"Prevent exposure before relying on response after an incident.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What does 'layered protection' mean?","back":"Combining practices, equipment, facility safeguards and PPE.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What should a control be, for it to be chosen?","back":"Practical and sustainable: staff can use it correctly and consistently.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"Name the five levels of the hierarchy of controls.","back":"Elimination, substitution, engineering, administrative, PPE.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What is elimination?","back":"Remove the hazard or hazardous step entirely (the most preferred control).","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What is substitution?","back":"Replace the hazard with a safer material or method.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What is an engineering control? Give an example.","back":"Isolates people from the hazard, e.g. a certified biological safety cabinet.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What is an administrative control? Give examples.","back":"Procedures, training, scheduling, signs and supervision (SOPs, competency checks).","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"Why is PPE the last level?","back":"It is a personal barrier and the last line of defence; it does not remove the hazard.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"Is a clean bench the same as a biological safety cabinet?","back":"No. A clean bench is not a BSC and is not a substitute for it.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"Name three engineering controls for aerosol exposure.","back":"Certified BSC, sealed centrifuge cups or rotors, ventilation or splash guards.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"Why avoid recapping needles?","back":"It is a common cause of percutaneous injury; it is an elimination-type control.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What is inhalation exposure and its key control?","back":"Breathing in aerosols from vortexing or centrifugation; key control is containment with sealed rotors and safe technique.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What is percutaneous exposure and its key control?","back":"A needlestick or cut; key controls are safety devices, no recapping and a sharps container.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What is splash or contact exposure?","back":"Droplets reaching eyes, mouth or broken skin; controls include BSC where indicated, eye/face protection and gloves.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"How should precautions be chosen?","back":"From a task-specific risk assessment, not from the organism name alone.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"Name the four non-biological hazard classes covered.","back":"Chemical, physical, ergonomic, fire/environment.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"How do you mitigate a chemical hazard?","back":"Substitute where possible, segregate and store correctly, use local exhaust, consult the SDS.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"How do you mitigate an ergonomic hazard?","back":"Adjust the workstation, use suitable pipettes, rotate tasks, take brief breaks.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What is the biosafety purpose?","back":"Prevent accidental exposure or accidental release of agents.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What is the biosecurity purpose?","back":"Prevent loss, theft, misuse, diversion or intentional release of agents.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"Memory aid for biosafety vs biosecurity?","back":"Biosafety protects against accidents; biosecurity protects against unauthorised access and misuse.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What does HGCER stand for?","back":"Hand hygiene, Gloves, Coat (lab coat), Eye/face, Respiratory.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"When should hand hygiene be done?","back":"Before and after tasks, and after glove removal.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"Name one PPE limitation.","back":"It depends on correct selection, fit, donning and doffing, replacement and disposal.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What does PDCA stand for?","back":"Plan, Do, Check, Act.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What happens in the CHECK step?","back":"Inspect, audit, observe technique, review incidents and near misses.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"Give examples of evidence of safety assurance.","back":"Equipment certification records, training and competency records, PPE and spill stock, incident trends.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"front":"What should you do if conditions change during a task?","back":"Stop and reassess the risk before continuing.","topic":"Week 5: Risk Mitigation and Control Strategies"}],"questions":[{"question":"Risk mitigation means:","options":["Only wearing PPE","Actions that reduce the likelihood and/or consequences of harm","Recording incidents only","Sterilising equipment"],"answerIndex":1,"explanation":"Mitigation reduces likelihood and/or consequences.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is a core message of Week 5?","options":["PPE alone keeps the lab safe","Mitigation means selecting, implementing and checking controls","Biosafety cabinets need no checks","Only chemicals need controls"],"answerIndex":1,"explanation":"Controls must be selected, implemented and checked.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which principle says controls should match the agent, procedure, people and facility?","options":["Prevention first","Layered protection","Risk-based","Review and improve"],"answerIndex":2,"explanation":"Risk-based mitigation matches controls to context.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"'Prevention first' means:","options":["Respond quickly after an incident","Prevent exposure before relying on response","Prevent only chemical exposure","Wait for incident reports"],"answerIndex":1,"explanation":"Prevention comes before response.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which principle combines practices, equipment, facility safeguards and PPE?","options":["Layered protection","Risk-based","Practical and sustainable","Review and improve"],"answerIndex":0,"explanation":"Layering uses several safeguards together.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"The hierarchy of controls is used to:","options":["Rank staff seniority","Start with the most effective controls and work down","Choose uniforms","Schedule shifts"],"answerIndex":1,"explanation":"Higher-level controls are preferred.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is the most preferred control in the hierarchy?","options":["PPE","Administrative","Elimination","Engineering"],"answerIndex":2,"explanation":"Elimination removes the hazard entirely.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is the second level in the hierarchy?","options":["Elimination","Substitution","Engineering","Administrative"],"answerIndex":1,"explanation":"The order is elimination, substitution, engineering, administrative, PPE.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Replacing a hazardous reagent with a safer one is:","options":["Elimination","Substitution","Engineering","PPE"],"answerIndex":1,"explanation":"Substitution replaces with a safer option.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"A certified biological safety cabinet is an example of:","options":["Elimination","Substitution","Engineering control","PPE"],"answerIndex":2,"explanation":"BSCs isolate people from the hazard.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"SOPs, training and supervision are:","options":["Engineering controls","Administrative controls","PPE","Elimination"],"answerIndex":1,"explanation":"These are administrative controls.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is the last line of defence in the hierarchy?","options":["Engineering","Administrative","PPE","Substitution"],"answerIndex":2,"explanation":"PPE is last because it only protects the person.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Why is PPE placed last?","options":["It is not useful","It is a personal barrier and does not remove the hazard","It is expensive","It is only for chemicals"],"answerIndex":1,"explanation":"PPE protects the individual but leaves the hazard present.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"A clean bench is:","options":["A biological safety cabinet","A substitute for a BSC","Not a biological safety cabinet","A form of PPE"],"answerIndex":2,"explanation":"A clean bench is not a BSC.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is an engineering control for aerosols?","options":["Gloves","Sealed centrifuge cups","Training records","Hand washing"],"answerIndex":1,"explanation":"Sealed cups contain aerosols.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Avoiding recapping of needles is an example of:","options":["Elimination of a risky step","Engineering control","PPE","Substitution"],"answerIndex":0,"explanation":"It removes a hazardous step.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which route is linked to aerosols from vortexing?","options":["Inhalation","Percutaneous","Ingestion","Splash"],"answerIndex":0,"explanation":"Aerosols are inhaled.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"A needlestick is which exposure route?","options":["Inhalation","Percutaneous","Mucocutaneous","Ingestion"],"answerIndex":1,"explanation":"Percutaneous means through the skin.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Droplets on eyes or broken skin are:","options":["Percutaneous","Splash or contact","Inhalation","Ingestion"],"answerIndex":1,"explanation":"Splash or contact exposure.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"For a percutaneous risk, a key control is:","options":["Recapping needles","Safety devices and a sharps container","Eating in the lab","Wearing sandals"],"answerIndex":1,"explanation":"Safety devices and sharps containers prevent injury.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"For splash risk, which combination fits best?","options":["BSC where indicated, eye/face protection, gloves","Only a lab coat","Only ventilation","Only training"],"answerIndex":0,"explanation":"Multiple controls match the route.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Precautions should be chosen based on:","options":["The organism name alone","A task-specific risk assessment","Lab location only","Cost alone"],"answerIndex":1,"explanation":"Risk assessment drives precautions.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is NOT a non-biological hazard class in the lecture?","options":["Chemical","Physical","Ergonomic","Ionising"],"answerIndex":3,"explanation":"Ionising sources are radiological and not in this lecture's table.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Chemical hazards are mitigated by:","options":["Recapping","Substitution where possible, correct storage, local exhaust and the SDS","Ignoring labels","Mouth pipetting"],"answerIndex":1,"explanation":"These are the listed chemical controls.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Centrifuge failure or broken glass is which hazard class?","options":["Chemical","Physical","Ergonomic","Biological"],"answerIndex":1,"explanation":"They are physical hazards.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Balancing centrifuge rotors is a control for:","options":["Chemical hazard","Physical hazard","Biological hazard","Ergonomic hazard"],"answerIndex":1,"explanation":"Balancing reduces physical risk from failure.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Micropipetting for long periods is which hazard?","options":["Ergonomic","Chemical","Radiological","Fire"],"answerIndex":0,"explanation":"Repetitive work is ergonomic.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"An ergonomic control is:","options":["Rotating tasks and taking breaks","Eating at the bench","Removing guards","Ignoring posture"],"answerIndex":0,"explanation":"Task rotation and breaks reduce strain.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Flammable solvents and poor waste handling belong to:","options":["Fire and environment","Ergonomic","Physical only","Biological"],"answerIndex":0,"explanation":"Fire and environment hazards.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Biosafety is mainly about:","options":["Theft prevention","Preventing accidental exposure or accidental release","Controlling diversion","Controlling access keys"],"answerIndex":1,"explanation":"Biosafety is about accidents.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Biosecurity is mainly about:","options":["Preventing accidental spills","Preventing loss, theft or misuse","Ergonomic posture","Fire drills"],"answerIndex":1,"explanation":"Biosecurity protects against intentional or unauthorised actions.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is a biosecurity measure?","options":["Decontamination","Controlled access to work areas","Hand hygiene","Waste segregation"],"answerIndex":1,"explanation":"Access control is biosecurity.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Reporting missing biological materials is:","options":["Biosafety","Biosecurity","Ergonomics","Radiation safety"],"answerIndex":1,"explanation":"It is about accountability for materials.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is a biosafety measure?","options":["Secure inventory","Authorised transfer","Incident reporting and emergency response","Restricted storage"],"answerIndex":2,"explanation":"Incident response protects people.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"'Biosafety protects against accidents' is a:","options":["Memory aid","Chemical rule","Ergonomic rule","Radiation rule"],"answerIndex":0,"explanation":"It is a memory aid from the lecture.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"In HGCER, the letter G stands for:","options":["Glasses","Gloves","Gowns","Germicide"],"answerIndex":1,"explanation":"G is for gloves.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"In HGCER, the letter E stands for:","options":["Eye or face protection","Equipment","Exhaust","Emergency"],"answerIndex":0,"explanation":"E is eye/face protection.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Hand hygiene should be done:","options":["Only at the end of the day","Before and after tasks, and after glove removal","Only if visibly dirty","Never with gloves"],"answerIndex":1,"explanation":"Hand hygiene is frequent.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Gloves should be changed when:","options":["Once a week","Contaminated or damaged","Never","Only at lunch"],"answerIndex":1,"explanation":"Replace them when compromised.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which practice is unsafe?","options":["Changing contaminated gloves","Mouth-pipetting","Fastening a lab coat","Using eye protection for splash risk"],"answerIndex":1,"explanation":"Mouth-pipetting is never allowed.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"PPE alone:","options":["Makes any procedure safe","Does not make an unsafe procedure safe","Replaces the BSC","Removes the need for SOPs"],"answerIndex":1,"explanation":"PPE complements other controls.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is a limitation of PPE?","options":["It depends on fit, donning, doffing and disposal","It removes all hazards","It needs no training","It is always reusable"],"answerIndex":0,"explanation":"Correct use matters.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"PDCA stands for:","options":["Plan, Do, Check, Act","Prepare, Deliver, Clean, Assess","Protect, Direct, Control, Audit","Plan, Document, Clean, Advise"],"answerIndex":0,"explanation":"PDCA is the assurance cycle.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which step assigns owners and sets controls?","options":["Do","Check","Plan","Act"],"answerIndex":2,"explanation":"Planning assigns owners.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Implementing SOPs and training happens in which step?","options":["Plan","Do","Check","Act"],"answerIndex":1,"explanation":"Do is implementation.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Reviewing incidents and near misses happens in:","options":["Plan","Do","Check","Act"],"answerIndex":2,"explanation":"Check includes review.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Correcting gaps and reassessing happens in:","options":["Plan","Do","Check","Act"],"answerIndex":3,"explanation":"Act follows up the findings.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is evidence of assurance?","options":["Equipment certification records","Unlabelled waste","Expired SOPs","Missing training logs"],"answerIndex":0,"explanation":"Certification records show assurance.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is NOT good evidence of assurance?","options":["Training and competency records","Documented SOP review","Incident trend records with closed actions","No record of maintenance"],"answerIndex":3,"explanation":"Missing records are not evidence.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Before starting a task, you should check:","options":["Only your phone","Hazards, containment, SOP, training, PPE, incident reporting","Only the time","Only the lab temperature"],"answerIndex":1,"explanation":"The pre-task checklist covers these.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"If conditions change during a task, you should:","options":["Keep going","Stop and reassess","Ask a friend","Remove the gloves"],"answerIndex":1,"explanation":"Reassess when conditions change.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"A specimen that arrives with leaking packaging is a:","options":["Transport risk","Disposal risk","Analysis risk","Radiological risk"],"answerIndex":0,"explanation":"Transport packaging is the control.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which control best reduces an aerosol risk during centrifugation?","options":["Sealed rotors and safe technique","Eating nearby","Using no gloves","Turning off the lights"],"answerIndex":0,"explanation":"Containment and safe technique reduce aerosols.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"A safety control 'that staff can use correctly and consistently' reflects which principle?","options":["Practical and sustainable","Risk-based","Prevention first","Layered"],"answerIndex":0,"explanation":"Practicality is the principle.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is a key benefit of the hierarchy?","options":["It ranks PPE highest","It prefers controls that remove or isolate the hazard","It only applies to chemicals","It replaces training"],"answerIndex":1,"explanation":"Higher levels remove or isolate hazards.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which control is administrative?","options":["Certified BSC","Sealed centrifuge cups","Workload planning","Splash guards"],"answerIndex":2,"explanation":"Workload planning is administrative.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is a physical hazard control?","options":["Use guards and isolate faulty equipment","Recap needles","Wear gloves only","Eat at the bench"],"answerIndex":0,"explanation":"Guards and isolation control physical risk.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is an example of a fire and environment control?","options":["Control ignition sources","Mouth-pipetting","Recapping","Ignoring spills"],"answerIndex":0,"explanation":"Remove ignition sources.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"What should happen after a spill?","options":["Ignore it","Follow the approved spill-response procedure","Clean with bare hands","Leave for the next shift"],"answerIndex":1,"explanation":"Follow the approved procedure.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which indicates the control system may be weak?","options":["Repeated non-conformities","Trained staff","Certified equipment","Complete records"],"answerIndex":0,"explanation":"Repeated non-conformities show gaps.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Why is correct selection of PPE important?","options":["It is cheaper","It depends on the assessed risk, fit and correct use","It is only needed for tests","It replaces hand hygiene"],"answerIndex":1,"explanation":"PPE must match the risk.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"The biggest safety principle in this lecture is:","options":["Assume controls work without checking","Select, implement and check controls to keep risk acceptable","Use PPE as the only control","Rely on incident counts alone"],"answerIndex":1,"explanation":"Controls must be checked.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which combination is an example of layered protection?","options":["A BSC, SOPs, gloves and eye protection","Gloves only","Training only","A clean bench only"],"answerIndex":0,"explanation":"Several layers together.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"For a splash risk, which control is an engineering control?","options":["Gloves","Eye protection","Splash guards","SOPs"],"answerIndex":2,"explanation":"Splash guards are engineering controls.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which control reduces ergonomic risk at a micropipetting station?","options":["Adjusting the workstation and suitable pipettes","Standing still all day","Ignoring posture","Using the wrong pipette"],"answerIndex":0,"explanation":"Good design and tools reduce strain.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which of these best reflects a 'review and improve' principle?","options":["Monitoring performance and reassessing after changes","Ignoring near misses","Keeping old SOPs forever","Removing audits"],"answerIndex":0,"explanation":"Review is ongoing.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Week 6 of MLS 101 covers:","options":["Biorisk management performance","Radiation physics","Chemical storage only","Ergonomics only"],"answerIndex":0,"explanation":"Week 6 is about performance measurement.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is a safe practice in the lab?","options":["Eating with contaminated gloves","Keeping phones away from contaminated gloves","Mouth-pipetting","Recapping sharps"],"answerIndex":1,"explanation":"Avoid handling phones with contaminated gloves.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"A lab coat should be:","options":["Left open","Fastened properly and kept in designated areas","Worn outside the lab","Shared between rooms"],"answerIndex":1,"explanation":"Fastened and designated use.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Respiratory protection should be used:","options":["Always, for everything","Only as indicated by assessment and programme","Never","Only for chemicals"],"answerIndex":1,"explanation":"It depends on assessment and fit.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is a correct reason to change gloves?","options":["They are a different colour","They are contaminated or damaged","It is Monday","They feel warm"],"answerIndex":1,"explanation":"Change when compromised.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Why must the risk be assessed for each task?","options":["Because all tasks are identical","Because controls must match the specific procedure and people","Because only managers read it","Because it is a legal form only"],"answerIndex":1,"explanation":"Context determines controls.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"A 'practical and sustainable' control is one that:","options":["Only works in a lab inspection","Staff can use correctly and consistently","Costs nothing","Replaces training"],"answerIndex":1,"explanation":"It must work in daily practice.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which best describes residual risk?","options":["Risk remaining after controls are applied","Risk before any controls","Risk from PPE only","Risk from chemicals only"],"answerIndex":0,"explanation":"Residual risk remains after controls.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is correct about PPE in the hierarchy?","options":["It is the first level","It is essential but last level","It is optional","It replaces engineering controls"],"answerIndex":1,"explanation":"PPE is essential but last.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Substitution is only used when:","options":["It is convenient","It is validated and safer","It is cheaper","It removes the need for SOPs"],"answerIndex":1,"explanation":"Validation and safety are required.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which statement about BSCs is correct?","options":["A BSC replaces correct technique","A BSC is an engineering control that needs correct use and certification","A BSC needs no maintenance","A BSC is PPE"],"answerIndex":1,"explanation":"BSCs need certification and correct technique.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which step includes reviewing incidents and near misses?","options":["Plan","Do","Check","Act"],"answerIndex":2,"explanation":"Check includes review.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is an example of administrative control for access?","options":["Locked storage","Controlled access rules","Splash guards","Sealed rotors"],"answerIndex":1,"explanation":"Access rules are administrative.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"What is the purpose of incident reporting?","options":["To blame staff","To identify trends, causes and corrective actions","To avoid paperwork","To close the lab"],"answerIndex":1,"explanation":"Reporting drives learning.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is the best immediate response to a sharps injury?","options":["Ignore it","Follow the lab's approved injury response procedure and report it","Keep working","Recap the needle"],"answerIndex":1,"explanation":"Follow the procedure and report.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which best explains why PPE is not enough?","options":["It is too expensive","It does not remove the hazard and can fail if misused","It is only for patients","It is not needed"],"answerIndex":1,"explanation":"PPE can fail or be misused.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Risk mitigation aims to reduce risk to:","options":["Zero always","An acceptable level","The highest level","Only the chemical level"],"answerIndex":1,"explanation":"The aim is an acceptable level.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which of these is a physical hazard in the lab?","options":["Solvent","Broken glass","Pathogen","Stain"],"answerIndex":1,"explanation":"Broken glass is physical.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"In a medical lab, which hazard class does the lecture say often compounds biological hazards?","options":["Radiological","Chemical and physical","Ergonomic only","None"],"answerIndex":1,"explanation":"Chemical and physical hazards compound risk.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which exposure route is linked to broken skin?","options":["Splash or contact","Inhalation","Ingestion only","None"],"answerIndex":0,"explanation":"Broken skin is a splash/contact route.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which best describes the purpose of a checklist before a task?","options":["To delay work","To confirm controls are ready before starting","To replace SOPs","To record staff names only"],"answerIndex":1,"explanation":"It confirms readiness.","topic":"Week 5: Risk Mitigation and Control Strategies"},{"question":"Which is the correct order of the hierarchy from top to bottom?","options":["PPE, administrative, engineering, substitution, elimination","Elimination, substitution, engineering, administrative, PPE","Engineering, elimination, PPE, substitution, administrative","Administrative, PPE, elimination, engineering, substitution"],"answerIndex":1,"explanation":"Elimination is top; PPE is bottom.","topic":"Week 5: Risk Mitigation and Control Strategies"}]},{"id":"mls101-lecture-06","order":6,"title":"Week 6: Biorisk Management Performance","notesHtml":"<div class=\"card\">\n    <h2>Learning outcomes</h2>\n    <ul>\n      <li>Explain the meaning and scope of biorisk management performance</li>\n      <li>State why performance measurement is important in a laboratory</li>\n      <li>Identify indicators of effective biorisk management</li>\n      <li>Describe practical methods for measuring performance</li>\n      <li>Outline a stepwise process for evaluating performance and improving controls</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>1. Key concepts</h2>\n    <p><b>Biorisk management performance</b> is the extent to which a laboratory's policies, people, practices and facilities control biological risks and achieve intended safety outcomes.</p>\n    <table>\n      <tr><th>Term</th><th>Meaning</th></tr>\n      <tr><td>Biorisk</td><td>The likelihood of an adverse event and the severity of its consequences, considered in context</td></tr>\n      <tr><td>Measurement</td><td>Collecting and analysing evidence against defined indicators, targets or criteria</td></tr>\n      <tr><td>Performance</td><td>How well planned activities and controls are implemented, and whether they achieve the intended result. It includes activities (training, maintenance, audits) and outcomes (fewer exposures, reliable controls, completed corrective actions)</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>2. Why measure performance?</h2>\n    <ul>\n      <li><b>Detect weaknesses early:</b> find gaps before they contribute to an incident.</li>\n      <li><b>Demonstrate accountability:</b> provide evidence for management review and audits.</li>\n      <li><b>Check control effectiveness:</b> verify that procedures, equipment, PPE and training work in practice.</li>\n      <li><b>Learn from incidents:</b> identify trends, contributing factors and recurring failures.</li>\n      <li><b>Support decisions:</b> direct resources toward priority risks.</li>\n      <li><b>Drive improvement:</b> set targets, assign actions and check whether changes worked.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>3. Types of indicators</h2>\n    <table>\n      <tr><th>Indicator type</th><th>What it measures</th><th>Lab example</th></tr>\n      <tr><td>Input / capacity</td><td>Resources available to manage risk</td><td>Trained biosafety lead; functioning safety cabinet</td></tr>\n      <tr><td>Process / activity</td><td>Whether planned actions are completed</td><td>% of staff completing competency assessment</td></tr>\n      <tr><td>Output</td><td>Immediate deliverables</td><td>Risk assessments reviewed; equipment checks completed</td></tr>\n      <tr><td>Outcome</td><td>Whether controls improve safety</td><td>Reduction in repeated unsafe practices or uncontained spills</td></tr>\n      <tr><td>Learning / improvement</td><td>Whether findings lead to action</td><td>% of audit actions closed by due date</td></tr>\n    </table>\n    <p class=\"key\">Use a balanced set of indicators. No single number describes the whole safety system.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>4. Indicators of effective biorisk management</h2>\n    <table>\n      <tr><th>Domain</th><th>Example indicator</th><th>What it reveals</th></tr>\n      <tr><td>Training and competence</td><td>% of relevant staff with current competence assessment</td><td>Whether staff can demonstrate required skills</td></tr>\n      <tr><td>Risk assessment</td><td>% of high-risk procedures reviewed on schedule</td><td>Whether assessments remain current</td></tr>\n      <tr><td>Equipment and facilities</td><td>% of checks or maintenance completed on time</td><td>Reliability of safety-critical equipment</td></tr>\n      <tr><td>Work practices</td><td>Observed compliance with critical SOP steps</td><td>Whether procedures are followed in practice</td></tr>\n      <tr><td>Incident learning</td><td>% of events reviewed; corrective actions closed on time</td><td>Whether the organisation learns and responds</td></tr>\n      <tr><td>Waste and decontamination</td><td>Audit compliance with segregation and decontamination</td><td>Reliability of routine controls</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>5. Leading and lagging indicators</h2>\n    <table>\n      <tr><th>Type</th><th>Measures</th><th>Examples</th></tr>\n      <tr><td><b>Leading</b></td><td>Preventive activity before harm occurs</td><td>Competency checks completed; equipment certification current; risk assessments reviewed after changes; corrective actions closed on time</td></tr>\n      <tr><td><b>Lagging</b></td><td>Events or consequences after they occur</td><td>Occupational exposure incidents; sharps injuries or laboratory-acquired infections; spills requiring response; repeated non-conformities</td></tr>\n    </table>\n    <p class=\"key\">Interpret together. A low incident count does not automatically prove good performance, because under-reporting may hide problems. Pair outcome data with audits, observations, near-miss reports and staff feedback.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>6. How performance is measured</h2>\n    <ul>\n      <li><b>Record review:</b> training logs, risk assessments, maintenance records, incident reports.</li>\n      <li><b>Audit or inspection:</b> compare practice with approved SOPs, standards and local requirements.</li>\n      <li><b>Trend analysis:</b> compare results across time, units, procedures or targets.</li>\n      <li><b>Direct observation:</b> observe critical work steps using a consistent checklist.</li>\n      <li><b>Staff feedback:</b> interviews, brief surveys, debriefs and near-miss discussions.</li>\n      <li><b>Management review:</b> prioritise gaps, assign owners and agree improvement actions.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>7. Building a useful indicator</h2>\n    <p>A useful indicator is <b>specific, measurable, relevant to risk, feasible to collect</b> and <b>linked to an action</b>.</p>\n    <h3>Worked example: training completion rate</h3>\n    <p>(Relevant staff who completed required training ÷ total relevant staff) × 100</p>\n    <p>If 36 of 40 relevant staff completed training: (36 ÷ 40) × 100 = <b>90%</b></p>\n    <table>\n      <tr><th>Specification</th><th>Example</th></tr>\n      <tr><td>Definition</td><td>Percentage of relevant staff with current required training</td></tr>\n      <tr><td>Numerator / denominator</td><td>36 completed / 40 relevant staff</td></tr>\n      <tr><td>Frequency / owner</td><td>Monthly; laboratory manager or biosafety lead</td></tr>\n      <tr><td>Target / action</td><td>Illustrative target ≥95%; investigate the gap, plan catch-up training, recheck next month</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>8. Six steps in evaluating performance</h2>\n    <ol>\n      <li><b>Define scope:</b> which laboratory, activity, risks and period?</li>\n      <li><b>Set criteria:</b> choose standards, objectives, indicators and targets.</li>\n      <li><b>Collect evidence:</b> records, observations, audit findings and feedback.</li>\n      <li><b>Analyse results:</b> compare actual performance with criteria; identify trends.</li>\n      <li><b>Prioritise findings:</b> judge significance and potential effect on risk.</li>\n      <li><b>Act and follow up:</b> assign owners and deadlines; verify improvement.</li>\n    </ol>\n  </div>\n\n  <div class=\"card\">\n    <h2>9. Case study: recurring biosafety cabinet checks</h2>\n    <p>A teaching laboratory's monthly review finds only 70% of scheduled biosafety cabinet checks were documented on time. No exposure incident has been reported this semester.</p>\n    <ul>\n      <li><b>Initial reading:</b> the low completion rate is a process warning. No reported incident is reassuring, but it does not prove all controls work or that all events are reported.</li>\n      <li><b>Evidence to collect:</b> review schedules, checklists, equipment status, reasons for missed checks, staffing and training. Verify records against practice.</li>\n      <li><b>Corrective action:</b> confirm safety-critical checks are completed; assign an owner and a backup; simplify recording; train staff; address workload barriers.</li>\n      <li><b>Indicator:</b> on-time completion rate = checks completed on time ÷ checks scheduled × 100, tracked monthly.</li>\n      <li><b>Follow-up:</b> compare results with the target over later periods, and check the quality of the checks, not just the tick-box.</li>\n    </ul>\n    <p class=\"key\">Certification of a cabinet is not the same as a routine user check. Certification is a formal test by a qualified person; routine checks are the daily or periodic user checks that confirm the cabinet is working in use.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>Summary: key takeaways</h2>\n    <ul>\n      <li>Performance = how well controls are implemented and whether they work.</li>\n      <li>Use a balanced set of indicators, not one number.</li>\n      <li>Leading indicators prevent harm; lagging indicators reveal harm that has occurred.</li>\n      <li>A low incident count can hide under-reporting.</li>\n      <li>Good indicators are specific, measurable, relevant, feasible and linked to action.</li>\n      <li>The loop is evaluate, act, verify, then repeat.</li>\n    </ul>\n  </div>","flashcards":[{"front":"What is biorisk management performance?","back":"The extent to which a lab's policies, people, practices and facilities control biological risks and achieve intended safety outcomes.","topic":"Week 6: Biorisk Management Performance"},{"front":"Define 'biorisk'.","back":"The likelihood of an adverse event and the severity of its consequences, considered in context.","topic":"Week 6: Biorisk Management Performance"},{"front":"Define 'measurement' in this context.","back":"Collecting and analysing evidence against defined indicators, targets or criteria.","topic":"Week 6: Biorisk Management Performance"},{"front":"What does performance include?","back":"Activities (training, maintenance, audits) and outcomes (fewer exposures, reliable controls, completed corrective actions).","topic":"Week 6: Biorisk Management Performance"},{"front":"Give five reasons to measure performance.","back":"Detect weaknesses early, demonstrate accountability, check control effectiveness, learn from incidents, support decisions, drive improvement.","topic":"Week 6: Biorisk Management Performance"},{"front":"What is an input or capacity indicator?","back":"Measures resources available to manage risk, e.g. a trained biosafety lead or a working safety cabinet.","topic":"Week 6: Biorisk Management Performance"},{"front":"What is a process or activity indicator?","back":"Measures whether planned actions are completed, e.g. % of staff completing competency assessment.","topic":"Week 6: Biorisk Management Performance"},{"front":"What is an output indicator?","back":"Measures immediate deliverables, e.g. risk assessments reviewed or equipment checks completed.","topic":"Week 6: Biorisk Management Performance"},{"front":"What is an outcome indicator?","back":"Measures whether controls improve safety, e.g. reduction in repeated unsafe practices or uncontained spills.","topic":"Week 6: Biorisk Management Performance"},{"front":"What is a learning or improvement indicator?","back":"Measures whether findings lead to action, e.g. % of audit actions closed by the due date.","topic":"Week 6: Biorisk Management Performance"},{"front":"Why use a balanced set of indicators?","back":"No single number describes the whole safety system.","topic":"Week 6: Biorisk Management Performance"},{"front":"What is a leading indicator?","back":"Measures preventive activity before harm occurs, e.g. competency checks completed.","topic":"Week 6: Biorisk Management Performance"},{"front":"What is a lagging indicator?","back":"Measures events or consequences after they occur, e.g. sharps injuries or spills requiring response.","topic":"Week 6: Biorisk Management Performance"},{"front":"Why can a low incident count be misleading?","back":"Under-reporting may hide problems; pair it with audits, observations, near-miss reports and staff feedback.","topic":"Week 6: Biorisk Management Performance"},{"front":"Name six methods of measuring performance.","back":"Record review, audit or inspection, trend analysis, direct observation, staff feedback, management review.","topic":"Week 6: Biorisk Management Performance"},{"front":"What is record review?","back":"Checking training logs, risk assessments, maintenance records and incident reports.","topic":"Week 6: Biorisk Management Performance"},{"front":"What is trend analysis?","back":"Comparing results across time, units, procedures or targets.","topic":"Week 6: Biorisk Management Performance"},{"front":"What makes a useful indicator?","back":"Specific, measurable, relevant to risk, feasible to collect, and linked to an action.","topic":"Week 6: Biorisk Management Performance"},{"front":"Write the formula for training completion rate.","back":"(Relevant staff who completed required training ÷ total relevant staff) × 100.","topic":"Week 6: Biorisk Management Performance"},{"front":"If 36 of 40 staff completed training, what is the rate?","back":"90%: (36 ÷ 40) × 100.","topic":"Week 6: Biorisk Management Performance"},{"front":"What are the six steps in evaluating performance?","back":"Define scope, set criteria, collect evidence, analyse results, prioritise findings, act and follow up.","topic":"Week 6: Biorisk Management Performance"},{"front":"What is the first step in evaluating performance?","back":"Define scope: which lab, activity, risks and period.","topic":"Week 6: Biorisk Management Performance"},{"front":"What does 'prioritise findings' mean?","back":"Judge the significance of each finding and its potential effect on risk.","topic":"Week 6: Biorisk Management Performance"},{"front":"What does 'act and follow up' involve?","back":"Assigning owners and deadlines, then verifying that improvement happened.","topic":"Week 6: Biorisk Management Performance"},{"front":"What is the difference between certification and a routine user check of a biosafety cabinet?","back":"Certification is a formal test by a qualified person; routine checks are user checks that confirm the cabinet works in use.","topic":"Week 6: Biorisk Management Performance"},{"front":"Formula for on-time completion rate?","back":"Checks completed on time ÷ checks scheduled × 100, tracked monthly.","topic":"Week 6: Biorisk Management Performance"},{"front":"What does a low on-time completion rate mean in the case study?","back":"A process warning. It needs evidence and corrective action, even with no reported incidents.","topic":"Week 6: Biorisk Management Performance"},{"front":"What should be the owner of a monthly training indicator in the example?","back":"The laboratory manager or biosafety lead.","topic":"Week 6: Biorisk Management Performance"},{"front":"Why should indicators be linked to an action?","back":"So that a result leads to a decision, owner and follow-up, not just a number.","topic":"Week 6: Biorisk Management Performance"}],"questions":[{"question":"Biorisk management performance is:","options":["Only the number of incidents","The extent to which controls achieve intended safety outcomes","The cost of PPE","The number of staff"],"answerIndex":1,"explanation":"Performance covers controls and their outcomes.","topic":"Week 6: Biorisk Management Performance"},{"question":"Biorisk, as defined in the lecture, is:","options":["A type of PPE","The likelihood of an adverse event and the severity of its consequences","Any chemical spill","A laboratory building"],"answerIndex":1,"explanation":"Likelihood and severity together.","topic":"Week 6: Biorisk Management Performance"},{"question":"Measurement in this context means:","options":["Guessing results","Collecting and analysing evidence against defined indicators or targets","Counting staff only","Buying equipment"],"answerIndex":1,"explanation":"Measurement uses evidence and criteria.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which is an 'activity' included in performance?","options":["Training","Incident-free weather","Lab decor","Staff salaries only"],"answerIndex":0,"explanation":"Training is a performance activity.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which is an 'outcome' included in performance?","options":["Fewer exposures","Number of staff","Lab size","Brand name"],"answerIndex":0,"explanation":"Fewer exposures is an outcome.","topic":"Week 6: Biorisk Management Performance"},{"question":"Why measure performance?","options":["To punish staff","To detect weaknesses early","To avoid audits","To reduce training"],"answerIndex":1,"explanation":"Early detection prevents incidents.","topic":"Week 6: Biorisk Management Performance"},{"question":"Demonstrating accountability means:","options":["Hiding records","Providing evidence for management review and audits","Avoiding inspection","Deleting logs"],"answerIndex":1,"explanation":"Evidence supports review.","topic":"Week 6: Biorisk Management Performance"},{"question":"Checking control effectiveness verifies that:","options":["Procedures, equipment, PPE and training work in practice","Staff are happy","The building is painted","Cost is low"],"answerIndex":0,"explanation":"Controls must work in practice.","topic":"Week 6: Biorisk Management Performance"},{"question":"Learning from incidents involves:","options":["Ignoring trends","Identifying trends, contributing factors and recurring failures","Only firing staff","Stopping all work"],"answerIndex":1,"explanation":"Trend analysis drives improvement.","topic":"Week 6: Biorisk Management Performance"},{"question":"Directing resources toward priority risks is part of:","options":["Support decisions","Learning","Training","Cleaning"],"answerIndex":0,"explanation":"Support decisions use the evidence.","topic":"Week 6: Biorisk Management Performance"},{"question":"Setting targets and checking whether changes worked is:","options":["Drive improvement","Record review","Staff feedback","Trend analysis only"],"answerIndex":0,"explanation":"Improvement needs targets and checks.","topic":"Week 6: Biorisk Management Performance"},{"question":"A trained biosafety lead is an example of which indicator type?","options":["Input or capacity","Outcome","Output","Learning"],"answerIndex":0,"explanation":"It is a resource.","topic":"Week 6: Biorisk Management Performance"},{"question":"Staff completing competency assessments is a:","options":["Process or activity indicator","Outcome indicator","Input indicator","Lagging indicator"],"answerIndex":0,"explanation":"It measures completed actions.","topic":"Week 6: Biorisk Management Performance"},{"question":"Risk assessments reviewed is an example of:","options":["Output indicator","Outcome indicator","Input indicator","Leading only"],"answerIndex":0,"explanation":"It is an immediate deliverable.","topic":"Week 6: Biorisk Management Performance"},{"question":"Reduction in uncontained spills is an example of:","options":["Input indicator","Outcome indicator","Output indicator","Process indicator"],"answerIndex":1,"explanation":"It shows whether controls improved safety.","topic":"Week 6: Biorisk Management Performance"},{"question":"% of audit actions closed on time measures:","options":["Learning or improvement","Input","Output","Outcome only"],"answerIndex":0,"explanation":"It shows if findings led to action.","topic":"Week 6: Biorisk Management Performance"},{"question":"Why use a balanced set of indicators?","options":["It is cheaper","No single number describes the whole system","It is easier to write","It removes audits"],"answerIndex":1,"explanation":"Several views are needed.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which is a leading indicator?","options":["Sharps injuries","Spills requiring response","Equipment certification current","Occupational exposure incidents"],"answerIndex":2,"explanation":"Certification is preventive.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which is a lagging indicator?","options":["Competency checks completed","Risk assessments reviewed after changes","Occupational exposure incidents","Corrective actions closed on time"],"answerIndex":2,"explanation":"Exposure incidents are events that already happened.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which is a leading indicator?","options":["Repeated non-conformities","Laboratory-acquired infections","Risk assessments reviewed after changes","Spills requiring response"],"answerIndex":2,"explanation":"Reviews prevent harm.","topic":"Week 6: Biorisk Management Performance"},{"question":"Why can a low incident count be misleading?","options":["It always means good performance","Under-reporting may hide problems","It shows no staff","It means no SOPs"],"answerIndex":1,"explanation":"Under-reporting hides issues.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which should be paired with outcome data?","options":["Only incident counts","Audits, observations, near-miss reports and staff feedback","Only the lab temperature","Only the number of gloves"],"answerIndex":1,"explanation":"Multiple sources give the full picture.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which method compares practice with approved SOPs?","options":["Trend analysis","Audit or inspection","Staff feedback","Record review only"],"answerIndex":1,"explanation":"Audits compare practice to standards.","topic":"Week 6: Biorisk Management Performance"},{"question":"Comparing results across time or units is:","options":["Trend analysis","Direct observation","Management review","Record review"],"answerIndex":0,"explanation":"Trends compare across time and units.","topic":"Week 6: Biorisk Management Performance"},{"question":"Observing critical work steps with a checklist is:","options":["Direct observation","Staff survey","Trend analysis","Record review"],"answerIndex":0,"explanation":"Observation uses a consistent checklist.","topic":"Week 6: Biorisk Management Performance"},{"question":"Debriefs and near-miss discussions are:","options":["Staff feedback","Record review","Trend analysis","Audit"],"answerIndex":0,"explanation":"They gather staff views.","topic":"Week 6: Biorisk Management Performance"},{"question":"Prioritising gaps and assigning owners happens in:","options":["Management review","Direct observation","Trend analysis","Record review"],"answerIndex":0,"explanation":"Management review decides actions.","topic":"Week 6: Biorisk Management Performance"},{"question":"A useful indicator should be:","options":["Vague","Specific, measurable and linked to an action","Impossible to collect","Only about cost"],"answerIndex":1,"explanation":"These are the key features.","topic":"Week 6: Biorisk Management Performance"},{"question":"The formula for a training completion rate is:","options":["(Total staff ÷ completed) × 100","(Relevant staff who completed training ÷ total relevant staff) × 100","Completed × total × 100","Total ÷ completed"],"answerIndex":1,"explanation":"Numerator over denominator, times 100.","topic":"Week 6: Biorisk Management Performance"},{"question":"What is the rate if 36 of 40 relevant staff completed training?","options":["80%","85%","90%","95%"],"answerIndex":2,"explanation":"(36 ÷ 40) × 100 = 90%.","topic":"Week 6: Biorisk Management Performance"},{"question":"In the training example, the illustrative target is:","options":["50%","75%","95% or higher","100% always"],"answerIndex":2,"explanation":"The example target is ≥95%.","topic":"Week 6: Biorisk Management Performance"},{"question":"Who owns the monthly training indicator in the example?","options":["The security guard","The laboratory manager or biosafety lead","The patient","The cleaner"],"answerIndex":1,"explanation":"The manager or lead owns it.","topic":"Week 6: Biorisk Management Performance"},{"question":"What is the first step of evaluating performance?","options":["Act and follow up","Define scope","Prioritise findings","Analyse results"],"answerIndex":1,"explanation":"Scope defines what to evaluate.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which step sets standards, objectives, indicators and targets?","options":["Set criteria","Collect evidence","Analyse results","Act and follow up"],"answerIndex":0,"explanation":"Criteria are set before data is collected.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which step judges significance and effect on risk?","options":["Collect evidence","Analyse results","Prioritise findings","Define scope"],"answerIndex":2,"explanation":"Prioritising weighs significance.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which step compares actual performance with criteria?","options":["Analyse results","Define scope","Act and follow up","Collect evidence"],"answerIndex":0,"explanation":"Analysis compares to criteria.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which step assigns owners and deadlines?","options":["Set criteria","Act and follow up","Analyse results","Collect evidence"],"answerIndex":1,"explanation":"Action is assigned and followed up.","topic":"Week 6: Biorisk Management Performance"},{"question":"In the case study, only 70% of checks were on time. What is the first reading?","options":["The lab is perfectly safe","A process warning","A reason to close the lab","A sign of no staff"],"answerIndex":1,"explanation":"It is a process warning.","topic":"Week 6: Biorisk Management Performance"},{"question":"No incidents reported means:","options":["All controls work","Nothing to investigate ever","Reassurance, but not proof that all controls work or events are reported","The lab is certified"],"answerIndex":2,"explanation":"Reassurance is not proof.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which evidence should be collected first in the case study?","options":["Lab decoration","Schedules, checklists, equipment status and reasons for missed checks","Staff salaries","Parking records"],"answerIndex":1,"explanation":"Evidence checks the process.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which is an appropriate corrective action?","options":["Ignore the gap","Assign an owner and backup, simplify recording and train staff","Remove the cabinet","Stop all checks"],"answerIndex":1,"explanation":"Address owner, workload and training.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which indicator shows if the intervention worked?","options":["On-time completion rate of checks","Number of parking spaces","Lab colour","Staff height"],"answerIndex":0,"explanation":"Track the on-time rate.","topic":"Week 6: Biorisk Management Performance"},{"question":"Certification of a biosafety cabinet is:","options":["The same as a routine user check","A formal test by a qualified person","Done by the user daily","Not needed"],"answerIndex":1,"explanation":"Certification is a formal test.","topic":"Week 6: Biorisk Management Performance"},{"question":"Routine user checks of a cabinet:","options":["Confirm it is working in use","Replace certification","Are optional forever","Only matter in theft cases"],"answerIndex":0,"explanation":"Routine checks support daily use.","topic":"Week 6: Biorisk Management Performance"},{"question":"A low on-time check rate needs:","options":["No action","Verification of records against practice and corrective action","Only an email","Closing the lab"],"answerIndex":1,"explanation":"Verify and act.","topic":"Week 6: Biorisk Management Performance"},{"question":"Why verify the quality of checks, not just the tick-box?","options":["Tick-boxes are illegal","A completed box may not mean the check was done properly","Quality is unimportant","Staff cannot tick"],"answerIndex":1,"explanation":"Quality matters.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which is a process indicator in the case study?","options":["Checks completed on time as a percentage of scheduled","Lab walls painted","Number of visitors","Staff uniform colour"],"answerIndex":0,"explanation":"It measures completed activity.","topic":"Week 6: Biorisk Management Performance"},{"question":"Differentiate a leading indicator from a lagging indicator. Which pair is correct?","options":["Leading = after harm, lagging = before harm","Leading = before harm, lagging = after harm","Both are the same","Neither is useful"],"answerIndex":1,"explanation":"Leading is preventive; lagging is after harm.","topic":"Week 6: Biorisk Management Performance"},{"question":"For an indicator, the numerator is:","options":["The total number of staff","The count of cases meeting the condition","The reporting period","The target"],"answerIndex":1,"explanation":"The numerator counts what meets the condition.","topic":"Week 6: Biorisk Management Performance"},{"question":"For an indicator, the denominator is:","options":["The count of events meeting the condition","The total population or number scheduled","The target","The owner"],"answerIndex":1,"explanation":"The denominator is the total base.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which should be stated for every indicator?","options":["The lab's history only","Numerator, denominator and reporting period","Staff home addresses","Only the cost"],"answerIndex":1,"explanation":"These define the indicator.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which is an example of a laboratory-acquired infection measure?","options":["Lagging indicator","Leading indicator","Input indicator","Process indicator"],"answerIndex":0,"explanation":"It is an event after exposure.","topic":"Week 6: Biorisk Management Performance"},{"question":"Repeated non-conformities are best described as:","options":["A leading indicator","A lagging indicator","An input indicator","A learning indicator only"],"answerIndex":1,"explanation":"They are recorded after failures occur.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which indicator shows whether staff competencies are current?","options":["Staff competency assessment percentage","Lab size","Number of microscopes","Waste bin colour"],"answerIndex":0,"explanation":"It shows current competence.","topic":"Week 6: Biorisk Management Performance"},{"question":"Waste segregation audit compliance measures:","options":["Reliability of routine controls","Staff salaries","Lab decor","Patient numbers"],"answerIndex":0,"explanation":"It measures routine control reliability.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which is a sign that reporting may be weak?","options":["Many near-miss reports","Very few incidents with no near-miss reports","Regular audits","Closed corrective actions"],"answerIndex":1,"explanation":"Few reports can mean under-reporting.","topic":"Week 6: Biorisk Management Performance"},{"question":"Near-miss reports are valuable because they:","options":["Show blame","Reveal risks before harm occurs","Replace audits","Are required only for chemicals"],"answerIndex":1,"explanation":"They are leading information.","topic":"Week 6: Biorisk Management Performance"},{"question":"Staff feedback is useful because it:","options":["Replaces records","Adds the front-line view of risk and practice","Is always wrong","Is only for managers"],"answerIndex":1,"explanation":"It captures real practice.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which step confirms that improvement actually happened?","options":["Define scope","Collect evidence","Act and follow up","Set criteria"],"answerIndex":2,"explanation":"Follow-up verifies improvement.","topic":"Week 6: Biorisk Management Performance"},{"question":"Setting an illustrative target of 95% is part of:","options":["Set criteria","Define scope","Analyse results","Act"],"answerIndex":0,"explanation":"Targets are criteria.","topic":"Week 6: Biorisk Management Performance"},{"question":"A monthly review cycle is used to:","options":["Stop evaluation","Track indicators and act on gaps regularly","Replace SOPs","Avoid management"],"answerIndex":1,"explanation":"Regular review keeps performance on track.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which combination best describes a complete performance system?","options":["Records only","Indicators, measurement, evaluation, action and follow-up","Incidents only","PPE only"],"answerIndex":1,"explanation":"It is a continuous loop.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which is an example of a record that supports performance review?","options":["Training logs","Lab wallpaper","Staff hobbies","Parking tickets"],"answerIndex":0,"explanation":"Training logs are key records.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which best describes a 'review and improve' loop?","options":["Evaluate, act, verify, then repeat","Do once and stop","Only inspect yearly","Ignore findings"],"answerIndex":0,"explanation":"It is a continuous cycle.","topic":"Week 6: Biorisk Management Performance"},{"question":"Week 5 covered which topic that Week 6 builds on?","options":["Risk mitigation and control strategies","Radiation physics","Ergonomics only","Chemical storage only"],"answerIndex":0,"explanation":"Controls from Week 5 are measured in Week 6.","topic":"Week 6: Biorisk Management Performance"},{"question":"An indicator with no link to action is:","options":["Useful","Less useful, because results do not lead to decisions","Mandatory","Always accurate"],"answerIndex":1,"explanation":"Indicators should drive action.","topic":"Week 6: Biorisk Management Performance"},{"question":"The loop in the 'Plan, Do, Check, Act' cycle corresponds to performance evaluation as:","options":["Check = measure and evaluate, Act = improve","Check = buy PPE, Act = train","Plan = close the lab","Do = ignore data"],"answerIndex":0,"explanation":"Check evaluates; Act improves.","topic":"Week 6: Biorisk Management Performance"},{"question":"Why is evaluating performance done in steps?","options":["To make it longer","To ensure a structured, repeatable and evidence-based process","To avoid decisions","To satisfy inspectors only"],"answerIndex":1,"explanation":"A structured method gives reliable results.","topic":"Week 6: Biorisk Management Performance"},{"question":"Which is the best definition of 'performance' in this lecture?","options":["How expensive the lab is","How well planned activities and controls are implemented and whether they achieve the intended result","How many staff are present","How clean the bench looks"],"answerIndex":1,"explanation":"Performance is implementation plus results.","topic":"Week 6: Biorisk Management Performance"}]},{"id":"mls101-lecture-07","order":7,"title":"Lecture 7: Biorisks from Handling Clinical Samples","notesHtml":"<div class=\"card\">\n    <h2>1. What is a biological hazard?</h2>\n    <p>Biological hazards are conveyed by biological vectors, pathogenic microorganisms, toxins and bioactive substances. Examples:</p>\n    <ul>\n      <li>Bacteria, viruses and parasites</li>\n      <li>Venomous wildlife and insects, poisonous plants</li>\n      <li>Mosquitoes and other vectors carrying disease-causing agents</li>\n    </ul>\n    <p>They usually arise naturally, but can also come from deliberate or accidental release. They threaten humans, animals (including livestock) and plants. Consequences can include death and severe economic and environmental loss.</p>\n    <p class=\"key\">A medical laboratory scientist must know the possible biological agents that may be present in any clinical sample they work on.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>2. Why biological hazards are hard to assess</h2>\n    <table>\n      <tr><th>Characteristic</th><th>What it means</th></tr>\n      <tr><td><b>Agent diversity</b></td><td>From bacteria and viruses to toxins and insect infestations. Transmitted from the environment, animals, plants and other humans.</td></tr>\n      <tr><td><b>Routes of transmission</b></td><td>Airborne, ingestion, absorption (skin, eyes, mucous membranes, wounds), animal vectors (mosquitoes, ticks), bodily fluids (blood, mother-to-child, sexual).</td></tr>\n      <tr><td><b>Pathogenicity and virulence</b></td><td>Some agents cause severe disease at very low concentrations and multiply fast. For example, 1 to 10 aerosolised organisms of Lassa or Ebola virus can cause severe disease in humans.</td></tr>\n      <tr><td><b>Hazard identification</b></td><td>Microbes are invisible, so clinical signs and epidemiology are not enough. Specific diagnostic techniques are needed.</td></tr>\n      <tr><td><b>Endemic with epidemic potential</b></td><td>Biological hazards can be present in a community and are usually low-risk when the population is largely immune. Risk rises with crises, migration into endemic areas, or introduction into a non-immune population.</td></tr>\n      <tr><td><b>Sensitivity to climate and environment</b></td><td>Zoonoses and vector-borne diseases (malaria, dengue, Zika, Ebola) can change in incidence, lethality, geography or season due to climate, land-use changes and ecosystem changes. About 75% of emerging human infectious diseases evolved from zoonotic pathogens.</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>3. The chain of infection</h2>\n    <p>Infection passes through six links. Break any one link and transmission stops.</p>\n    <ol>\n      <li>Infectious agent (pathogen)</li>\n      <li>Reservoir</li>\n      <li>Portal of exit from the reservoir</li>\n      <li>Mode of transmission</li>\n      <li>Portal of entry into a host</li>\n      <li>Susceptible host</li>\n    </ol>\n    <p class=\"key\">Lab link: a sample is a reservoir. Your gloves, PPE, safe technique and disinfection work to break the chain at the exit, transmission or entry links.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>Summary: key takeaways</h2>\n    <ul>\n      <li>Biological hazards include microbes, toxins, vectors and bioactive substances.</li>\n      <li>Hazards are hard to assess because agents are diverse, invisible and transmitted in many ways.</li>\n      <li>A tiny dose can cause severe disease (Lassa, Ebola).</li>\n      <li>Endemic hazards become dangerous when immunity is low or conditions change.</li>\n      <li>Climate and land-use change are shifting disease patterns.</li>\n      <li>Infection needs all six links of the chain; breaking one stops it.</li>\n    </ul>\n  </div>","flashcards":[{"front":"What is a biological hazard?","back":"A hazard conveyed by biological vectors, pathogenic microorganisms, toxins or bioactive substances.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"Name four examples of biological hazards.","back":"Bacteria, viruses, parasites, venomous wildlife, poisonous plants, disease-carrying mosquitoes and insects.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"How do biological hazards usually arise?","back":"Naturally, but they can also result from deliberate or accidental release.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"Which living things besides humans can biological hazards affect?","back":"Animals (including livestock) and plants.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"What consequences can a biological hazard event have?","back":"Death, and severe economic and environmental losses.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"Why must a medical lab scientist know the possible agents in a sample?","back":"Because any clinical sample may carry biological agents that pose a risk.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"Why are biological hazards hard to assess?","back":"Agent diversity, many routes of transmission, low infectious doses, invisibility, endemic presence, and sensitivity to environment.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"What does 'agent diversity' mean?","back":"Hazards range from bacteria and viruses to toxins and insect infestations, transmitted from the environment, animals, plants and humans.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"Name the main routes of transmission.","back":"Airborne, ingestion, absorption (skin, eyes, mucous membranes, wounds), animal vectors, and bodily fluids.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"Give an example of an animal vector.","back":"Mosquitoes or ticks.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"Give examples of transmission through bodily fluids.","back":"Blood, mother-to-child, and sexual transmission.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"How many aerosolised Lassa or Ebola organisms can cause severe disease?","back":"As few as 1 to 10.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"Why is hazard identification hard for microbes?","back":"They are not visible, and clinical signs and epidemiology alone are not enough, so specific diagnostic techniques are needed.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"What does 'endemic with epidemic potential' mean?","back":"A hazard present in the community that is usually low-risk when people are largely immune, but can cause epidemics when conditions change.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"When does a non-endemic hazard pose a risk?","back":"When it is introduced to a new host community with no immunity.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"How does migration raise risk?","back":"People move from disease-free areas into endemic regions where they lack immunity.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"Which hazards are sensitive to climate and land-use changes?","back":"Zoonoses and vector-borne diseases such as malaria, dengue, Zika and Ebola.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"What share of emerging human infectious diseases evolved from zoonotic pathogens?","back":"About 75%.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"What is a reservoir in the chain of infection?","back":"The place where the infectious agent lives and multiplies, e.g. a human, animal or environment.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"What is a portal of exit?","back":"The route by which the agent leaves the reservoir.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"What is a portal of entry?","back":"The route by which the agent enters a new host.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"What is a susceptible host?","back":"A person who can be infected by the agent, e.g. one without immunity.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"How many links are in the chain of infection?","back":"Six: agent, reservoir, portal of exit, mode of transmission, portal of entry, susceptible host.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"How can the chain of infection be broken?","back":"By interrupting any one link, which stops transmission.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"front":"In the lab, what is a clinical sample in terms of the chain?","back":"A possible reservoir carrying the agent.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"}],"questions":[{"question":"Which of these is a biological hazard?","options":["Broken glass","A bacterium","A solvent","Heat"],"answerIndex":1,"explanation":"Bacteria are biological agents.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Biological hazards are conveyed by all EXCEPT:","options":["Biological vectors","Pathogenic microorganisms","Toxins","Ergonomic postures"],"answerIndex":3,"explanation":"Posture is ergonomic, not biological.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which is an example of a venomous wildlife hazard?","options":["A scorpion","A microscope","A centrifuge","A pipette"],"answerIndex":0,"explanation":"Venomous animals are biological hazards in the lecture's list.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Biological hazards usually arise:","options":["Only from deliberate release","Naturally, but can also arise from deliberate or accidental release","Only in hospitals","Never in animals"],"answerIndex":1,"explanation":"They can be natural, accidental or deliberate.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Biological hazards pose a risk to:","options":["Humans only","Animals and plants as well as humans","Machines only","Buildings only"],"answerIndex":1,"explanation":"They affect animals and plants too.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"A medical lab scientist must be informed about:","options":["Only the lab's price list","The possible biological agents in clinical samples","The weather","Only their colleagues' names"],"answerIndex":1,"explanation":"Knowing possible agents is essential.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Agent diversity means:","options":["Only one type of organism","Hazards range from microbes to toxins and insect infestations","All hazards are viruses","Hazards are always chemical"],"answerIndex":1,"explanation":"Agents are very varied.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which is NOT a route of transmission listed?","options":["Airborne","Ingestion","Absorption through skin","Gravitational pull"],"answerIndex":3,"explanation":"Gravity is not a transmission route.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Absorption through the eyes, skin, mucous membranes or wounds is:","options":["Ingestion","Airborne transmission","Absorption","Animal vector"],"answerIndex":2,"explanation":"Absorption covers skin, eyes, membranes and wounds.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Mosquitoes and ticks are examples of:","options":["Animal vectors","Airborne agents","Toxins","Reservoirs only"],"answerIndex":0,"explanation":"They are animal vectors of disease.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Mother-to-child transmission belongs to which route?","options":["Airborne","Ingestion","Bodily fluids","Animal vector"],"answerIndex":2,"explanation":"It is a bodily fluid route in the lecture.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Sexual transmission belongs to which route?","options":["Bodily fluids","Ingestion","Airborne","Vector"],"answerIndex":0,"explanation":"It is listed under bodily fluids.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Some biological hazards cause severe disease at:","options":["Only very high concentrations","Very low concentrations","No concentration","Only in animals"],"answerIndex":1,"explanation":"Low concentrations can be enough.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"How many aerosolised Lassa or Ebola organisms can be enough to cause severe disease?","options":["1 to 10","1000 to 10000","1 million","Only 500"],"answerIndex":0,"explanation":"The lecture gives 1 to 10.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Why are microbes hard to identify from clinical signs alone?","options":["They are invisible to the naked eye","They are too large","They have no symptoms","They change colour"],"answerIndex":0,"explanation":"Invisible microbes need specific diagnosis.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"What does 'endemic' mean for a biological hazard?","options":["It is present in the community","It only exists in space","It is always an epidemic","It is found in water only"],"answerIndex":0,"explanation":"Endemic means it is present in the community.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"A biological hazard that is endemic usually poses:","options":["High risk always","Low risk when the population is largely immune","No risk ever","Risk only to animals"],"answerIndex":1,"explanation":"Immunity keeps the risk low.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Risk from endemic hazards may rise during:","options":["Calm periods","Crises or emergencies","Holidays only","Every morning"],"answerIndex":1,"explanation":"Crises worsen transmission conditions.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"A non-endemic hazard poses risk when it is:","options":["Kept in a freezer","Introduced to a new host community with no immunity","Stored in a closed box","Labelled clearly"],"answerIndex":1,"explanation":"No immunity means high susceptibility.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Migration from disease-free areas into endemic regions raises risk because:","options":["People gain immunity","People typically lack immunity","Cases decrease","Hospitals close"],"answerIndex":1,"explanation":"Lack of immunity is the key factor.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which hazards are sensitive to climate change?","options":["Zoonoses and vector-borne diseases","Glassware breakage","Ergonomic strain only","Radioactive decay only"],"answerIndex":0,"explanation":"Vector and zoonotic diseases respond to climate.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which disease is given as an example of vector-borne disease?","options":["Malaria","Fracture","Burn","Asthma"],"answerIndex":0,"explanation":"Malaria is vector-borne.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Changes in climate or land use can:","options":["Reduce all disease","Change incidence, lethality, geography or seasonal patterns","Stop all vectors","Remove microbes"],"answerIndex":1,"explanation":"These are the effects listed.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"About what share of emerging human infectious diseases evolved from zoonotic pathogens?","options":["About 25%","About 50%","About 75%","About 100%"],"answerIndex":2,"explanation":"The lecture gives about 75%.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"What does 'zoonotic' mean?","options":["Caused by plants","Transmitted between animals and humans","Caused by chemicals","Found only in water"],"answerIndex":1,"explanation":"Zoonoses pass between animals and humans.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"The chain of infection has how many links?","options":["4","5","6","8"],"answerIndex":2,"explanation":"Six links.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which is the first link of the chain of infection?","options":["Susceptible host","Infectious agent (pathogen)","Portal of entry","Mode of transmission"],"answerIndex":1,"explanation":"The pathogen starts the chain.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"The place where the agent lives and multiplies is the:","options":["Portal of exit","Reservoir","Susceptible host","Mode of transmission"],"answerIndex":1,"explanation":"Reservoir is where the agent lives.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"The route by which an agent leaves its reservoir is the:","options":["Portal of entry","Portal of exit","Reservoir","Host"],"answerIndex":1,"explanation":"Portal of exit.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"The route by which an agent enters a new host is the:","options":["Portal of exit","Mode of transmission","Portal of entry","Reservoir"],"answerIndex":2,"explanation":"Portal of entry.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which link describes the person who can be infected?","options":["Reservoir","Susceptible host","Portal of exit","Pathogen"],"answerIndex":1,"explanation":"The susceptible host.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Breaking one link of the chain of infection:","options":["Makes no difference","Stops transmission","Doubles the risk","Only affects animals"],"answerIndex":1,"explanation":"One broken link stops the chain.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"In the lab, a clinical sample can be seen as:","options":["A safe object","A possible reservoir carrying the agent","A chemical reagent","A piece of equipment"],"answerIndex":1,"explanation":"Samples may carry agents.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which lab action helps break the chain at the portal of entry?","options":["Wearing PPE and safe technique","Leaving samples open","Eating at the bench","Ignoring spills"],"answerIndex":0,"explanation":"PPE blocks entry.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which lab action helps break the chain at the exit from a reservoir?","options":["Containment and decontamination","Mouth pipetting","Sharing needles","Leaving waste out"],"answerIndex":0,"explanation":"Containment limits exit and spread.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which is a 'biological hazard' in the lab?","options":["Ergonomic posture","Pathogen in a clinical sample","Poor lighting","Chemical stains"],"answerIndex":1,"explanation":"A pathogen is biological.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which statement is correct?","options":["Biological hazards cannot cause death","Biological hazards can lead to death and economic loss","Biological hazards are always visible","Biological hazards only affect cattle"],"answerIndex":1,"explanation":"They can cause death and loss.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Why must hazards be recognised before handling samples?","options":["To choose the right colour of gloves","To pick the correct precautions","To pass the exam","To avoid paperwork"],"answerIndex":1,"explanation":"Precautions depend on the hazard.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"What makes assessing biological risks challenging?","options":["Their simplicity","Their diverse and invisible nature and many routes","Their colour","Their size only"],"answerIndex":1,"explanation":"Several characteristics make it hard.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which best describes a 'hazard' in the lecture's context?","options":["A safe agent","Anything able to cause harm","A waste bin","A sample label"],"answerIndex":1,"explanation":"A hazard can cause harm.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which hazard can be deliberately released?","options":["Biological agents","Dust","Water","Light"],"answerIndex":0,"explanation":"Biological agents can be deliberately released.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Ebola and Lassa are described in this lecture as:","options":["Safe viruses","Viruses causing severe disease at very low doses","Chemicals","Physical hazards"],"answerIndex":1,"explanation":"They are highly infectious at low doses.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which factor makes a biological hazard more dangerous in a new area?","options":["Presence of immunity","Absence of immunity in the population","High temperature only","Clean water"],"answerIndex":1,"explanation":"No immunity raises risk.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Zika and dengue are examples of:","options":["Vector-borne diseases","Chemical hazards","Physical hazards","Radiological hazards"],"answerIndex":0,"explanation":"They are vector-borne.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which of these best shows that hazards change over time?","options":["Stable disease patterns","Shifting geographic distribution of vector diseases","Fixed rainfall","Unchanging hospital rules"],"answerIndex":1,"explanation":"Distribution changes with climate and land use.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Land-use changes can affect disease by:","options":["Changing ecosystems and human exposure","Removing all insects","Stopping transmission","Making samples sterile"],"answerIndex":0,"explanation":"Ecosystem change alters exposure.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"The best description of endemic and epidemic hazard risk is:","options":["Endemic risk is always high","Endemic hazards can become epidemic when conditions change","Epidemic hazards cannot occur","Endemic hazards only affect plants"],"answerIndex":1,"explanation":"Conditions can turn endemic into epidemic.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which of these is a biological agent?","options":["Mercury","Bacteria","Sodium chloride","Glass"],"answerIndex":1,"explanation":"Bacteria are biological.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"A 'susceptible host' is best described as:","options":["A person protected by immunity","A person who can be infected","A type of reagent","A waste container"],"answerIndex":1,"explanation":"Susceptible means can be infected.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which link is about the way the agent moves from one place to another?","options":["Reservoir","Mode of transmission","Pathogen","Host"],"answerIndex":1,"explanation":"Mode of transmission is the movement.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which of these shows the value of the chain of infection model?","options":["It identifies where to intervene","It replaces diagnosis","It removes the need for PPE","It is only a theory of art"],"answerIndex":0,"explanation":"It guides intervention points.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"In the lecture, the pathogen is the:","options":["Infectious agent","Portal of entry","Reservoir","Host"],"answerIndex":0,"explanation":"The pathogen is the infectious agent.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which is a good reason to treat every clinical sample carefully?","options":["Samples are always clean","You cannot always know which agents a sample carries","Samples have no risk","Samples are always labelled"],"answerIndex":1,"explanation":"Unknown content is a risk.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which best describes 'pathogenicity'?","options":["How easily an agent is seen","The ability of an agent to cause disease","The cost of an agent","The shape of a microbe"],"answerIndex":1,"explanation":"Pathogenicity is disease-causing ability.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which best describes 'virulence'?","options":["The colour of an agent","The degree of harm an agent can cause","The size of a vector","The price of a test"],"answerIndex":1,"explanation":"Virulence is severity of disease.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which factor increases the risk from biological hazards in the environment?","options":["Land-use change","Good ventilation only","Clean hands only","Labelled samples"],"answerIndex":0,"explanation":"Land-use change can increase exposure.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"The lecture says biological hazards can be present in:","options":["Only hospitals","The community as well","Only laboratories","Only outer space"],"answerIndex":1,"explanation":"They can be present in communities.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which is an example of a pathogen in the list of biological hazards?","options":["Venomous snake","Poisonous plant","Bacterium","Mosquito"],"answerIndex":2,"explanation":"Bacteria are pathogenic microorganisms.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which of these is a vector rather than a pathogen?","options":["Mosquito","Bacterium","Virus","Toxin"],"answerIndex":0,"explanation":"Mosquitoes carry disease agents.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"A toxin is best described as:","options":["A living bacterium","A poisonous substance from living sources","A reagent for staining","A piece of equipment"],"answerIndex":1,"explanation":"Toxins are poisonous substances.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which is the correct link order in the chain of infection?","options":["Host, agent, reservoir, exit, transmission, entry","Agent, reservoir, exit, transmission, entry, host","Exit, agent, host, transmission, reservoir, entry","Entry, host, agent, reservoir, exit, transmission"],"answerIndex":1,"explanation":"This is the correct order.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which lecture statement describes an emerging risk?","options":["Diseases are always stable","Biological hazards may change in incidence and distribution","No change is expected","Only chemicals change"],"answerIndex":1,"explanation":"The lecture discusses changing patterns.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which is true about the risk of biological hazards in immune populations?","options":["Risk is high","Risk is usually low","Risk is always zero","Risk is unrelated to immunity"],"answerIndex":1,"explanation":"Immunity lowers the risk.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which best describes the role of diagnosis for biological hazards?","options":["Not needed","Needed because the agents are not visible","Only needed for chemicals","Replaces risk assessment"],"answerIndex":1,"explanation":"Specific diagnosis identifies the agent.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which phrase best matches 'portal of exit'?","options":["Where the agent leaves","Where the agent enters","Where the agent lives","Where the agent is tested"],"answerIndex":0,"explanation":"The exit is where the agent leaves.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which is an example of biological hazards affecting livestock?","options":["Animal disease spread","Glass breakage","Electrical fire","Heat stress"],"answerIndex":0,"explanation":"Animal disease is a biological hazard.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"Which practice helps protect a lab worker from biological hazards?","options":["Eating at the bench","Wearing gloves and washing hands","Pipetting by mouth","Sharing needles"],"answerIndex":1,"explanation":"Gloves and handwashing protect.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"},{"question":"What is the main point of Lecture 7?","options":["Chemicals are the only danger","Biological hazards are diverse and hard to assess, and every clinical sample must be treated with care","Samples are harmless","Hazards cannot be controlled"],"answerIndex":1,"explanation":"This is the core message.","topic":"Lecture 7: Biorisks from Handling Clinical Samples"}]},{"id":"mls101-lecture-08","order":8,"title":"Lecture 8: Laboratory Safety and Precaution","notesHtml":"<div class=\"card\">\n    <h2>1. The laboratory and why safety matters</h2>\n    <ul>\n      <li>A <b>laboratory</b> is equipped with instruments, equipment and chemicals (reagents) for experiments, research and investigations.</li>\n      <li>A <b>medical laboratory</b> is equipped with biomedical instruments, equipment, materials and reagents for laboratory investigations.</li>\n      <li>Medical laboratories are on the frontline of protecting everyone's health.</li>\n      <li>Safe labs let trained staff test accurately and on time, without endangering workers, the environment or the public.</li>\n      <li>Labs protect staff and the public from biological, chemical, environmental and physical hazards. They usually have strictly controlled access.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>2. Pathogens and Pathogen Risk Groups</h2>\n    <p>A <b>pathogen</b> is an infectious agent that can cause disease in humans, animals or plants. Pathogens can be bacteria, viruses, parasites or fungi. They are grouped into four <b>Pathogen Risk Groups</b>:</p>\n    <table>\n      <tr><th>Risk group</th><th>Risk level</th><th>Examples</th></tr>\n      <tr><td><b>1</b></td><td>No or low individual and community risk; unlikely to cause disease</td><td>E. coli, Lactobacillus</td></tr>\n      <tr><td><b>2</b></td><td>Moderate individual risk, low community risk; serious infection possible, but effective treatment and prevention exist</td><td>Campylobacter, Salmonella, Shigella, HIV, Rotavirus, Influenza</td></tr>\n      <tr><td><b>3</b></td><td>High individual risk, low community risk; serious disease, but does not usually spread person to person</td><td>SARS-CoV-2, Tuberculosis, Chikungunya</td></tr>\n      <tr><td><b>4</b></td><td>High individual and community risk; readily spreads, and effective treatment and prevention are usually not available</td><td>Ebola, Marburg, Lassa virus</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>3. Biosafety levels (BSL)</h2>\n    <p>Biosafety levels are a series of protections linked to the activities carried out in biological labs. They are individual safeguards to protect laboratory personnel, the environment and the community. They are ranked <b>1 to 4</b> and assigned based on the agent being worked with.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>4. Universal precautions: personal protection</h2>\n    <ol>\n      <li>Laboratory coats must be worn at all times for work in the lab.</li>\n      <li>Appropriate gloves must be worn for any procedure with possible contact with blood, body fluids or other potentially infectious materials. Remove gloves aseptically, then wash hands.</li>\n      <li>Wash hands after handling infectious materials or animals, and before leaving the working area.</li>\n      <li>Wear safety glasses, face shields or other protection against splashes, impacts and artificial UV radiation.</li>\n      <li>Do not wear lab clothing outside the lab (canteens, coffee rooms, offices, libraries, staff rooms, toilets).</li>\n      <li>Open-toed footwear is not allowed.</li>\n      <li>No eating, drinking, smoking, applying cosmetics or handling contact lenses in working areas.</li>\n      <li>No storing human food or drink anywhere in the working areas.</li>\n      <li>Female staff should keep their hair well packed.</li>\n      <li>Used lab clothing must not be stored with street clothing.</li>\n    </ol>\n  </div>\n\n  <div class=\"card\">\n    <h2>5. Laboratory procedures</h2>\n    <ul>\n      <li><b>Pipetting by mouth is strictly forbidden.</b></li>\n      <li>Perform procedures in a way that minimises aerosols and droplets.</li>\n      <li>Limit the use of hypodermic needles and syringes. They must not replace pipetting devices, and are only for parenteral injection or drawing fluid from lab animals.</li>\n      <li>Decontaminate contaminated liquids (chemically or physically) before discharge to the sanitary sewer.</li>\n      <li>Protect written documents leaving the lab from contamination while inside.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>6. Laboratory working areas</h2>\n    <ul>\n      <li>Keep the lab neat, clean and free of harmful materials.</li>\n      <li>Decontaminate work surfaces after any spill of dangerous material, and at the end of each working day.</li>\n      <li>Decontaminate all contaminated materials, specimens and cultures before disposal or reuse.</li>\n      <li>Packing and transport must follow national and international regulations.</li>\n      <li><b>Controlled ventilation</b> must keep airflow directional into the lab room. Avoid electric fans. Keep windows closed; if opened, fit arthropod-proof screens.</li>\n    </ul>\n    <p class=\"key\">Airflow direction matters: air should move into the room, so contaminated air does not spread out into corridors.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>Summary: key takeaways</h2>\n    <ul>\n      <li>Four pathogen risk groups: 1 (low) to 4 (high individual and community risk).</li>\n      <li>Biosafety levels (1 to 4) are set by the agent being handled.</li>\n      <li>PPE: lab coat, gloves, eye protection, handwashing, no street clothing in the lab.</li>\n      <li>Prohibited: mouth pipetting, eating, drinking, smoking, cosmetics, contact lenses, food storage in work areas.</li>\n      <li>Decontaminate spills, surfaces at day's end, and all waste before disposal.</li>\n      <li>Ventilation must keep airflow directional into the room.</li>\n    </ul>\n  </div>","flashcards":[{"front":"What is a laboratory?","back":"A place equipped with instruments, equipment and chemicals (reagents) for experiments, research and investigative procedures.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"What is a medical laboratory?","back":"A lab equipped with biomedical instruments, equipment, materials and reagents for laboratory investigations.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"What does laboratory safety protect?","back":"The health of workers, the environment and the public, from biological, chemical, environmental and physical hazards.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"What is a pathogen?","back":"An infectious agent capable of causing disease in humans, animals or plants.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Name four types of pathogen.","back":"Bacteria, viruses, parasites and fungi.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"What are pathogen risk groups?","back":"A classification of pathogens into four groups based on the risk they pose.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Describe Risk Group 1.","back":"No or low individual and community risk; unlikely to cause disease. E.g. E. coli, Lactobacillus.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Describe Risk Group 2.","back":"Moderate individual risk, low community risk; effective treatment and prevention are available. E.g. Salmonella, HIV, Influenza.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Describe Risk Group 3.","back":"High individual risk, low community risk; serious disease, but usually not spread person to person. E.g. Tuberculosis, SARS-CoV-2.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Describe Risk Group 4.","back":"High individual and community risk; readily transmitted, with treatment and prevention usually unavailable. E.g. Ebola, Marburg, Lassa.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Which risk group includes Tuberculosis?","back":"Risk Group 3.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Which risk group includes HIV?","back":"Risk Group 2.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Which risk group includes Ebola?","back":"Risk Group 4.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"What are biosafety levels (BSL)?","back":"A series of protections linked to the activities in biological labs, designed to protect staff, the environment and the community.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"How many biosafety levels are there?","back":"Four, ranked 1 to 4.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"What determines the biosafety level?","back":"The agent or organism the lab personnel are working on.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Why must lab coats be worn?","back":"They must be worn at all times for work in the laboratory.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"When must gloves be worn?","back":"For any procedure that may involve direct or accidental contact with blood, body fluids or potentially infectious materials.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"When should hands be washed?","back":"After handling infectious materials or animals, and before leaving the working area.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"What eye and face protection is required?","back":"Safety glasses, face shields or other devices to protect against splashes, impacting objects and artificial UV.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Can lab clothing be worn to the canteen?","back":"No. Protective lab clothing must not be worn outside the lab, including canteens.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Is open-toed footwear allowed in the lab?","back":"No.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Name four things banned in lab working areas.","back":"Eating, drinking, smoking, applying cosmetics, handling contact lenses, storing food or drink.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Is pipetting by mouth allowed?","back":"No. It is strictly forbidden.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"What should procedures minimise?","back":"The formation of aerosols and droplets.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"What are hypodermic needles and syringes for in the lab?","back":"Parenteral injection or drawing fluid from laboratory animals only; not as pipetting substitutes.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"How must contaminated liquids be treated before sewer discharge?","back":"Decontaminated, chemically or physically.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"When must work surfaces be decontaminated?","back":"After any spill of potentially dangerous material, and at the end of the working day.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"What must happen to contaminated specimens and cultures before disposal?","back":"They must be decontaminated.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"What ventilation airflow is required?","back":"A controlled system that keeps airflow directional into the lab room.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"Why avoid electric fans in the lab?","back":"Fans disturb controlled directional airflow and can spread contamination.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"If windows are opened, what must they have?","back":"Arthropod-proof screens.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"front":"What rules apply to packing and transport?","back":"Follow applicable national and/or international regulations.","topic":"Lecture 8: Laboratory Safety and Precaution"}],"questions":[{"question":"A pathogen is best defined as:","options":["A harmless bacterium","An infectious agent capable of causing disease in humans, animals or plants","A lab chemical","A type of glove"],"answerIndex":1,"explanation":"A pathogen is an infectious disease-causing agent.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which is NOT a type of pathogen listed?","options":["Bacteria","Viruses","Parasites","Minerals"],"answerIndex":3,"explanation":"Minerals are not pathogens; bacteria, viruses, parasites and fungi are.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Pathogens are classified into how many risk groups?","options":["2","3","4","5"],"answerIndex":2,"explanation":"There are four Pathogen Risk Groups.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"E. coli and Lactobacillus belong to which risk group?","options":["Risk Group 1","Risk Group 2","Risk Group 3","Risk Group 4"],"answerIndex":0,"explanation":"They are Risk Group 1 examples.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Salmonella and HIV belong to which risk group?","options":["Risk Group 1","Risk Group 2","Risk Group 3","Risk Group 4"],"answerIndex":1,"explanation":"They are Risk Group 2 examples.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Tuberculosis belongs to which risk group?","options":["Risk Group 1","Risk Group 2","Risk Group 3","Risk Group 4"],"answerIndex":2,"explanation":"TB is Risk Group 3.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Ebola virus belongs to which risk group?","options":["Risk Group 1","Risk Group 2","Risk Group 3","Risk Group 4"],"answerIndex":3,"explanation":"Ebola is Risk Group 4.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which group poses high individual risk but low community risk?","options":["Risk Group 1","Risk Group 2","Risk Group 3","Risk Group 4"],"answerIndex":2,"explanation":"Risk Group 3.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which group is readily transmitted with treatment usually unavailable?","options":["Risk Group 2","Risk Group 3","Risk Group 4","Risk Group 1"],"answerIndex":2,"explanation":"Risk Group 4.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which group has effective treatment and prevention available and limited spread?","options":["Risk Group 2","Risk Group 4","Risk Group 1 only","None"],"answerIndex":0,"explanation":"Risk Group 2 has effective measures.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"SARS-CoV-2 belongs to which risk group?","options":["Risk Group 1","Risk Group 2","Risk Group 3","Risk Group 4"],"answerIndex":2,"explanation":"It is listed in Risk Group 3.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Lassa virus belongs to which risk group?","options":["Risk Group 1","Risk Group 2","Risk Group 3","Risk Group 4"],"answerIndex":3,"explanation":"Lassa is Risk Group 4.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Influenza belongs to which risk group?","options":["Risk Group 1","Risk Group 2","Risk Group 3","Risk Group 4"],"answerIndex":1,"explanation":"Influenza is Risk Group 2.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Biosafety levels are ranked:","options":["1 to 3","1 to 4","A to D","1 to 10"],"answerIndex":1,"explanation":"Levels are ranked 1 to 4.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"What determines the biosafety level?","options":["The colour of the bench","The agent or organism being worked on","The lab's floor plan","The cost of equipment"],"answerIndex":1,"explanation":"The agent determines the level.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Biosafety levels protect:","options":["Only equipment","Personnel, the environment and the community","Only patients","Only buildings"],"answerIndex":1,"explanation":"Protection covers people and environment.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"When must a lab coat be worn?","options":["Only for visitors","At all times for work in the lab","Only in the canteen","Never"],"answerIndex":1,"explanation":"Coats are worn at all times.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Gloves must be worn for procedures involving:","options":["Only chemicals","Blood, body fluids or potentially infectious materials","Only paper","Nothing"],"answerIndex":1,"explanation":"Gloves protect against infectious contact.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"After glove use, the gloves should be removed:","options":["Carelessly","Aseptically, followed by handwashing","Only after lunch","Outside the lab"],"answerIndex":1,"explanation":"Aseptic removal and handwashing.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Hands must be washed:","options":["Only at the start of the day","After handling infectious materials and before leaving the working area","Never","Only after breaks"],"answerIndex":1,"explanation":"Handwashing is a key step.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which protection is needed against splashes and artificial UV?","options":["Safety glasses or face shields","Open-toed shoes","Lab coat outside the lab","Ponytails"],"answerIndex":0,"explanation":"Eye and face protection.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Lab clothing must NOT be worn in:","options":["The laboratory","The canteen","The working area","The procedure room"],"answerIndex":1,"explanation":"It must stay in the lab.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Open-toed footwear in the lab is:","options":["Recommended","Not allowed","Required","Free to choose"],"answerIndex":1,"explanation":"Open-toed footwear is prohibited.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which is prohibited in working areas?","options":["Handwashing","Eating and drinking","Wearing gloves","Labelling samples"],"answerIndex":1,"explanation":"Eating and drinking are banned.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Contact lenses should be handled:","options":["In working areas","Not in working areas","Only with gloves on","During procedures"],"answerIndex":1,"explanation":"Contact lenses must not be handled in working areas.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Human food or drink should be stored:","options":["In the working area","Nowhere in the working area","In the lab fridge","Beside the centrifuge"],"answerIndex":1,"explanation":"Never store food in working areas.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Hair for female staff should be:","options":["Loose","Well packed","Dyed","Cut short only"],"answerIndex":1,"explanation":"Hair should be well packed.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Used lab clothing must not be stored with:","options":["Lab gloves","Street clothing","Labels","Waste bags"],"answerIndex":1,"explanation":"Keep used lab clothes separate.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Pipetting by mouth is:","options":["Recommended for accuracy","Strictly forbidden","Allowed with gloves","Allowed for water only"],"answerIndex":1,"explanation":"It is strictly forbidden.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Procedures should be done to:","options":["Maximise aerosols","Minimise aerosols and droplets","Create splashes","Make noise"],"answerIndex":1,"explanation":"Minimise aerosols.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Hypodermic needles and syringes should be:","options":["Used as pipettes","Limited, and used only for injection or animal fluid aspiration","Used for all tasks","Stored in the open"],"answerIndex":1,"explanation":"Their use is limited.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Contaminated liquids must be decontaminated before:","options":["Storage","Discharge to the sanitary sewer","Labelling","Testing"],"answerIndex":1,"explanation":"They must be treated before sewer discharge.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Written documents leaving the lab must be:","options":["Ignored","Protected from contamination while in the lab","Folded only","Coloured"],"answerIndex":1,"explanation":"Protect documents from contamination.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Work surfaces must be decontaminated:","options":["Only once a year","After any spill of dangerous material and at the end of the day","Only at the start of term","Never"],"answerIndex":1,"explanation":"Spills and day's end.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Contaminated specimens and cultures must be:","options":["Thrown away untreated","Decontaminated before disposal or reuse","Kept for later","Stored in the staff room"],"answerIndex":1,"explanation":"Decontaminate before disposal.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Packing and transport must follow:","options":["Personal rules","National and international regulations","Random practice","Market prices"],"answerIndex":1,"explanation":"Regulations apply.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which ventilation is required?","options":["Random airflow","Controlled, directional airflow into the lab room","Airflow out of the room only","No ventilation"],"answerIndex":1,"explanation":"Airflow must be directional into the room.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Why avoid electric fans in the lab?","options":["They are noisy","They disturb controlled directional airflow","They are expensive","They use too much water"],"answerIndex":1,"explanation":"Fans disturb directional airflow.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"If windows are opened, they must have:","options":["Curtains","Arthropod-proof screens","Stickers","Bars only"],"answerIndex":1,"explanation":"Screens keep insects out.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which statement is correct about lab windows?","options":["They must always be open","They should be closed; if opened, screened","They can be left open at night","They should be painted"],"answerIndex":1,"explanation":"Closed or screened.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Why are medical labs described as frontline?","options":["They sell drugs","They protect everyone's health","They run hospitals","They make uniforms"],"answerIndex":1,"explanation":"They protect public health.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Safe labs enable staff to:","options":["Avoid all tests","Test accurately and on time without risk to health","Skip training","Work without gloves"],"answerIndex":1,"explanation":"Safety supports accurate testing.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Lab access is:","options":["Open to all","Strictly controlled","Free for visitors only","Unrestricted"],"answerIndex":1,"explanation":"Labs have controlled access.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which is a biological hazard that labs protect against?","options":["Pathogens","Heat from the sun","Music","Furniture"],"answerIndex":0,"explanation":"Pathogens are biological hazards.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which is a chemical hazard labs protect against?","options":["Reagents","Books","Chairs","Windows"],"answerIndex":0,"explanation":"Reagents are chemicals.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which is an environmental risk labs guard against?","options":["Contaminated waste","Lab decor","Ceiling height","Carpet colour"],"answerIndex":0,"explanation":"Contaminated waste harms the environment.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which is a physical hazard labs guard against?","options":["Sharps and broken glass","Water coolers","Posters","Art"],"answerIndex":0,"explanation":"Sharps and glass are physical.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which shows the correct handling of a spill?","options":["Leave it","Decontaminate the surface immediately","Cover it with paper","Blow it away"],"answerIndex":1,"explanation":"Decontaminate promptly.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"What is the purpose of decontaminating waste?","options":["To make it smell better","To prevent harm from contamination","To reduce its weight","To sell it"],"answerIndex":1,"explanation":"It prevents harm.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which is a correct summary of Risk Group 4?","options":["Low risk","High individual and community risk","Moderate risk","No risk"],"answerIndex":1,"explanation":"Risk Group 4 is the highest.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which risk group matches E. coli?","options":["Group 1","Group 2","Group 3","Group 4"],"answerIndex":0,"explanation":"E. coli is in Group 1.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which lab practice reduces aerosols during centrifugation?","options":["Leaving the lid open","Sealing centrifuge cups or using safer technique","Shaking hard","Speeding up"],"answerIndex":1,"explanation":"Sealing or safe technique reduces aerosols.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Why do labs restrict access?","options":["To make visitors wait","To protect people and materials","To save electricity","To reduce tests"],"answerIndex":1,"explanation":"Access control protects people and materials.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which is the best reason to follow universal precautions?","options":["It looks professional","Any sample may be infectious","Only for exams","It is optional"],"answerIndex":1,"explanation":"Treat every sample as potentially infectious.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which practice is correct at the end of the day?","options":["Leave surfaces dirty","Decontaminate work surfaces","Eat at the bench","Store food at the bench"],"answerIndex":1,"explanation":"Surfaces must be decontaminated.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which is the correct handwashing timing?","options":["Never","After handling infectious materials and before leaving the area","Only at home","Once a week"],"answerIndex":1,"explanation":"Right timing.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Who should follow these lab precautions?","options":["Only senior staff","Everyone working in the lab","Only visitors","No one"],"answerIndex":1,"explanation":"Everyone in the lab must follow them.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which is a correct use of a hypodermic syringe?","options":["Pipetting water","Parenteral injection or drawing animal fluid","Stirring reagents","Cleaning benches"],"answerIndex":1,"explanation":"Only for injection or animal fluid.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"The main message of Lecture 8 is:","options":["Labs do not need rules","Safety rules and precautions protect staff, the public and the environment","Only chemicals need care","Precautions are optional"],"answerIndex":1,"explanation":"That is the core message.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"A pathogen unlikely to cause disease in humans or animals belongs to which risk group?","options":["Risk Group 1","Risk Group 2","Risk Group 3","Risk Group 4"],"answerIndex":0,"explanation":"Risk Group 1 is unlikely to cause human or animal disease.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"A student is found eating a snack at a lab bench. Which rule is broken?","options":["Eating, drinking, smoking and cosmetics are prohibited in working areas","Gloves must be worn","Lab coats must be fastened","Hair must be packed"],"answerIndex":0,"explanation":"Eating in working areas is prohibited.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Contaminated liquids may be decontaminated by:","options":["Chemical or physical means","Only adding water","Pouring them into the sink untreated","Leaving them open"],"answerIndex":0,"explanation":"Liquids are decontaminated chemically or physically before discharge.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which best describes the correct removal of gloves?","options":["Remove them carelessly and touch door handles","Remove them aseptically, then wash hands","Keep them on until the end of the day","Turn them inside out and reuse"],"answerIndex":1,"explanation":"Remove aseptically, then wash hands.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Protective lab clothing should not be worn in which place?","options":["The laboratory","The canteen","The bench area","The procedure room"],"answerIndex":1,"explanation":"Lab clothing must not be worn in canteens, offices, libraries or toilets.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Why must written documents leaving the lab be protected?","options":["To keep them dry","To prevent contamination while in the lab","To make them look neat","To hide results"],"answerIndex":1,"explanation":"Documents must be protected from contamination while in the lab.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which statement about biosafety levels is correct?","options":["They are assigned by lab colour","They are ranked 1 to 4 based on the agent being worked with","They are the same for all labs","They apply only to chemicals"],"answerIndex":1,"explanation":"Biosafety levels are ranked 1 to 4 and set by the agent.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Which practice is strictly forbidden?","options":["Pipetting by mouth","Using a pipette bulb","Labelling tubes","Using a centrifuge lid"],"answerIndex":0,"explanation":"Pipetting by mouth is strictly forbidden.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Procedures should be carried out in a way that:","options":["Maximises aerosols","Minimises aerosols and droplets","Creates splashes for mixing","Avoids the use of gloves"],"answerIndex":1,"explanation":"Technical procedures should minimise aerosols and droplets.","topic":"Lecture 8: Laboratory Safety and Precaution"},{"question":"Ventilation in the lab should maintain:","options":["Random airflow","Directional airflow into the room","Airflow out of the room into corridors","No airflow"],"answerIndex":1,"explanation":"The controlled ventilation system maintains directional airflow into the room.","topic":"Lecture 8: Laboratory Safety and Precaution"}]},{"id":"mls101-lecture-09","order":9,"title":"Lecture 9: Biorisk Performance, AMP Model and Evaluation","notesHtml":"<div class=\"card\">\n    <h2>Introduction: two key definitions</h2>\n    <ul>\n      <li><b>Laboratory biosafety:</b> containment principles, technologies and practices to prevent unintentional exposure to pathogens and toxins, or their unintentional release.</li>\n      <li><b>Laboratory biosecurity:</b> protection, control and accountability for valuable biological materials, to prevent unauthorised access, loss, theft, misuse, diversion or intentional release.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>1. The AMP model</h2>\n    <p><b>Biorisk management = Assessment + Mitigation + Performance</b></p>\n    <table>\n      <tr><th>Component</th><th>What it involves</th></tr>\n      <tr><td><b>Assessment</b></td><td>Hazard identification</td></tr>\n      <tr><td><b>Mitigation</b></td><td>Biorisk measures and risk management</td></tr>\n      <tr><td><b>Performance</b></td><td>Measurement, assurance, defining and reviewing objectives</td></tr>\n    </table>\n    <p class=\"key\">Laboratory biorisk management is a system or process that improves biorisk management by recording, measuring and evaluating organisational actions and outcomes to reduce biorisk. It controls safety and security risks linked to handling, storing and disposing of biological agents and toxins.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>2. Biorisk management system performance</h2>\n    <p>Performance is the way a biorisk management system actually functions to manage or minimise biorisk. It compares <b>intended outcomes (IO)</b> with <b>observed outcomes (OO)</b>.</p>\n    <table>\n      <tr><th>Intended outcome (IO)</th><th>Observed outcome (OO)</th><th>Corrective action</th></tr>\n      <tr><td>Number of incidents less than 5</td><td>6</td><td>Revise SOP and provide training</td></tr>\n      <tr><td>Number of accidents less than 3</td><td>0</td><td>Not required</td></tr>\n      <tr><td>Spills in the laboratory: 0</td><td>1</td><td>Revise SOP and provide training</td></tr>\n    </table>\n    <p class=\"key\">A gap between IO and OO triggers action. If OO meets or beats IO, no corrective action is needed.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>3. Assessing a basic process</h2>\n    <p>Every process has three parts: <b>Input → Steps → Output</b>.</p>\n    <ul>\n      <li><b>Steps:</b> are they physically possible? Are they the right steps?</li>\n      <li><b>Output:</b> is the actual output equal to the desired output? Is it the right measurement for the process?</li>\n    </ul>\n    <h3>Worked example: Mycobacterium tuberculosis</h3>\n    <ul>\n      <li><b>Input:</b> reduce exposure of lab workers to <i>M. tuberculosis</i> using administrative controls and PPE.</li>\n      <li><b>Steps:</b> preliminary health screening of lab workers; an SOP for correct PPE use; post-project screening of workers.</li>\n      <li><b>Output:</b> one of five workers tested positive, so the output does not match the intended result.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>4. Characteristics of BRM system performance</h2>\n    <ul>\n      <li>Performance is the result of the activities and efforts of <b>all</b> the people in a facility.</li>\n      <li>Actual performance may not match the planned level of risk management effectiveness.</li>\n      <li>Performance measurement assesses the differences between plan and reality.</li>\n      <li>Performance changes over time, so sustained performance needs continual effort.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>5. Why measure performance?</h2>\n    <p>Measurement is the first step that leads to control and, eventually, to improvement. It:</p>\n    <ul>\n      <li>Shows which parts of the system meet stated goals or benchmarks</li>\n      <li>Gives a demonstrable record of performance, which can support certification or accreditation</li>\n      <li>Identifies areas for improvement using a consistent framework</li>\n      <li>Provides assurance that the risk is acceptable</li>\n      <li>Supports maintenance and sustainability of the system</li>\n      <li>Saves time and money by helping prioritise resources</li>\n      <li>Helps prevent accidents and incidents, and reduces operating costs</li>\n    </ul>\n    <p class=\"key\">Quote to remember (H. James Harrington): \"If you can't measure something, you can't understand it. If you can't understand it, you can't control it. If you can't control it, you can't improve it.\"</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>6. Continuous improvement: PDCA</h2>\n    <table>\n      <tr><th>Step</th><th>Meaning</th></tr>\n      <tr><td><b>Plan</b></td><td>Identify hazards and risks; establish programme goals</td></tr>\n      <tr><td><b>Do</b></td><td>Implement, including training and operational issues</td></tr>\n      <tr><td><b>Check</b></td><td>Monitor and take corrective action</td></tr>\n      <tr><td><b>Act</b></td><td>Review, innovate and make the changes needed in the management system</td></tr>\n    </table>\n    <h3>Important points from the standard</h3>\n    <ul>\n      <li>Performance measurement is part of the biorisk management system, not a stand-alone function.</li>\n      <li>The organisation must determine, collect and analyse appropriate data to assess the suitability and effectiveness of the system and to find where it can improve.</li>\n      <li><b>Top management</b> must review the system at planned intervals. The review covers opportunities for improvement and the need for changes to the system, procedures, policies and objectives.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>7. Summary</h2>\n    <ul>\n      <li><b>AMP:</b> Assessment, Mitigation, Performance.</li>\n      <li><b>Performance</b> compares intended outcomes with observed outcomes.</li>\n      <li><b>Process check:</b> input, steps and output must each be right.</li>\n      <li><b>PDCA</b> is the engine of continuous improvement.</li>\n      <li><b>Top management</b> reviews the system at planned intervals.</li>\n    </ul>\n  </div>","flashcards":[{"front":"What is laboratory biosafety?","back":"Containment principles, technologies and practices to prevent unintentional exposure to pathogens and toxins, or their unintentional release.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What is laboratory biosecurity?","back":"Protection, control and accountability for valuable biological materials, to prevent unauthorised access, loss, theft, misuse, diversion or intentional release.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"Write the AMP model.","back":"Biorisk management = Assessment + Mitigation + Performance.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What does Assessment involve in the AMP model?","back":"Hazard identification.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What does Mitigation involve in the AMP model?","back":"Biorisk measures and risk management.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What does Performance involve in the AMP model?","back":"Measurement, assurance, and defining and reviewing objectives.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"Define laboratory biorisk management.","back":"A system or process that improves biorisk management by recording, measuring and evaluating organisational actions and outcomes to reduce biorisk.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"Define biorisk management system performance.","back":"The way a biorisk management system actually functions to manage or minimise biorisk.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What does performance compare?","back":"Intended outcomes (IO) with observed outcomes (OO).","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What happens when observed outcomes do not meet intended outcomes?","back":"Corrective action is triggered, e.g. revise the SOP and provide training.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What are the three parts of a basic process?","back":"Input, steps and output.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What two questions check the steps of a process?","back":"Are they physically possible? Are they the right steps?","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What two questions check the output of a process?","back":"Is the actual output equal to the desired output? Is it the right measurement for the process?","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"Who contributes to biorisk management performance?","back":"All the people in the facility, not only management.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"Why might actual performance differ from plan?","back":"Real performance may not match the planned level of risk management effectiveness, so measurement finds the gap.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"Why does performance need continual effort?","back":"Performance changes over time; a sustained level needs ongoing work.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"State the Harrington principle in one line.","back":"You cannot control or improve what you cannot measure.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"Give three benefits of performance measurement.","back":"Shows what meets goals, supports accreditation, helps prioritise resources, prevents incidents.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What does PDCA stand for?","back":"Plan, Do, Check, Act.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What happens in the Plan step?","back":"Identify hazards and risks and establish programme goals.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What happens in the Do step?","back":"Implement, including training and operational issues.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What happens in the Check step?","back":"Monitoring and corrective action.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What happens in the Act step?","back":"Review, process innovation and making needed changes to the management system.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"Is performance measurement a stand-alone function?","back":"No. It is an integral part of the overall biorisk management system.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"Who must review the biorisk management system?","back":"Top management, at planned intervals.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What should a management review assess?","back":"Opportunities for improvement and the need for changes to the system, procedures, policies and objectives.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"front":"What is the M. tuberculosis example's controls?","back":"Administrative controls and PPE, with health screening and an SOP for PPE use.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"}],"questions":[{"question":"The AMP model stands for:","options":["Assessment, Mitigation, Performance","Analysis, Monitoring, Prevention","Audit, Management, Planning","Assessment, Measurement, Protection"],"answerIndex":0,"explanation":"AMP = Assessment + Mitigation + Performance.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Hazard identification belongs to which AMP component?","options":["Assessment","Mitigation","Performance","Audit"],"answerIndex":0,"explanation":"Hazard identification is assessment.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Biorisk measures and risk management belong to:","options":["Assessment","Mitigation","Performance","Planning"],"answerIndex":1,"explanation":"Mitigation covers measures and risk management.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Measurement and assurance belong to:","options":["Assessment","Mitigation","Performance","Inspection"],"answerIndex":2,"explanation":"Performance covers measurement and assurance.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Biorisk management, per the lecture, is:","options":["A single laboratory test","A system that records, measures and evaluates actions and outcomes to reduce biorisk","A brand of PPE","A type of waste bin"],"answerIndex":1,"explanation":"It is a system of recording, measuring and evaluating.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Biorisk management performance compares:","options":["Staff with patients","Intended outcomes with observed outcomes","Cost with budget only","Equipment with suppliers"],"answerIndex":1,"explanation":"IO versus OO.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Intended outcome (IO) of 'number of incidents less than 5' and observed outcome (OO) of 6 means:","options":["Performance met the target","Performance did not meet the target","No action is needed","The IO is wrong"],"answerIndex":1,"explanation":"6 is more than 5, so the target is not met.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"In the IO/OO example with 6 incidents, the corrective action is:","options":["No action","Revise SOP and provide training","Close the lab","Buy a new centrifuge"],"answerIndex":1,"explanation":"The lecture recommends revising the SOP and training.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"If accidents are intended to be less than 3 and observed is 0, the corrective action is:","options":["Revise SOP","Not required","Close the lab","Retrain all staff"],"answerIndex":1,"explanation":"The target is met.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"A spill in the lab with an intended outcome of 0 requires:","options":["No action","Revision of SOP and training","Closing the lab","Ignoring it"],"answerIndex":1,"explanation":"The target was missed.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"The three parts of a basic process are:","options":["Plan, Do, Act","Input, steps, output","Assess, mitigate, perform","Start, middle, end"],"answerIndex":1,"explanation":"Input-steps-output is the basic process model.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which question checks whether the steps are right?","options":["Is the output measured in mg?","Are they physically possible and the right steps?","Who signed the form?","Is the room big enough?"],"answerIndex":1,"explanation":"Steps should be possible and correct.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which question checks the output?","options":["Are they physically possible?","Is the actual output equal to the desired output?","Who is the lab head?","Is the cabinet new?"],"answerIndex":1,"explanation":"Output must match desired output.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"In the M. tuberculosis example, what was the input?","options":["One worker tested positive","Reduce worker exposure using administrative controls and PPE","A health screening after the project","An SOP on cleaning"],"answerIndex":1,"explanation":"The input is the intended mitigation.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"In the M. tuberculosis example, the output was:","options":["Zero infections","One of five workers tested positive","All workers vaccinated","The SOP was revised"],"answerIndex":1,"explanation":"One positive result is the observed output.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which step in the TB example is a PPE-related step?","options":["Post-project screening","An SOP for correct PPE use","Preliminary health screening","Output measurement"],"answerIndex":1,"explanation":"The SOP covers PPE use.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Who contributes to biorisk performance?","options":["Only the lab head","Only the quality officer","All the people in the facility","Only the cleaners"],"answerIndex":2,"explanation":"Performance is everyone's effort.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Actual biorisk performance may:","options":["Always match the plan","Not match the planned level of effectiveness","Be unmeasurable","Never change"],"answerIndex":1,"explanation":"That is why measurement is needed.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Why is sustained performance difficult?","options":["Because it never changes","Because performance changes over time and needs continual effort","Because staff refuse","Because equipment is always new"],"answerIndex":1,"explanation":"Continual effort is needed.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Harrington's quote says that you cannot improve what you cannot:","options":["Afford","Control","Name","Hire"],"answerIndex":1,"explanation":"You cannot control what you cannot understand, and you cannot improve what you cannot control.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Performance measurement helps to:","options":["Create more paperwork only","Show which parts meet goals","Replace management","Stop all training"],"answerIndex":1,"explanation":"It shows which parts meet goals.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"A demonstrable record of performance can support:","options":["Certification or accreditation","Advertising","Staff hiring only","Drug sales"],"answerIndex":0,"explanation":"Records support accreditation.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Performance measurement helps prioritise:","options":["Staff hobbies","Resources","Lab colours","Visitors"],"answerIndex":1,"explanation":"Resources are focused on priority risks.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"PDCA stands for:","options":["Plan, Do, Check, Act","Prepare, Deliver, Clean, Analyse","Protect, Direct, Control, Assess","Plan, Document, Confirm, Audit"],"answerIndex":0,"explanation":"PDCA is the improvement cycle.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Identifying hazards and establishing goals is part of:","options":["Plan","Do","Check","Act"],"answerIndex":0,"explanation":"Plan sets goals and identifies hazards.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Training and operational issues belong to:","options":["Plan","Do","Check","Act"],"answerIndex":1,"explanation":"Do is implementation.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Monitoring and corrective action belong to:","options":["Plan","Do","Check","Act"],"answerIndex":2,"explanation":"Check monitors and corrects.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Process innovation and changes to the management system belong to:","options":["Plan","Do","Check","Act"],"answerIndex":3,"explanation":"Act reviews and changes the system.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Is performance measurement a stand-alone function?","options":["Yes, always","No; it is part of the overall biorisk management system","Only in hospitals","Only for chemicals"],"answerIndex":1,"explanation":"It is integrated, not separate.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which data should the organisation determine, collect and analyse?","options":["Only financial data","Appropriate data to assess suitability and effectiveness of the system","Only patient names","Only staff salaries"],"answerIndex":1,"explanation":"Data must assess effectiveness.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Who must review the biorisk system at planned intervals?","options":["Cleaners","Top management","Visitors","Students only"],"answerIndex":1,"explanation":"Top management reviews the system.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"A management review should assess:","options":["Only the budget","Opportunities for improvement and needed changes","Only staff birthdays","Only parking"],"answerIndex":1,"explanation":"Review looks for improvement and change.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which is a change a management review might lead to?","options":["Changes to procedures, policies and objectives","Changes to the weather","Changes to the building name","Changes to the uniform"],"answerIndex":0,"explanation":"Reviews can change procedures, policies and objectives.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"The main purpose of performance measurement is to:","options":["Blame staff","Control and improve the system","Reduce the number of labs","Increase costs"],"answerIndex":1,"explanation":"Measurement leads to control and improvement.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which best describes 'performance'?","options":["How well the lab looks","How the system actually functions to manage or minimise biorisk","How many years the lab has existed","How many tests are sold"],"answerIndex":1,"explanation":"It is actual functioning.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Laboratory biosafety focuses on:","options":["Theft","Unintentional exposure or release of pathogens and toxins","Unauthorised access","Diversion of materials"],"answerIndex":1,"explanation":"Biosafety is about accidents.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Laboratory biosecurity focuses on:","options":["Accidental spills","Protection and accountability for valuable biological materials","Ergonomic posture","Fire drills"],"answerIndex":1,"explanation":"Biosecurity protects valuable materials.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which pair is correctly matched?","options":["Biosafety: theft; Biosecurity: spills","Biosafety: accidental exposure; Biosecurity: unauthorised access","Biosafety: ergonomics; Biosecurity: radiation","Biosafety: budget; Biosecurity: audit"],"answerIndex":1,"explanation":"Matches the definitions.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which is an example of a 'corrective action' in the lecture?","options":["Revision of SOP and training","Buying flowers","Renaming the lab","Closing the library"],"answerIndex":0,"explanation":"Revising SOPs and training is the example.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"If a spill occurs and the IO is 0, the performance is:","options":["Met","Not met","Not measured","Irrelevant"],"answerIndex":1,"explanation":"Any spill fails the target of 0.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"A process that produces an output different from the desired output indicates:","options":["Perfect performance","A gap that needs investigation","No measurement needed","A correct process"],"answerIndex":1,"explanation":"A gap triggers investigation.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Why check the 'right measurement' for a process?","options":["To use more paper","To ensure the output measures what matters for the process","To impress visitors","To avoid audits"],"answerIndex":1,"explanation":"The measure must fit the process.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which is NOT a benefit of performance measurement listed?","options":["Helps prevent incidents","Reduces cost of operation","Replaces all training","Supports certification"],"answerIndex":2,"explanation":"Measurement does not replace training.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which improvement cycle is recommended for biorisk systems?","options":["One-off review","PDCA continuous improvement","Annual shredding","Random changes"],"answerIndex":1,"explanation":"PDCA is recommended.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"The lecture recalls the AMP model under which heading?","options":["Recap","Introduction only","Conclusion only","Appendix"],"answerIndex":0,"explanation":"The recap introduces AMP.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which best summarises the lecture's message?","options":["Performance is measured by luck","Measure intended vs observed outcomes, act on gaps, and improve continuously","Performance needs no data","Only top managers matter"],"answerIndex":1,"explanation":"That is the core message.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which of these would show a sustained high performance?","options":["One good month","Continual monitoring and improvement over time","A single audit","Zero records"],"answerIndex":1,"explanation":"Sustained performance needs continual effort.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which step in the M. tuberculosis example is an assessment step?","options":["Post-project screening","An SOP for PPE use","Preliminary health screening","Output report"],"answerIndex":2,"explanation":"Screening identifies risk before work.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which would be correct for an IO of 'spills: 0' and an OO of 0?","options":["Revise SOP","Target met; no corrective action needed","Close the lab","Retrain all staff"],"answerIndex":1,"explanation":"No gap, no corrective action needed.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"The 'Plan' step should include:","options":["Only buying equipment","Identifying hazards and risks and establishing goals","Only training","Only auditing"],"answerIndex":1,"explanation":"Plan sets up the system.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"The 'Check' step includes:","options":["Monitoring and corrective action","Writing the SOP","Buying PPE","Designing the lab"],"answerIndex":0,"explanation":"Monitoring and correction.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which is the main reason for a PDCA approach?","options":["To repeat the same tasks","To keep improving the system continuously","To avoid all changes","To reduce data"],"answerIndex":1,"explanation":"PDCA drives continuous improvement.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"An intended outcome is 'spills: 0' and the observed outcome is 2. The performance is:","options":["Met","Not met, so corrective action is needed","Not measurable","Irrelevant"],"answerIndex":1,"explanation":"Observed differs from intended, so action is needed.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"An observed outcome is best described as:","options":["The target set in advance","What was actually seen when the system was measured","The cost of controls","The staff list"],"answerIndex":1,"explanation":"Observed outcomes are the actual results.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which is the first step that leads to control and eventually to improvement?","options":["Measurement","Punishment","Auditing alone","Hiring"],"answerIndex":0,"explanation":"Measurement is the first step, per the Harrington quote in the lecture.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which benefit of performance measurement supports certification or accreditation?","options":["Providing a demonstrable record of performance","Increasing lab noise","Reducing training","Removing audits"],"answerIndex":0,"explanation":"A demonstrable record can support certification or accreditation.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Why does a sustained level of biorisk performance require continual effort?","options":["Because performance changes over time","Because the lab never has staff","Because PPE expires daily","Because audits are forbidden"],"answerIndex":0,"explanation":"Performance changes over time, so it needs ongoing effort.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"The management review of the biorisk system should assess:","options":["Opportunities for improvement and the need for changes to procedures, policies and objectives","Only the price of gloves","Only staff birthdays","Only parking"],"answerIndex":0,"explanation":"Top management reviews improvement opportunities and needed changes.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"In the TB example, the output 'one of five workers tested positive' shows that:","options":["The output matches the intended outcome","The output does not match the intended outcome","The process is complete and perfect","Nothing can be learned"],"answerIndex":1,"explanation":"The desired output was no positive results, so the process needs review.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"In a basic process check, which question asks whether the steps are physically possible?","options":["Output question","Steps question","Input question only","Budget question"],"answerIndex":1,"explanation":"The steps must be physically possible and the right steps.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which PDCA step includes process innovation and making needed changes to the management system?","options":["Plan","Do","Check","Act"],"answerIndex":3,"explanation":"Act reviews and makes the needed changes.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Which PDCA step covers training and operational issues?","options":["Plan","Do","Check","Act"],"answerIndex":1,"explanation":"Do includes implementation, training and operational issues.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Measurement and analysis must ensure appropriate data are collected and analysed to:","options":["Assess suitability and effectiveness of the system","Pay salaries","Decorate the lab","Replace staff"],"answerIndex":0,"explanation":"Data show whether the system is suitable and effective.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"Measuring performance can help to:","options":["Save money and time by prioritising resources","Increase operating costs","Reduce all controls","Eliminate PDCA"],"answerIndex":0,"explanation":"Measurement enables resource prioritisation.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"},{"question":"A laboratory wants to find where continual improvement can be made. Which tool is most suitable?","options":["Performance measurement and analysis","Guessing","Ignoring incidents","Doubling staff"],"answerIndex":0,"explanation":"Performance measurement and analysis finds where the system can improve.","topic":"Lecture 9: Biorisk Performance, AMP Model and Evaluation"}]},{"id":"mls101-lecture-10","order":10,"title":"Lecture 10: Laboratory Quality Management System","notesHtml":"<div class=\"card\">\n    <h2>1. What is a Laboratory QMS?</h2>\n    <p>A standardised procedure and practice that contributes to the overall <b>biosafety, biosecurity and quality</b> of laboratory test results. It is a set of building blocks used to control, assure and manage the quality of the laboratory's processes.</p>\n    <ul>\n      <li>It helps protect staff safety, patient satisfaction and regulatory compliance, and makes processes more efficient.</li>\n      <li>Quality must cover every area: environment, procedures, record keeping, human resources, reagents, equipment and instruments.</li>\n      <li>The framework used here is <b>12 building blocks</b>, called <b>Quality System Essentials (QSEs)</b>, described by CLSI.</li>\n    </ul>\n    <p class=\"key\">An ISO standard adopted by all member countries applies to the laboratory QMS. ISO itself does not carry out accreditation. It develops the standards.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>2. The two ISO standards</h2>\n    <table>\n      <tr><th>Standard</th><th>Scope</th></tr>\n      <tr><td><b>ISO 15189</b></td><td>Medical laboratories: requirements for quality and competence</td></tr>\n      <tr><td><b>ISO 17025</b></td><td>Testing and calibration laboratories; lets a calibration laboratory prove the accuracy of its results</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>3. The 12 Quality System Essentials</h2>\n    <table>\n      <tr><th>#</th><th>QSE</th><th>Key points</th></tr>\n      <tr><td>1</td><td><b>Organisation</b></td><td>Clear structure and an organogram showing who is responsible for what and who reports to whom. Covers leadership, planning, implementation and monitoring for continuous improvement.</td></tr>\n      <tr><td>2</td><td><b>Personnel</b></td><td>Right qualifications and clear job descriptions. Training and competency assessment at the start of employment and regularly after. Motivated staff perform best; staff make the final decisions on methods and results.</td></tr>\n      <tr><td>3</td><td><b>Equipment</b></td><td>Selection, installation, calibration, maintenance and troubleshooting, and validation before use. A logbook records the test, the operator, the last maintenance date and more.</td></tr>\n      <tr><td>4</td><td><b>Purchasing and inventory</b></td><td>Right products from the right suppliers. Good inventory management prevents interruptions.</td></tr>\n      <tr><td>5</td><td><b>Process control</b></td><td>Checks along the pre-analytical, analytical and post-analytical phases. Includes method verification, process validation, internal quality control, sample collection and sample handling.</td></tr>\n      <tr><td>6</td><td><b>Information management</b></td><td>Accuracy, security, confidentiality and privacy of patient data and lab data, with access for people with the right privileges.</td></tr>\n      <tr><td>7</td><td><b>Documents and records</b></td><td>A cornerstone of the QMS. SOPs must be available at the point of work, current, accurate and secure.</td></tr>\n      <tr><td>8</td><td><b>Occurrence management</b></td><td>Any error or non-conformance is investigated. Root cause analysis leads to Corrective and Preventive Actions (CAPAs).</td></tr>\n      <tr><td>9</td><td><b>Assessment</b></td><td>Internal and external monitoring and audits check that processes meet requirements. Internal audits find weaknesses; external audits support accreditation, certification or licensure.</td></tr>\n      <tr><td>10</td><td><b>Process improvement</b></td><td>Continuous improvement, ideally proactive as well as reactive. Techniques include audits, external quality assessment and management review.</td></tr>\n      <tr><td>11</td><td><b>Customer service</b></td><td>The ultimate goal of the lab. Understand customers and their needs, measure satisfaction (surveys, indicators, audits) and use feedback to improve.</td></tr>\n      <tr><td>12</td><td><b>Facilities and safety</b></td><td>A safe, secure and clean environment, including containment, worker safety and ergonomics. The lab head is responsible for safety and quality.</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>4. Process improvement in detail (ISO 15189)</h2>\n    <p>The continual improvement process should:</p>\n    <ol>\n      <li>Identify potential sources of system weakness or error</li>\n      <li>Develop plans to implement improvement</li>\n      <li>Implement the plan</li>\n      <li>Review the effectiveness of the action</li>\n      <li>Adjust the action plan and modify the system after review and audit results</li>\n    </ol>\n    <p class=\"key\">A proactive approach (finding improvements before something goes wrong) is preferred to a purely reactive one.</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>5. Occurrence management and CAPA</h2>\n    <ul>\n      <li>An <b>occurrence</b> is any action or event that can harm staff, performance, equipment or the environment. It includes errors and near misses in testing or communication.</li>\n      <li>All deviations that affect lab operations are investigated.</li>\n      <li>Investigation looks for the <b>root cause</b>, which prevents recurrence.</li>\n      <li>Found occurrences are fixed through <b>Corrective and Preventive Actions (CAPAs)</b>.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>6. Internal vs external audit</h2>\n    <table>\n      <tr><th></th><th>Internal audit</th><th>External audit</th></tr>\n      <tr><td><b>Who</b></td><td>Lab's own staff; people from one area audit another</td><td>External professionals and experts</td></tr>\n      <tr><td><b>Purpose</b></td><td>Identify potential weaknesses</td><td>Accreditation, certification or licensure</td></tr>\n    </table>\n  </div>\n\n  <div class=\"card\">\n    <h2>7. Facilities and safety essentials</h2>\n    <ul>\n      <li>Physically secured lab, with containment procedures for hazards, worker safety and ergonomics.</li>\n      <li>Adequate supply of: PPE, fire extinguishers, safe storage for flammable and toxic chemicals, eye washers and emergency showers, waste disposal supplies, first aid equipment.</li>\n      <li>A waste management system must dispose of harmful contaminated waste safely.</li>\n      <li>The lab head must take part in lab design, assess all potential risks and give feedback on building a safe lab.</li>\n    </ul>\n  </div>\n\n  <div class=\"card\">\n    <h2>Summary: key takeaways</h2>\n    <ul>\n      <li>The QMS is a set of building blocks that controls and assures quality.</li>\n      <li>There are <b>12 QSEs</b>. Know all of them by name.</li>\n      <li>ISO 15189 applies to medical labs; ISO 17025 to testing and calibration labs.</li>\n      <li>Investigate occurrences to the root cause, then apply CAPA.</li>\n      <li>Internal audits find weaknesses; external audits support accreditation.</li>\n      <li>Customer service is the ultimate goal of the laboratory.</li>\n    </ul>\n  </div>","flashcards":[{"front":"What is a Laboratory Quality Management System (LQMS)?","back":"A standardised procedure and practice that contributes to the biosafety, biosecurity and quality of laboratory test results.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"What does an LQMS help ensure?","back":"Staff safety, patient satisfaction, regulatory compliance and more efficient processes.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"What are the building blocks of the QMS framework used here?","back":"The 12 Quality System Essentials (QSEs).","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"Who described the 12 QSEs?","back":"CLSI (Clinical and Laboratory Standards Institute).","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"Which ISO standard applies to medical laboratories?","back":"ISO 15189: quality and competence in medical laboratories.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"Which ISO standard applies to testing and calibration laboratories?","back":"ISO 17025.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"Does ISO carry out accreditation?","back":"No. ISO develops standards; it does not perform accreditation.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"QSE 1: Organisation covers what?","back":"Clear structure and an organogram of responsibility, plus leadership, planning, implementation and monitoring.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"QSE 2: Personnel covers what?","back":"Qualifications, job descriptions, training and competency assessment, and staff motivation.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"QSE 3: Equipment covers what?","back":"Selection, installation, calibration, maintenance, troubleshooting, validation and equipment logbooks.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"QSE 4: Purchasing and inventory covers what?","back":"Right products from the right suppliers, and inventory management to avoid interruptions.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"QSE 5: Process control covers what?","back":"Checks through the pre-analytical, analytical and post-analytical phases, including IQC and method validation.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"QSE 6: Information management covers what?","back":"Accuracy, security, confidentiality and privacy of data, with access by right privilege.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"QSE 7: Documents and records covers what?","back":"SOPs and records that are available at the point of work, current, accurate and secure.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"QSE 8: Occurrence management covers what?","back":"Investigating errors and non-conformances, root cause analysis, and CAPA.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"QSE 9: Assessment covers what?","back":"Internal and external monitoring and audits to verify that processes meet requirements.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"QSE 10: Process improvement covers what?","back":"Continuous improvement through audits, external quality assessment and management review.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"QSE 11: Customer service covers what?","back":"Understanding customers, measuring satisfaction and using feedback to improve.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"QSE 12: Facilities and safety covers what?","back":"A safe, secure, clean environment with containment, worker safety and ergonomics.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"What is an occurrence?","back":"Any action or event that can harm staff, performance, equipment or the environment, including errors and near misses.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"What is root cause analysis for?","back":"To find the underlying cause so the problem does not recur.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"What is a CAPA?","back":"Corrective and Preventive Action, taken to fix an occurrence and prevent it happening again.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"What is an internal audit?","back":"An audit by the lab's own staff, to identify potential weaknesses.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"What is an external audit for?","back":"Accreditation, certification or licensure, performed by external professionals.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"Name the five steps of the continual improvement process.","back":"Identify weaknesses, develop plans, implement, review effectiveness, adjust the plan and system.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"Is a proactive or reactive approach preferred for improvement?","back":"Proactive. Find opportunities before something goes wrong.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"Who is responsible for lab safety and quality?","back":"The laboratory head.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"Name the safety supplies a lab must have.","back":"PPE, fire extinguishers, chemical storage, eye washers and emergency showers, waste disposal supplies, first aid equipment.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"What should a logbook for equipment record?","back":"The test performed, the person performing it, the date of last maintenance and more.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"Why do SOPs matter in the QMS?","back":"They create a standard for each process and are a cornerstone of the QMS.","topic":"Lecture 10: Laboratory Quality Management System"},{"front":"Who ultimately benefits from the QMS?","back":"Customers, the patients; customer service is the ultimate goal of a lab.","topic":"Lecture 10: Laboratory Quality Management System"}],"questions":[{"question":"A Laboratory Quality Management System is best described as:","options":["A set of building blocks to control, assure and manage quality","A type of PPE","A laboratory building plan","A staff payroll"],"answerIndex":0,"explanation":"It is the framework of building blocks for quality.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"An LQMS contributes to which three areas?","options":["Biosafety, biosecurity and quality of results","Cost, speed and size","Art, music and design","Transport, storage and sales"],"answerIndex":0,"explanation":"The lecture links QMS to biosafety, biosecurity and quality.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which benefit does an LQMS provide to staff?","options":["Higher salaries","Staff safety","More patients only","Fewer tests"],"answerIndex":1,"explanation":"Staff safety is one of the stated benefits.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"How many building blocks (QSEs) are in the framework used?","options":["8","10","12","15"],"answerIndex":2,"explanation":"There are 12 Quality System Essentials.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Who described the Quality System Essentials?","options":["WHO","CLSI","ISO itself","NAFDAC"],"answerIndex":1,"explanation":"CLSI described the QSEs.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"ISO 15189 applies to:","options":["Medical laboratories","Food factories","Banks","Schools"],"answerIndex":0,"explanation":"ISO 15189 is for medical laboratories.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"ISO 17025 applies to:","options":["Testing and calibration laboratories","Hospitals only","Pharmacies only","Schools"],"answerIndex":0,"explanation":"It is for testing and calibration labs.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which is correct about ISO?","options":["ISO performs accreditation","ISO develops standards and does not accredit","ISO runs audits","ISO is a hospital"],"answerIndex":1,"explanation":"ISO develops standards.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"QSE 1, Organisation, requires:","options":["An organogram showing responsibility and reporting lines","A new building","Free tests","Unlimited staff"],"answerIndex":0,"explanation":"An organogram shows structure.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE covers competency assessment and job descriptions?","options":["Personnel","Equipment","Purchasing","Customer service"],"answerIndex":0,"explanation":"Personnel covers job descriptions and competency.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Training and competency assessment should happen:","options":["Only once","At the beginning and regularly after","Only when a complaint arrives","Never"],"answerIndex":1,"explanation":"It is required at start and regularly.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Equipment validation should take place:","options":["After it is broken","Before the equipment goes into operation","Once in ten years","Never"],"answerIndex":1,"explanation":"Validation comes before use.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE covers calibration and preventive maintenance?","options":["Equipment","Customer service","Documents","Assessment"],"answerIndex":0,"explanation":"Equipment covers calibration and maintenance.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"A logbook for equipment should record:","options":["Only the price","The test, the operator and last maintenance date","Only the colour","Nothing"],"answerIndex":1,"explanation":"Logbooks record key details.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE covers choosing products and suppliers?","options":["Purchasing and inventory","Information management","Process control","Facilities"],"answerIndex":0,"explanation":"Purchasing covers suppliers and stock.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Good inventory management ensures:","options":["Excess stock always","Uninterrupted service","No supplies","Random ordering"],"answerIndex":1,"explanation":"Supplies are available when needed.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Process control checks which phases?","options":["Only analytical","Pre-analytical, analytical and post-analytical","Only post-analytical","Only financial"],"answerIndex":1,"explanation":"All three phases are checked.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which is part of process control?","options":["Method verification","Buying furniture","Painting walls","Choosing uniforms"],"answerIndex":0,"explanation":"Method verification is process control.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Internal quality control is an example of:","options":["A process control measure","A finance measure","A staff hobby","A facility decor"],"answerIndex":0,"explanation":"IQC is a process control measure.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE protects patient confidentiality?","options":["Information management","Equipment","Purchasing","Facilities"],"answerIndex":0,"explanation":"Information management covers privacy.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE covers SOP availability at the point of work?","options":["Documents and records","Personnel","Customer service","Assessment"],"answerIndex":0,"explanation":"SOPs are documents.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Why are documents called a cornerstone of the QMS?","options":["They are expensive","They ensure standardisation, which is paramount to quality","They replace staff","They are optional"],"answerIndex":1,"explanation":"Standardisation drives quality.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"What is an occurrence?","options":["A good result","Any error or non-conformance","Only a machine failure","Only a staff holiday"],"answerIndex":1,"explanation":"Occurrence includes any error or non-conformance.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE covers investigating errors and non-conformances?","options":["Occurrence management","Customer service","Purchasing","Personnel"],"answerIndex":0,"explanation":"Occurrence management covers this.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Investigation of an occurrence should find:","options":["The person to blame","The root cause","The cheapest fix","Nothing"],"answerIndex":1,"explanation":"Root cause prevents recurrence.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"CAPA stands for:","options":["Corrective and Preventive Action","Central Audit and Planning Authority","Clinical and Pathology Analysis","Client Acceptance and Payment Agreement"],"answerIndex":0,"explanation":"CAPA is corrective and preventive action.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE covers internal and external audits?","options":["Assessment","Purchasing","Facilities","Equipment"],"answerIndex":0,"explanation":"Assessment covers audits.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Internal audits are carried out by:","options":["External experts only","The lab's own people, often from another area","Patients","Suppliers"],"answerIndex":1,"explanation":"Internal audits use own staff.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"The main purpose of internal audits is to:","options":["Accredit the lab","Identify potential weaknesses","Sell equipment","Hire staff"],"answerIndex":1,"explanation":"Internal audits identify weaknesses.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"External audits are used for:","options":["Accreditation, certification or licensure","Choosing lunch","Hiring cleaners","Designing posters"],"answerIndex":0,"explanation":"External audits serve formal recognition.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE covers continuous improvement?","options":["Process improvement","Purchasing","Facilities","Information"],"answerIndex":0,"explanation":"Process improvement is continuous.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which technique is useful for process improvement?","options":["External quality assessment","Painting","Ignoring data","Random purchasing"],"answerIndex":0,"explanation":"EQA helps improvement.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Management review is useful because it:","options":["Hides data","Looks at all gathered data to decide actions","Stops improvement","Replaces audits"],"answerIndex":1,"explanation":"Management review uses the data.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE covers customer satisfaction?","options":["Customer service","Equipment","Purchasing","Documents"],"answerIndex":0,"explanation":"Customer service measures satisfaction.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which tool can measure customer satisfaction?","options":["Surveys, indicators and audits","Only the price list","Only the weather","Only the lab's logo"],"answerIndex":0,"explanation":"Surveys, indicators and audits measure it.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Who is responsible for measuring customer satisfaction?","options":["Cleaners","The laboratory head","Patients","Suppliers"],"answerIndex":1,"explanation":"The lab head is responsible.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE covers containment and worker safety?","options":["Facilities and safety","Purchasing","Personnel","Customer service"],"answerIndex":0,"explanation":"Facilities and safety covers containment.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which safety supply is required by the lecture?","options":["Fire extinguishers","Decorative plants","Music systems","Coffee machines"],"answerIndex":0,"explanation":"Fire extinguishers are required.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Eye washers and emergency showers are part of:","options":["Facilities and safety","Purchasing","Information management","Customer service"],"answerIndex":0,"explanation":"They are safety equipment.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Who must take part in designing a safe lab?","options":["Only the cleaner","The laboratory head","Only students","Only patients"],"answerIndex":1,"explanation":"The lab head must participate.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"A waste management system must:","options":["Ignore harmful waste","Dispose of harmful contaminated waste safely","Store waste forever","Burn everything at the bench"],"answerIndex":1,"explanation":"Safe disposal is required.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Chemicals that are flammable or toxic must be:","options":["Stored in the open","Appropriately stored","Thrown away","Mixed"],"answerIndex":1,"explanation":"They need appropriate storage.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"The lecture says the ultimate goal of a laboratory is:","options":["Profit","Customer service","Size","Paper"],"answerIndex":1,"explanation":"Customer service is the ultimate goal.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"In ISO 15189's continual improvement process, the step after implementing the plan is:","options":["Identify weakness","Review the effectiveness of the action","Buy equipment","Close the lab"],"answerIndex":1,"explanation":"Review follows implementation.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which is the correct order for improvement?","options":["Implement, identify, review, adjust","Identify, develop plan, implement, review effectiveness, adjust","Review, adjust, identify, implement","Adjust, implement, review, identify"],"answerIndex":1,"explanation":"This is the ISO 15189 sequence.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which is a proactive improvement approach?","options":["Waiting for a complaint","Finding improvement opportunities before anything goes wrong","Ignoring audits","Closing records"],"answerIndex":1,"explanation":"Proactive means finding issues early.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which is part of the organisation QSE?","options":["Leadership and planning","Customer discounts","Equipment brands","Ice-cream sales"],"answerIndex":0,"explanation":"Leadership and planning are part of Organisation.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE covers reagents and quality of inputs?","options":["Purchasing and inventory","Customer service","Assessment","Information"],"answerIndex":0,"explanation":"Purchasing covers reagent quality.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE is the 'ultimate goal' of the lab, according to the lecture?","options":["Customer service","Documents","Equipment","Purchasing"],"answerIndex":0,"explanation":"Customer service is the ultimate goal.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE links directly to accreditation evidence through records?","options":["Documents and records","Customer service only","Purchasing only","Facilities only"],"answerIndex":0,"explanation":"Records provide evidence for audits.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which best describes 'occurrence management'?","options":["A focus on continual improvement by investigating errors","A focus on marketing","A focus on hiring","A focus on decoration"],"answerIndex":0,"explanation":"It is about investigating and improving.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which of the following is an example of an occurrence?","options":["A near miss in testing","A successful audit","A completed training","A clean record"],"answerIndex":0,"explanation":"Near misses are occurrences.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Information management includes:","options":["Only printing","Accuracy, security, confidentiality and access by right privilege","Only colour coding","Only storage space"],"answerIndex":1,"explanation":"These are the stated principles.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Why is quality needed in all lab practices?","options":["Only to pass exams","Because the QMS requires quality in environment, procedures, records, staff, reagents and equipment","Because it is cheaper","Because patients ask"],"answerIndex":1,"explanation":"The lecture lists these areas.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"The lab QMS is best seen as:","options":["A one-off project","A continuous system of building blocks","A single document","A staff uniform policy"],"answerIndex":1,"explanation":"It is an ongoing system.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which is a correct pairing?","options":["QSE 12: Facilities and safety","QSE 1: Purchasing","QSE 9: Customer service","QSE 6: Equipment"],"answerIndex":0,"explanation":"QSE 12 is facilities and safety.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which pairing is correct?","options":["QSE 10: Process improvement","QSE 3: Assessment","QSE 7: Personnel","QSE 11: Equipment"],"answerIndex":0,"explanation":"QSE 10 is process improvement.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE is about staff making decisions on methods and results?","options":["Personnel","Purchasing","Facilities","Customer"],"answerIndex":0,"explanation":"Staff make the ultimate decisions on methods and results.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE is most directly responsible for equipment logbooks and calibration?","options":["Equipment","Customer service","Purchasing","Assessment"],"answerIndex":0,"explanation":"Equipment covers calibration, maintenance and logbooks.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"An occurrence includes which of the following?","options":["Near misses in testing or communication","Only machine breakdowns","Only patient complaints","Only staff holidays"],"answerIndex":0,"explanation":"Occurrences include errors and near misses in testing or communication.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"A near miss in testing is best described as:","options":["An occurrence","A customer survey","An external audit","A calibration certificate"],"answerIndex":0,"explanation":"A near miss is an occurrence.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which ISO standard is developed for laboratories that perform calibration and testing?","options":["ISO 15189","ISO 17025","ISO 9001","ISO 27001"],"answerIndex":1,"explanation":"ISO 17025 is for testing and calibration labs.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which audit is carried out by people working in one area auditing another area?","options":["External audit","Internal audit","Accreditation audit","Licensure audit"],"answerIndex":1,"explanation":"Internal audits are carried out by the lab's own people.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"What is the first step of the continual improvement process under ISO 15189?","options":["Review effectiveness","Identify potential sources of system weakness or error","Close the lab","Buy new equipment"],"answerIndex":1,"explanation":"Identify weaknesses first, then plan, implement and review.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which QSE covers the control of pre-analytical, analytical and post-analytical phases?","options":["Process control","Customer service","Facilities and safety","Purchasing"],"answerIndex":0,"explanation":"Process control checks each phase of testing.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"The laboratory head is responsible for:","options":["Ensuring and measuring customer satisfaction","Cleaning the bench","Choosing lunch","Printing forms"],"answerIndex":0,"explanation":"The lab head is responsible for measuring customer satisfaction.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Why must a QMS include a safe waste management system?","options":["It is optional","Harmful contaminated waste must be disposed of safely","It replaces audits","It only applies to chemicals"],"answerIndex":1,"explanation":"Safe disposal of harmful contaminated waste is required.","topic":"Lecture 10: Laboratory Quality Management System"},{"question":"Which technique is useful for process improvement?","options":["Management review of all data gathered","Ignoring data","Random purchasing","Staff turnover"],"answerIndex":0,"explanation":"Management review of gathered data supports improvement.","topic":"Lecture 10: Laboratory Quality Management System"}]}]};
